"use client";

import { motion, useReducedMotion } from "framer-motion";

export function PrimaryButton({ children }: { children: React.ReactNode }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.button
      whileHover={shouldReduceMotion ? undefined : { y: -2 }}
      whileTap={{ scale: 0.96, y: 0 }}
      transition={{ type: "spring", stiffness: 500, damping: 30 }}
      className="group relative inline-flex items-center justify-center overflow-hidden rounded-lg bg-emerald-700 px-5 py-2.5 text-sm font-medium text-white shadow-[0_1px_2px_rgba(4,120,87,0.3)] transition-[box-shadow,background-color] duration-300 hover:bg-emerald-600 hover:shadow-[0_12px_24px_-8px_rgba(4,120,87,0.65)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-700 active:bg-emerald-800 dark:bg-emerald-500 dark:shadow-[0_1px_2px_rgba(16,185,129,0.35)] dark:hover:bg-emerald-400 dark:hover:shadow-[0_12px_24px_-8px_rgba(16,185,129,0.55)] dark:focus-visible:outline-emerald-400 dark:active:bg-emerald-600"
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/30 to-transparent transition-transform duration-700 ease-out group-hover:translate-x-full motion-reduce:hidden"
      />
      <span className="relative">{children}</span>
    </motion.button>
  );
}

export function GhostButton({ children }: { children: React.ReactNode }) {
  return (
    <button className="group relative inline-flex items-center justify-center overflow-hidden rounded-lg border border-slate-300 px-5 py-2.5 text-sm font-medium text-slate-700 transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 active:scale-[0.97] dark:border-slate-600 dark:text-slate-200">
      <span
        aria-hidden
        className="absolute inset-0 origin-left scale-x-0 bg-slate-900 transition-transform duration-300 ease-out group-hover:scale-x-100 motion-reduce:transition-none dark:bg-white"
      />
      <span className="relative transition-colors duration-300 group-hover:text-white dark:group-hover:text-slate-900">
        {children}
      </span>
    </button>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

export function ToggleSwitch({ label }: { label: string }) {
  const [checked, setChecked] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  return (
    <label className="flex items-center gap-3 cursor-pointer select-none">
      <motion.button
        role="switch"
        aria-checked={checked}
        onClick={() => setChecked((v) => !v)}
        whileTap={{ scale: 0.93 }}
        className={`relative h-6 w-11 shrink-0 rounded-full transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
          checked ? "bg-emerald-600" : "bg-slate-300 dark:bg-slate-600"
        }`}
      >
        <motion.span
          animate={{ x: checked ? 22 : 2 }}
          transition={
            shouldReduceMotion
              ? { duration: 0 }
              : { type: "spring", stiffness: 700, damping: 32 }
          }
          className="absolute top-0.5 block h-5 w-5 rounded-full bg-white shadow-md"
        />
      </motion.button>
      <span className="text-sm text-slate-700 dark:text-slate-200">{label}</span>
    </label>
  );
}

export function TextField({ label }: { label: string }) {
