        type="text"
        placeholder=" "
        className="peer w-full rounded-lg border border-slate-300 bg-white px-3.5 pb-2 pt-5 text-sm text-slate-900 outline-none transition-colors focus:border-amber-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-600 dark:border-slate-600 dark:bg-neutral-950 dark:text-white"
      />
      <label
        htmlFor="text-field"
        className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-sm text-slate-400 transition-all duration-200 ease-out peer-focus:top-3.5 peer-focus:text-xs peer-focus:text-amber-700 peer-[:not(:placeholder-shown)]:top-3.5 peer-[:not(:placeholder-shown)]:text-xs peer-[:not(:placeholder-shown)]:text-slate-500 dark:peer-[:not(:placeholder-shown)]:text-slate-400"
      >
        {label}
      </label>
      <span className="pointer-events-none absolute inset-x-3.5 bottom-1.5 h-px origin-left scale-x-0 bg-amber-500 transition-transform duration-300 ease-out peer-focus:scale-x-100" />
    </div>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export function IconButton({
  icon,
  label,
  onClick,
}: {
  icon: ReactNode;
  label: string;
  onClick?: () => void;
}) {
  const [hovered, setHovered] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="relative inline-flex">
      <motion.button
        type="button"
        aria-label={label}
        onClick={onClick}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onFocus={() => setHovered(true)}
        onBlur={() => setHovered(false)}
        whileHover={shouldReduceMotion ? undefined : { y: -2 }}
        whileTap={shouldReduceMotion ? { scale: 0.94 } : { scale: 0.9, rotate: [0, -10, 8, -4, 0] }}
        transition={{ type: "spring", stiffness: 500, damping: 30 }}
        className="inline-flex h-10 w-10 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-600 shadow-sm transition-colors hover:border-emerald-300 hover:text-emerald-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:bg-neutral-950 dark:text-slate-300 dark:hover:text-emerald-400"
      >
        {icon}
      </motion.button>
      <AnimatePresence>
        {hovered && (
          <motion.span
            role="tooltip"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, scale: 0.9 }}
            transition={{ type: "spring", stiffness: 500, damping: 32 }}
            className="pointer-events-none absolute -top-9 left-1/2 -translate-x-1/2 whitespace-nowrap rounded-md bg-slate-900 px-2 py-1 text-xs font-medium text-white dark:bg-slate-100 dark:text-slate-900"
          >
            {label}
            <span aria-hidden className="absolute left-1/2 top-full -mt-1 h-2 w-2 -translate-x-1/2 rotate-45 bg-slate-900 dark:bg-slate-100" />
          </motion.span>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export function Select({ options, label }: { options: string[]; label: string }) {
  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useState(0);
  const [highlighted, setHighlighted] = useState(0);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      if (!open) return setOpen(true);
      setHighlighted((h) => Math.min(h + 1, options.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlighted((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (open) {
        setSelected(highlighted);
        setOpen(false);
      } else {
        setOpen(true);
      }
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  };

  return (
    <div ref={rootRef} className="relative w-full max-w-xs">
      <button
        type="button"
        role="combobox"
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-label={label}
        onClick={() => {
          setOpen((v) => !v);
          setHighlighted(selected);
        }}
        onKeyDown={handleKeyDown}
        className="flex w-full items-center justify-between gap-2 rounded-lg border border-slate-300 bg-white px-3.5 py-2.5 text-sm text-slate-900 outline-none transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-500 dark:border-slate-600 dark:bg-neutral-950 dark:text-white"
      >
        <span>{options[selected]}</span>
        <motion.svg
          animate={{ rotate: open ? 180 : 0 }}
          transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 30 }}
          viewBox="0 0 24 24"
          width="16"
          height="16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
          className="shrink-0 text-slate-400"
        >
          <path d="m6 9 6 6 6-6" />
        </motion.svg>
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { height: { duration: 0.22, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.15 } }
            }
            className="mt-1.5 w-full overflow-hidden rounded-lg border border-slate-200 bg-white shadow-lg dark:border-slate-700 dark:bg-neutral-950"
          >
            <ul role="listbox" className="scrollbar-thin max-h-32 overflow-y-auto p-1">
            {options.map((option, i) => (
              <motion.li
                key={option}
                role="option"
                aria-selected={selected === i}
                initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, x: -4 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: shouldReduceMotion ? 0 : i * 0.03, duration: 0.15 }}
                onMouseEnter={() => setHighlighted(i)}
                onClick={() => {
                  setSelected(i);
                  setOpen(false);
                }}
                className="relative cursor-pointer rounded-md px-3 py-2 text-sm"
              >
                {highlighted === i && (
                  <motion.span
                    layoutId="select-highlight"
                    className="absolute inset-0 rounded-md bg-amber-50 dark:bg-amber-500/10"
                    transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 600, damping: 40 }}
                  />
                )}
                <span
                  className={`relative flex items-center justify-between ${
                    highlighted === i ? "text-amber-700 dark:text-amber-400" : "text-slate-700 dark:text-slate-300"
                  }`}
                >
                  {option}
                  {selected === i && <span aria-hidden>✓</span>}
                </span>
              </motion.li>
            ))}
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

const TICK_ANGLES = [-60, -10, 45, 100] as const;

export function Checkbox({ label }: { label: string }) {
  const [checked, setChecked] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  return (
    <label className="flex cursor-pointer select-none items-center gap-3">
      <span className="relative inline-flex">
        <motion.button
          type="button"
          role="checkbox"
          aria-checked={checked}
          onClick={() => setChecked((v) => !v)}
          whileTap={{ scale: 0.88 }}
          animate={checked && !shouldReduceMotion ? { scale: [1, 1.15, 1] } : { scale: 1 }}
          transition={{ type: "spring", stiffness: 500, damping: 22 }}
          className={`flex h-5 w-5 items-center justify-center rounded-md border-2 transition-colors duration-200 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-700 ${
            checked ? "border-emerald-700 bg-emerald-700" : "border-slate-300 bg-white dark:border-slate-600 dark:bg-neutral-950"
          }`}
        >
          <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <motion.path
              d="M3 8.5l3 3 7-7.5"
              initial={{ pathLength: 0, opacity: 0 }}
              animate={checked ? { pathLength: 1, opacity: 1 } : { pathLength: 0, opacity: 0 }}
              transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
            />
          </svg>
        </motion.button>
        {!shouldReduceMotion &&
          checked &&
          TICK_ANGLES.map((deg) => {
            const rad = (deg * Math.PI) / 180;
            return (
              <motion.span
                key={deg}
                aria-hidden
                className="absolute h-1 w-1 rounded-full bg-emerald-400"
                style={{ top: "50%", left: "50%", marginLeft: -2, marginTop: -2 }}
                initial={{ x: 0, y: 0, opacity: 1, scale: 1 }}
                animate={{ x: Math.cos(rad) * 16, y: Math.sin(rad) * 16, opacity: 0, scale: 0.4 }}
                transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
              />
            );
          })}
      </span>
      <span className="text-sm text-slate-700 dark:text-slate-200">{label}</span>
    </label>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

const COLOR_STOPS: [number, [number, number, number]][] = [
  [0, [4, 120, 87]], // emerald-700
  [50, [52, 211, 153]], // emerald-400
  [100, [245, 158, 11]], // amber-500
];

function trackColor(value: number): [number, number, number] {
  const v = Math.min(100, Math.max(0, value));
  let [lowerP, lowerC] = COLOR_STOPS[0];
  let [upperP, upperC] = COLOR_STOPS[COLOR_STOPS.length - 1];
  for (let i = 0; i < COLOR_STOPS.length - 1; i++) {
    if (v >= COLOR_STOPS[i][0] && v <= COLOR_STOPS[i + 1][0]) {
      [lowerP, lowerC] = COLOR_STOPS[i];
      [upperP, upperC] = COLOR_STOPS[i + 1];
      break;
    }
  }
  const t = (v - lowerP) / (upperP - lowerP || 1);
  return lowerC.map((c, i) => Math.round(c + (upperC[i] - c) * t)) as [number, number, number];
}

const TICKS = [0, 25, 50, 75, 100];

export function Slider({ label, initial = 40 }: { label: string; initial?: number }) {
  const [value, setValue] = useState(initial);
  const [dragging, setDragging] = useState(false);
  const [focused, setFocused] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  const [r, g, b] = trackColor(value);
  const accent = `rgb(${r}, ${g}, ${b})`;
  const accentGlow = `rgba(${r}, ${g}, ${b}, 0.22)`;

  return (
    <div className="w-full max-w-xs">
      <div className="mb-2 flex items-center justify-between text-sm text-slate-600 dark:text-slate-300">
        <span>{label}</span>
        <span className="tabular-nums text-slate-400 dark:text-slate-500">{value}%</span>
      </div>
      <div className="relative flex h-5 items-center">
        <div className="relative h-1.5 w-full overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
          <motion.div
            className="h-full rounded-full"
            style={{
              backgroundImage: "linear-gradient(to right, #047857, #34d399, #f59e0b)",
              backgroundSize: `${(100 / Math.max(value, 1)) * 100}% 100%`,
            }}
            animate={{ width: `${value}%` }}
            transition={dragging || shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 400, damping: 35 }}
          />
          <div className="pointer-events-none absolute inset-0 flex items-center justify-between px-0.5">
            {TICKS.map((tick) => (
              <span
                key={tick}
                className={`h-1 w-1 rounded-full transition-colors duration-300 ${
                  value >= tick ? "bg-white/70" : "bg-slate-400/60 dark:bg-slate-500/60"
                }`}
              />
            ))}
          </div>
        </div>
        <input
          type="range"
          min={0}
          max={100}
          value={value}
          onChange={(e) => setValue(Number(e.target.value))}
          onPointerDown={() => setDragging(true)}
          onPointerUp={() => setDragging(false)}
          onFocus={(e) => setFocused(e.currentTarget.matches(":focus-visible"))}
          onBlur={() => setFocused(false)}
          aria-label={label}
          className="peer absolute inset-0 h-5 w-full cursor-pointer opacity-0"
        />
        <motion.div className="pointer-events-none absolute top-1/2" style={{ left: `${value}%` }} animate={{ x: "-50%", y: "-50%" }}>
          <span
            aria-hidden
            className={`absolute left-1/2 top-1/2 h-7 w-7 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2 ring-offset-2 ring-offset-white transition-opacity duration-150 dark:ring-offset-slate-900 ${
              focused ? "opacity-100 ring-slate-900 dark:ring-white" : "opacity-0"
            }`}
          />
          <motion.div
            animate={{ scale: dragging ? 1.3 : 1 }}
            transition={{ type: "spring", stiffness: 500, damping: 25 }}
            style={{
              boxShadow: `0 0 0 2px #fff, 0 0 0 4px ${accent}${dragging ? `, 0 0 0 9px ${accentGlow}` : ""}`,
            }}
            className="h-4 w-4 rounded-full bg-white transition-shadow"
          />
          {dragging && (
            <motion.span
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, scale: 0.9 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              transition={{ type: "spring", stiffness: 500, damping: 30 }}
              className="pointer-events-none absolute -top-9 left-1/2 flex -translate-x-1/2 items-center gap-1.5 whitespace-nowrap rounded-md bg-slate-900 px-2 py-1 text-xs font-medium text-white dark:bg-slate-100 dark:text-slate-900"
            >
              <span aria-hidden className="h-1.5 w-1.5 rounded-full" style={{ backgroundColor: accent }} />
              {value}%
              <span aria-hidden className="absolute left-1/2 top-full -mt-1 h-2 w-2 -translate-x-1/2 rotate-45 bg-slate-900 dark:bg-slate-100" />
            </motion.span>
          )}
        </motion.div>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { TrashIcon as PhTrash, WarningIcon as PhWarning, CheckIcon as PhCheck } from "@phosphor-icons/react";

type Level = 0 | 1 | 2;

const DWELL_MS = 800;
const DECAY_MS = 2200;
const NEAR_RADIUS = 110;
const FAR_RADIUS = 170;

const LEVEL_STYLE: Record<Level, string> = {
  0: "border-slate-200/70 bg-white/95 text-slate-700 hover:border-slate-300 hover:bg-slate-50 dark:border-white/10 dark:bg-neutral-950/80 dark:text-slate-200 dark:hover:bg-white/[0.06]",
  1: "border-amber-400/50 bg-amber-50/70 text-slate-800 dark:border-amber-400/30 dark:bg-amber-500/10 dark:text-slate-100",
  2: "border-rose-400/70 bg-rose-50/80 text-rose-700 dark:border-rose-400/40 dark:bg-rose-500/10 dark:text-rose-300",
};

const ICON_TONE: Record<Level, string> = {
  0: "bg-slate-500/10 text-slate-500 dark:bg-white/10 dark:text-slate-300",
  1: "bg-amber-500/15 text-amber-600 dark:text-amber-400",
  2: "bg-rose-500/15 text-rose-600 dark:text-rose-400",
};

// Ambient "still waiting on you" pulse behind the icon badge, calmer at the
// warning level and more urgent once escalated, so a level that's settled
// (not mid-transition) still reads as alive rather than inert.
const HALO_BY_LEVEL: Partial<Record<Level, { tone: string; duration: number; peak: number }>> = {
  1: { tone: "bg-amber-400/40", duration: 2.6, peak: 0.4 },
  2: { tone: "bg-rose-400/50", duration: 1.3, peak: 0.65 },
};

function TrashIcon() {
  return <PhTrash size={14} aria-hidden />;
}

function AlertIcon() {
  return <PhWarning size={14} weight="bold" aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={14} weight="bold" aria-hidden />;
}

function HoldProgressRing({ progress }: { progress: number }) {
  const size = 14;
  const strokeWidth = 2;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="-rotate-90 shrink-0" aria-hidden>
      <circle cx={size / 2} cy={size / 2} r={radius} fill="none" stroke="currentColor" strokeOpacity={0.3} strokeWidth={strokeWidth} />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={circumference * (1 - progress)}
      />
    </svg>
  );
}

interface IntentAwareButtonProps {
  label?: string;
  confirmLabel?: string;
  warningHint?: string;
  confirmHint?: string;
  confirmedLabel?: string;
  holdMs?: number;
  onConfirm?: () => void;
  className?: string;
}

export function IntentAwareButton({
  label = "Delete project",
  confirmLabel = "Are you sure?",
  warningHint = "This can't be undone.",
  confirmHint = "Hold to permanently delete.",
  confirmedLabel = "Deleted",
  holdMs = 650,
  onConfirm,
  className,
}: IntentAwareButtonProps) {
  const [level, setLevel] = useState<Level>(0);
  const [holding, setHolding] = useState(false);
  const [progress, setProgress] = useState(0);
  const [done, setDone] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const doneRef = useRef(false);
  const wasNearRef = useRef(false);
  const approachCountRef = useRef(0);
  const dwellTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
  const decayTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
  const holdStart = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);
  const firedRef = useRef(false);

  useEffect(() => {
    doneRef.current = done;
  }, [done]);

  const clearDecay = () => {
    if (decayTimeout.current) {
      clearTimeout(decayTimeout.current);
      decayTimeout.current = null;
    }
  };

  const scheduleDecay = useCallback(() => {
    clearDecay();
    if (doneRef.current) return;
    decayTimeout.current = setTimeout(() => {
      if (doneRef.current) return;
      setLevel(0);
      approachCountRef.current = 0;
      wasNearRef.current = false;
    }, DECAY_MS);
  }, []);

  const raiseLevel = (next: Level) => {
    setLevel((current) => (current < next ? next : current));
  };

  // Tracked at the window level, not just over the button, so the button can
  // sense a real approach-and-retreat from anywhere nearby rather than only
  // reacting once the cursor already lands on it.
  useEffect(() => {
    if (done) return;
    const handleWindowPointerMove = (event: PointerEvent) => {
      if (!buttonRef.current) return;
      const rect = buttonRef.current.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const dist = Math.hypot(event.clientX - cx, event.clientY - cy);

      if (dist < NEAR_RADIUS) {
        clearDecay();
        if (!wasNearRef.current) {
          wasNearRef.current = true;
          approachCountRef.current += 1;
          if (approachCountRef.current >= 2) raiseLevel(2);
        }
      } else if (dist > FAR_RADIUS) {
        if (wasNearRef.current) wasNearRef.current = false;
        if (level > 0 || approachCountRef.current > 0) scheduleDecay();
      }
    };
    window.addEventListener("pointermove", handleWindowPointerMove);
    return () => window.removeEventListener("pointermove", handleWindowPointerMove);
  }, [done, level, scheduleDecay]);

  const handleButtonEnter = () => {
    clearDecay();
    dwellTimeout.current = setTimeout(() => {
      if (!doneRef.current) raiseLevel(1);
    }, DWELL_MS);
  };

  const handleButtonLeave = () => {
    if (dwellTimeout.current) {
      clearTimeout(dwellTimeout.current);
      dwellTimeout.current = null;
    }
    scheduleDecay();
  };

  const stopHold = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = null;
    holdStart.current = null;
    setHolding(false);
    if (!firedRef.current) setProgress(0);
  }, []);

  const startHold = useCallback(() => {
    if (firedRef.current || doneRef.current) return;
    setHolding(true);
    holdStart.current = performance.now();
    const tick = () => {
      if (holdStart.current === null) return;
      const elapsed = performance.now() - holdStart.current;
      const p = Math.min(1, elapsed / holdMs);
      setProgress(p);
      if (p >= 1) {
        firedRef.current = true;
        setHolding(false);
        setDone(true);
        onConfirm?.();
        return;
      }
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
  }, [holdMs, onConfirm]);

  useEffect(() => {
    return () => {
      if (dwellTimeout.current) clearTimeout(dwellTimeout.current);
      if (decayTimeout.current) clearTimeout(decayTimeout.current);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const hint = level === 1 ? warningHint : level === 2 ? confirmHint : null;
  const hintId = "intent-aware-hint";

  return (
    <div className={className}>
      <AnimatePresence mode="wait" initial={false}>
        {done ? (
          <motion.div
            key="done"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
            className="flex items-center gap-2 rounded-xl border border-slate-200/70 bg-white/95 px-4 py-2.5 text-sm font-medium text-slate-600 dark:border-white/10 dark:bg-neutral-950/80 dark:text-slate-300"
          >
            <span className="relative flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
              {!shouldReduceMotion && (
                <motion.span
                  aria-hidden
                  className="absolute rounded-full border-2 border-emerald-400/60"
                  style={{ inset: -3 }}
                  initial={{ scale: 0.7, opacity: 0.9 }}
                  animate={{ scale: 1.7, opacity: 0 }}
                  transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                />
              )}
              <CheckIcon />
            </span>
            {confirmedLabel}
          </motion.div>
        ) : (
          <motion.button
            key="button"
            layout
            type="button"
            ref={buttonRef}
            aria-describedby={hint ? hintId : undefined}
            onPointerEnter={handleButtonEnter}
            onPointerLeave={() => {
              handleButtonLeave();
              stopHold();
            }}
            onPointerDown={startHold}
            onPointerUp={stopHold}
            onPointerCancel={stopHold}
            onFocus={() => raiseLevel(1)}
            onBlur={() => {
              stopHold();
              scheduleDecay();
            }}
            onKeyDown={(event) => {
              if ((event.key === "Enter" || event.key === " ") && !event.repeat) {
                event.preventDefault();
                startHold();
              }
            }}
            onKeyUp={(event) => {
              if (event.key === "Enter" || event.key === " ") stopHold();
            }}
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 420, damping: 34 }}
            className={`relative flex w-full max-w-xs select-none flex-col overflow-hidden rounded-xl border px-4 py-2.5 text-left shadow-sm transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-500 ${LEVEL_STYLE[level]}`}
          >
            <motion.span
              aria-hidden
              className="absolute inset-y-0 left-0 bg-rose-600/25"
              style={{ transformOrigin: "left" }}
              animate={{ scaleX: progress }}
              transition={shouldReduceMotion || holding ? { duration: 0 } : { type: "spring", stiffness: 400, damping: 26 }}
            />
            <span className="relative flex items-center gap-2 text-sm font-medium">
              <span className={`relative flex h-6 w-6 shrink-0 items-center justify-center rounded-full ${ICON_TONE[level]}`}>
                {!holding && HALO_BY_LEVEL[level] && (
                  <motion.span
                    aria-hidden
                    className={`absolute inset-0 rounded-full blur-[3px] ${HALO_BY_LEVEL[level]!.tone}`}
                    animate={
                      shouldReduceMotion
                        ? { opacity: HALO_BY_LEVEL[level]!.peak * 0.6 }
                        : { opacity: [0.12, HALO_BY_LEVEL[level]!.peak, 0.12], scale: [1, 1.3, 1] }
                    }
                    transition={
                      shouldReduceMotion
                        ? { duration: 0.2 }
                        : { duration: HALO_BY_LEVEL[level]!.duration, repeat: Infinity, ease: "easeInOut" }
                    }
                  />
                )}
                <AnimatePresence initial={false}>
                  {level === 2 ? (
                    <motion.span
                      key="alert"
                      className="relative flex"
                      initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5, rotate: -20 }}
                      animate={
                        shouldReduceMotion
                          ? { opacity: 1 }
                          : { opacity: 1, scale: 1, rotate: 0, x: [0, -2.5, 2.5, -1.5, 1.5, 0] }
                      }
                      exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
                      transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1] }}
                    >
                      <AlertIcon />
                    </motion.span>
                  ) : (
                    <motion.span
                      key="trash"
                      className="relative flex"
                      initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
                      animate={{ opacity: 1, scale: 1 }}
                      exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
                      transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
                    >
                      <TrashIcon />
                    </motion.span>
                  )}
                </AnimatePresence>
              </span>
              <span className="relative inline-flex overflow-hidden">
                <AnimatePresence mode="popLayout" initial={false}>
                  <motion.span
                    key={holding ? "holding" : level === 2 ? "confirm" : "label"}
                    initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 8 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -8 }}
                    transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }}
                  >
                    {holding ? "Hold to delete…" : level === 2 ? confirmLabel : label}
                  </motion.span>
                </AnimatePresence>
              </span>
              {holding && (
                <span className="ml-auto text-rose-600 dark:text-rose-400">
                  <HoldProgressRing progress={progress} />
                </span>
              )}
            </span>
            <AnimatePresence initial={false}>
              {hint && !holding && (
                <motion.span
                  id={hintId}
                  role="status"
                  aria-live="polite"
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                  transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
                  className={`relative pl-8 pt-1 text-xs ${level === 2 ? "text-rose-600 dark:text-rose-400" : "text-amber-600 dark:text-amber-400"}`}
                >
                  {hint}
                </motion.span>
              )}
            </AnimatePresence>
          </motion.button>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useRef, useState, type DragEvent } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  UploadSimpleIcon as PhUploadSimple,
  CheckIcon as PhCheck,
  ImageIcon as PhImage,
  FileIcon as PhFile,
  XIcon as PhX,
} from "@phosphor-icons/react";

interface UploadedFile {
  id: string;
  name: string;
  size: number;
}

let nextId = 1;

function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb.toFixed(kb < 10 ? 1 : 0)} KB`;
  const mb = kb / 1024;
  return `${mb.toFixed(mb < 10 ? 1 : 0)} MB`;
}

function isImage(name: string) {
  return /\.(png|jpe?g|gif|webp|svg)$/i.test(name);
}

function UploadIcon() {
  return <PhUploadSimple size={18} aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={16} weight="bold" aria-hidden />;
}

function ImageIcon() {
  return <PhImage size={14} aria-hidden />;
}

function DocumentIcon() {
  return <PhFile size={14} aria-hidden />;
}

function XIcon() {
  return <PhX size={13} aria-hidden />;
}

function FileTone({ name }: { name: string }) {
  const image = isImage(name);
  return (
    <span
      className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${
        image ? "bg-emerald-500/12 text-emerald-600 dark:text-emerald-400" : "bg-amber-500/12 text-amber-600 dark:text-amber-400"
      }`}
    >
      {image ? <ImageIcon /> : <DocumentIcon />}
    </span>
  );
}

export function DocumentUpload({
  multiple = true,
  label = "Upload documents",
}: {
  multiple?: boolean;
  label?: string;
}) {
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const [justAdded, setJustAdded] = useState(false);
  const [pulseKey, setPulseKey] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const addedTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inputId = useId();
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => () => {
    if (addedTimeout.current) clearTimeout(addedTimeout.current);
  }, []);

  const addFiles = useCallback(
    (list: FileList | null) => {
      if (!list || list.length === 0) return;
      const incoming = Array.from(list).map((f) => ({ id: `f${nextId++}`, name: f.name, size: f.size }));
      setFiles((prev) => (multiple ? [...prev, ...incoming] : [incoming[0]]));
      setAnnouncement(
        incoming.length === 1 ? `${incoming[0].name} added` : `${incoming.length} files added`
      );
      setPulseKey((k) => k + 1);
      setJustAdded(true);
      if (addedTimeout.current) clearTimeout(addedTimeout.current);
      addedTimeout.current = setTimeout(() => setJustAdded(false), 900);
    },
    [multiple]
  );

  const removeFile = (file: UploadedFile) => {
    setFiles((prev) => prev.filter((f) => f.id !== file.id));
    setAnnouncement(`${file.name} removed`);
  };

  const onDrop = (e: DragEvent<HTMLLabelElement>) => {
    e.preventDefault();
    setIsDragging(false);
    addFiles(e.dataTransfer.files);
  };

  return (
    <div className="w-full max-w-md">
      <label
        htmlFor={inputId}
        onDragOver={(e) => {
          e.preventDefault();
          setIsDragging(true);
        }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={onDrop}
        className={`flex cursor-pointer flex-col items-center justify-center gap-2 rounded-2xl border-2 border-dashed px-6 py-8 text-center transition-colors duration-200 focus-within:outline focus-within:outline-2 focus-within:outline-offset-2 focus-within:outline-emerald-600 ${
          isDragging
            ? "border-emerald-500 bg-emerald-500/5"
            : "border-slate-300 hover:border-emerald-400 dark:border-slate-700 dark:hover:border-emerald-500/60"
        }`}
      >
        <span className="relative flex h-10 w-10 items-center justify-center rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
          <AnimatePresence mode="wait" initial={false}>
            {justAdded ? (
              <motion.span
                key="check"
                initial={shouldReduceMotion ? false : { scale: 0.5, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ type: "spring", stiffness: 500, damping: 20 }}
              >
                <CheckIcon />
              </motion.span>
            ) : (
              <motion.span key="upload" initial={false} animate={{ opacity: 1 }}>
                <UploadIcon />
              </motion.span>
            )}
          </AnimatePresence>
          {!shouldReduceMotion && justAdded && (
            <motion.span
              key={pulseKey}
              aria-hidden
              className="absolute inset-0 rounded-full border-2 border-emerald-500"
              initial={{ scale: 1, opacity: 0.6 }}
              animate={{ scale: 1.8, opacity: 0 }}
              transition={{ duration: 0.6, ease: "easeOut" }}
            />
          )}
        </span>
        <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{label}</span>
        <span className="text-xs text-slate-400 dark:text-slate-500">
          Drag &amp; drop {multiple ? "files" : "a file"} here, or click to browse
        </span>
        <input
          ref={inputRef}
          id={inputId}
          type="file"
          multiple={multiple}
          className="sr-only"
          onChange={(e) => {
            addFiles(e.target.files);
            e.target.value = "";
          }}
        />
      </label>

      <p aria-live="polite" className="sr-only">
        {announcement}
      </p>

      {files.length > 0 && (
        <ul className="mt-3 flex flex-col gap-1.5" role="list">
          <AnimatePresence initial={false}>
            {files.map((f) => (
              <motion.li
                key={f.id}
                layout
                initial={shouldReduceMotion ? false : { opacity: 0, scale: 0.96 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.94 }}
                transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
                className="flex items-center gap-3 rounded-xl border border-transparent bg-black/[0.02] px-3 py-2 dark:bg-white/[0.03]"
              >
                <FileTone name={f.name} />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-slate-800 dark:text-slate-100">{f.name}</p>
                  <p className="text-xs text-slate-400 dark:text-slate-500">{formatBytes(f.size)}</p>
                </div>
                <button
                  type="button"
                  onClick={() => removeFile(f)}
                  aria-label={`Remove ${f.name}`}
                  className="inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
                >
                  <XIcon />
                </button>
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      )}
    </div>
  );
}

