      </p>

      <div className="relative mt-4 grid grid-cols-2 rounded-lg bg-slate-100 p-1 text-sm font-medium dark:bg-neutral-900">
        {(["private", "anyone"] as const).map((option) => (
          <button
            key={option}
            type="button"
            onClick={() => setVisibility(option)}
            className={`relative z-10 rounded-md px-3 py-1.5 transition-colors ${
