              <motion.span
                layoutId="share-visibility-highlight"
                className="absolute inset-0 -z-10 rounded-md bg-white shadow-sm dark:bg-neutral-700"
                transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 34 }}
              />
            )}
            {option === "private" ? "Only you" : "Anyone with link"}
          </button>
        ))}
      </div>

      <AnimatePresence initial={false}>
        {visibility === "anyone" && (
          <motion.div
            initial={shouldReduceMotion ? { opacity: 1, height: "auto" } : { opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
            transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
            className="overflow-hidden"
          >
            <div className="mt-4 flex items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 py-1 pl-3 pr-1 dark:border-slate-800 dark:bg-neutral-900">
              <span className="min-w-0 flex-1 truncate text-xs text-slate-500 dark:text-slate-400">{shareUrl}</span>
              <button
                type="button"
                onClick={handleCopy}
                className={`inline-flex shrink-0 items-center gap-1.5 rounded-md px-2.5 py-1.5 text-xs font-medium transition-colors duration-200 ${
                  copied
                    ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400"
                    : "bg-slate-900 text-white hover:bg-slate-700 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
                }`}
              >
                <AnimatePresence mode="wait" initial={false}>
                  <motion.span
                    key={copied ? "check" : "link"}
                    initial={{ opacity: 0, scale: 0.6 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.6 }}
                    transition={{ duration: 0.15 }}
                    className="inline-flex"
                  >
                    {copied ? <CheckIcon /> : <LinkIcon />}
                  </motion.span>
                </AnimatePresence>
                {copied ? "Copied" : "Copy link"}
              </button>
            </div>

            <p className="mt-3 text-[11px] font-medium uppercase tracking-wide text-slate-400 dark:text-slate-500">
              What people will see
            </p>
            <div className="mt-2 rounded-xl border border-slate-200 bg-slate-50 p-3 dark:border-slate-800 dark:bg-neutral-900">
              <div className="flex items-center gap-2">
                <span className="h-1.5 w-1.5 rounded-full bg-amber-500" aria-hidden />
                <span className="text-[11px] font-medium uppercase tracking-wide text-slate-500 dark:text-slate-400">
                  Shared from Claude
                </span>
              </div>
              <p className="mt-1.5 truncate text-sm font-medium text-slate-900 dark:text-white">
                Debugging a flaky CI pipeline
              </p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

