"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

interface NotificationItem {
  id: number;
  title: string;
  time: string;
  read?: boolean;
}

export function NotificationButton({
  icon,
  label,
  notifications,
}: {
  icon: ReactNode;
  label: string;
  notifications: NotificationItem[];
}) {
  const [items, setItems] = useState(() => notifications.map((n) => ({ ...n, read: n.read ?? false })));
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const unreadCount = items.filter((n) => !n.read).length;

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const markRead = (id: number) => {
    setItems((list) => list.map((n) => (n.id === id ? { ...n, read: true } : n)));
  };

  const markAllRead = () => {
    setItems((list) => list.map((n) => ({ ...n, read: true })));
  };

  return (
    <div ref={rootRef} className="flex flex-col items-center">
      <motion.button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={unreadCount > 0 ? `${label}, ${unreadCount} unread` : label}
        onClick={() => setOpen((v) => !v)}
        onMouseEnter={() => setActive(true)}
        onMouseLeave={() => setActive(false)}
        onFocus={() => setActive(true)}
        onBlur={() => setActive(false)}
        whileTap={shouldReduceMotion ? { scale: 0.94 } : { scale: 0.9, rotate: [0, -10, 8, -4, 0] }}
        transition={{ type: "spring", stiffness: 500, damping: 30 }}
        className="relative inline-flex h-10 w-10 items-center justify-center rounded-full focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-600"
      >
        <span className="absolute inset-0 overflow-hidden rounded-full p-[1.5px]">
          <motion.span
            aria-hidden
            className="absolute inset-[-60%]"
            style={{
              background:
                "conic-gradient(from 0deg, transparent 0%, #10b981 12%, #f59e0b 20%, transparent 38%)",
            }}
            animate={shouldReduceMotion ? undefined : { rotate: 360 }}
            transition={{ duration: active || open ? 2 : 5.5, repeat: Infinity, ease: "linear" }}
          />
          <span className="relative z-10 inline-flex h-full w-full items-center justify-center rounded-full bg-white text-slate-600 transition-colors duration-300 dark:bg-black dark:text-slate-300">
            {icon}
          </span>
        </span>
        <AnimatePresence>
          {unreadCount > 0 && (
            <motion.span
              key={unreadCount}
              aria-hidden
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
              transition={{ type: "spring", stiffness: 500, damping: 25 }}
              className="absolute -top-1 -right-1 z-20 flex h-4 min-w-4 items-center justify-center rounded-full bg-amber-700 px-1 text-[10px] font-semibold leading-none text-white"
            >
              {unreadCount > 99 ? "99+" : unreadCount}
            </motion.span>
          )}
        </AnimatePresence>
      </motion.button>

      <AnimatePresence>
        {open && (
          <motion.div
            role="menu"
            aria-label={label}
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { height: { duration: 0.25, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.15 } }
            }
            className="mt-2 w-72 max-w-full overflow-hidden rounded-xl border border-slate-200 bg-white shadow-lg dark:border-slate-700 dark:bg-neutral-950"
          >
            <div className="flex items-center justify-between border-b border-slate-100 px-3.5 py-2.5 dark:border-slate-800">
              <span className="text-sm font-semibold text-slate-900 dark:text-white">{label}</span>
              {unreadCount > 0 && (
                <button
                  type="button"
                  onClick={markAllRead}
                  className="text-xs font-medium text-emerald-700 hover:text-emerald-800 dark:text-emerald-400 dark:hover:text-emerald-300"
                >
                  Mark all read
                </button>
              )}
            </div>
            <ul className="max-h-64 overflow-y-auto py-1">
              {items.map((n) => (
                <li key={n.id}>
                  <button
                    type="button"
                    role="menuitem"
                    onClick={() => markRead(n.id)}
                    className="flex w-full items-start gap-2.5 px-3.5 py-2.5 text-left transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/60"
                  >
                    <span
                      aria-hidden
                      className={`mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full ${n.read ? "bg-transparent" : "bg-amber-500"}`}
                    />
                    <span className="flex-1">
                      <span
                        className={`block text-sm ${n.read ? "text-slate-500 dark:text-slate-400" : "font-medium text-slate-900 dark:text-white"}`}
                      >
                        {n.title}
                      </span>
                      <span className="mt-0.5 block text-xs text-slate-400 dark:text-slate-500">{n.time}</span>
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

