import { useEffect, useRef } from "react";
import { motion, useInView, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion";

function Counter({
  to,
  decimals = 1,
  prefix = "",
  suffix = "",
}: {
  to: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
}) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-10% 0px" });
  const shouldReduceMotion = useReducedMotion();
  const motionValue = useMotionValue(shouldReduceMotion ? to : 0);
  const spring = useSpring(motionValue, { stiffness: 80, damping: 20 });
  const display = useTransform(spring, (v) => `${prefix}${v.toFixed(decimals)}${suffix}`);

  useEffect(() => {
    if (isInView && !shouldReduceMotion) motionValue.set(to);
  }, [isInView, to, motionValue, shouldReduceMotion]);

  return <motion.span ref={ref}>{display}</motion.span>;
}

export function StatCard({
  label,
  value,
  delta,
  sparklinePoints,
}: {
  label: string;
  value: number;
  delta?: number;
  sparklinePoints: string;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.div
      whileHover={shouldReduceMotion ? undefined : { y: -3 }}
      transition={{ type: "spring", stiffness: 400, damping: 28 }}
      className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-6 transition-shadow duration-300 hover:shadow-lg dark:border-slate-700 dark:bg-neutral-950"
    >
