"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export interface AccordionItem {
  q: string;
  a: string;
}

export function Accordion({ items }: { items: AccordionItem[] }) {
  const [open, setOpen] = useState<number | null>(0);
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="w-full max-w-md divide-y divide-slate-200 rounded-2xl border border-slate-200 bg-white dark:divide-slate-700 dark:border-slate-700 dark:bg-neutral-950">
      {items.map((item, i) => {
        const isOpen = open === i;
        return (
          <div key={item.q}>
            <h3>
              <button
                type="button"
                aria-expanded={isOpen}
                aria-controls={`accordion-panel-${i}`}
                onClick={() => setOpen(isOpen ? null : i)}
                className="flex w-full items-center justify-between gap-4 px-5 py-4 text-left text-sm font-medium text-slate-900 focus-visible:outline focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-emerald-600 dark:text-white"
              >
                {item.q}
                <motion.svg
                  animate={{ rotate: isOpen ? 45 : 0 }}
                  transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 30 }}
                  viewBox="0 0 24 24"
                  width="16"
                  height="16"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  aria-hidden
                  className="shrink-0 text-slate-400"
                >
                  <path d="M12 5v14M5 12h14" />
                </motion.svg>
              </button>
            </h3>
            <AnimatePresence initial={false}>
              {isOpen && (
                <motion.div
                  id={`accordion-panel-${i}`}
                  role="region"
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : { height: { duration: 0.3, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.2 } }
                  }
                  className="overflow-hidden"
                >
                  <p className="px-5 pb-4 text-sm leading-relaxed text-slate-500 dark:text-slate-400">{item.a}</p>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useRef } from "react";
import { motion, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion";

export function TestimonialCard({
  quote,
  name,
  role,
  initials,
}: {
  quote: string;
  name: string;
  role: string;
  initials: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const mouseX = useMotionValue(0.5);
  const mouseY = useMotionValue(0.5);

  const quoteX = useSpring(useTransform(mouseX, [0, 1], shouldReduceMotion ? [0, 0] : [-6, 6]), {
    stiffness: 150,
    damping: 20,
  });
  const quoteY = useSpring(useTransform(mouseY, [0, 1], shouldReduceMotion ? [0, 0] : [-6, 6]), {
    stiffness: 150,
    damping: 20,
  });

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    mouseX.set((e.clientX - rect.left) / rect.width);
    mouseY.set((e.clientY - rect.top) / rect.height);
  };

  return (
    <motion.div
      ref={ref}
      onMouseMove={handleMouseMove}
      whileHover={shouldReduceMotion ? undefined : { y: -3 }}
      transition={{ type: "spring", stiffness: 400, damping: 28 }}
      className="relative w-full max-w-sm overflow-hidden rounded-2xl border border-slate-200 bg-white p-6 transition-shadow duration-300 hover:shadow-xl dark:border-slate-700 dark:bg-neutral-950"
    >
      <motion.svg
        aria-hidden
        style={{ x: quoteX, y: quoteY }}
        className="pointer-events-none absolute -right-2 -top-3 text-amber-100 dark:text-amber-500/10"
        width="72"
        height="72"
        viewBox="0 0 24 24"
        fill="currentColor"
      >
        <path d="M7.17 6.5C4.31 6.5 2 8.81 2 11.67c0 2.65 1.95 4.83 4.5 5.17v.16c0 1.38-1.12 2.5-2.5 2.5v2c2.49 0 4.5-2.01 4.5-4.5v-5.5c0-2.86-2.31-5-5.17-5Zm10.66 0c-2.86 0-5.17 2.31-5.17 5.17 0 2.65 1.95 4.83 4.5 5.17v.16c0 1.38-1.12 2.5-2.5 2.5v2c2.49 0 4.5-2.01 4.5-4.5v-5.5c0-2.86-2.31-5-5.17-5Z" />
      </motion.svg>
      <p className="relative text-sm leading-relaxed text-slate-600 dark:text-slate-300">&ldquo;{quote}&rdquo;</p>
      <div className="relative mt-5 flex items-center gap-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-full bg-amber-700 text-xs font-semibold text-white">
          {initials}
        </div>
        <div>
          <p className="text-sm font-medium text-slate-900 dark:text-white">{name}</p>
          <p className="text-xs text-slate-400 dark:text-slate-500">{role}</p>
        </div>
      </div>
    </motion.div>
  );
}

"use client";

import { forwardRef, useImperativeHandle, useRef, useState } from "react";
import { animate, motion, useMotionValue, useReducedMotion, useTransform } from "framer-motion";

interface SwipeCardItem {
  id: string | number;
  title: string;
  subtitle: string;
  tag: string;
  description: string;
  gradient: string;
}

const SWIPE_THRESHOLD = 120;
const SWIPE_VELOCITY = 500;

type SwipeDirection = "left" | "right";
type SwipeHandle = { swipe: (direction: SwipeDirection) => void };

const SwipeCard = forwardRef<SwipeHandle, { item: SwipeCardItem; active: boolean; onSwiped: (direction: SwipeDirection) => void }>(
  function SwipeCard({ item, active, onSwiped }, ref) {
    const shouldReduceMotion = useReducedMotion();
    const x = useMotionValue(0);
    const rotate = useTransform(x, [-200, 200], shouldReduceMotion ? [0, 0] : [-16, 16]);
    const cardOpacity = useTransform(x, [-600, -200, 0, 200, 600], [0, 1, 1, 1, 0]);
    const saveOpacity = useTransform(x, [20, 120], [0, 1]);
    const skipOpacity = useTransform(x, [-120, -20], [1, 0]);

    const fly = (direction: SwipeDirection) => {
      animate(x, direction === "right" ? 700 : -700, {
        ...(shouldReduceMotion ? { duration: 0.15, ease: "easeOut" as const } : { type: "spring" as const, stiffness: 320, damping: 32 }),
        onComplete: () => onSwiped(direction),
      });
    };

    useImperativeHandle(ref, () => ({ swipe: fly }));

    return (
      <motion.div
        role={active ? "group" : undefined}
        aria-hidden={!active}
        aria-roledescription={active ? "swipe card" : undefined}
        aria-label={
          active
            ? `${item.title}, ${item.subtitle}. ${item.description} Press left arrow to skip, right arrow to save.`
            : undefined
        }
        tabIndex={active ? 0 : -1}
        style={{ x, rotate, opacity: cardOpacity }}
        drag={active ? "x" : false}
        dragMomentum={false}
        onDragEnd={(_, info) => {
          if (info.offset.x > SWIPE_THRESHOLD || info.velocity.x > SWIPE_VELOCITY) fly("right");
          else if (info.offset.x < -SWIPE_THRESHOLD || info.velocity.x < -SWIPE_VELOCITY) fly("left");
          else animate(x, 0, shouldReduceMotion ? { duration: 0.1 } : { type: "spring", stiffness: 320, damping: 24 });
        }}
        onKeyDown={(e) => {
          if (!active) return;
          if (e.key === "ArrowRight") fly("right");
          else if (e.key === "ArrowLeft") fly("left");
        }}
        className={`absolute inset-0 flex flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-xl outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-emerald-600 dark:border-slate-700 dark:bg-neutral-950 ${
          active ? "cursor-grab touch-none active:cursor-grabbing" : "pointer-events-none"
        }`}
      >
        <div className={`relative h-28 shrink-0 bg-gradient-to-br ${item.gradient}`}>
          {active && (
            <>
              <motion.span
                aria-hidden
                style={{ opacity: saveOpacity }}
                className="absolute left-3 top-3 -rotate-12 rounded-md border-2 border-emerald-400 bg-emerald-500/90 px-2 py-0.5 text-xs font-bold tracking-wide text-white shadow-sm"
              >
                SAVE
              </motion.span>
              <motion.span
                aria-hidden
                style={{ opacity: skipOpacity }}
                className="absolute right-3 top-3 rotate-12 rounded-md border-2 border-rose-400 bg-rose-500/90 px-2 py-0.5 text-xs font-bold tracking-wide text-white shadow-sm"
              >
                SKIP
              </motion.span>
            </>
          )}
          <span className="absolute bottom-2 left-3 rounded-full bg-black/30 px-2 py-0.5 text-[11px] font-medium text-white backdrop-blur-sm">
            {item.tag}
          </span>
        </div>
        <div className="flex flex-1 flex-col gap-1.5 p-5">
          <h3 className="text-base font-semibold text-slate-900 dark:text-white">
            {item.title}<span className="font-normal text-slate-400 dark:text-slate-500">: {item.subtitle}</span>
          </h3>
          <p className="text-sm leading-relaxed text-slate-500 dark:text-slate-400">{item.description}</p>
        </div>
      </motion.div>
    );
  }
);

export function SwipeCards({
  cards,
  onSave,
  onSkip,
}: {
  cards: SwipeCardItem[];
  onSave?: (item: SwipeCardItem) => void;
  onSkip?: (item: SwipeCardItem) => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [stack, setStack] = useState(cards);
  const [announcement, setAnnouncement] = useState("");
  const topRef = useRef<SwipeHandle>(null);

  const visible = stack.slice(0, 3);

  const handleSwiped = (direction: SwipeDirection) => {
    const top = stack[0];
    if (!top) return;
    setStack((s) => s.slice(1));
    if (direction === "right") {
      onSave?.(top);
      setAnnouncement(`Saved ${top.title}, ${top.subtitle}.`);
    } else {
      onSkip?.(top);
      setAnnouncement(`Skipped ${top.title}, ${top.subtitle}.`);
    }
  };

  const reset = () => {
    setStack([...cards].sort(() => Math.random() - 0.5));
    setAnnouncement("Deck reset.");
  };

  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-4">
      <div className="relative h-[320px] w-full overflow-hidden">
        {stack.length === 0 ? (
          <motion.div
            key="empty"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: shouldReduceMotion ? 0.1 : 0.25, ease: [0.22, 1, 0.36, 1] }}
            className="flex h-full w-full flex-col items-center justify-center gap-2 rounded-2xl border border-dashed border-slate-300 text-center dark:border-slate-700"
          >
            <p className="text-sm font-medium text-slate-600 dark:text-slate-300">You&apos;ve seen everything.</p>
            <button
              type="button"
              onClick={reset}
              className="mt-1 rounded-lg bg-emerald-700 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-emerald-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-700"
            >
              Start over
            </button>
          </motion.div>
        ) : (
          <div key="stack" className="relative h-full w-full">
            {visible.map((item, i) => (
              <motion.div
                key={item.id}
                className="absolute inset-0"
                style={{ zIndex: visible.length - i }}
                initial={false}
                animate={{ scale: 1 - i * 0.05, y: i * 10, opacity: i === 2 ? 0.6 : 1 }}
                transition={shouldReduceMotion ? { duration: 0.1 } : { type: "spring", stiffness: 300, damping: 26 }}
              >
                <SwipeCard ref={i === 0 ? topRef : undefined} item={item} active={i === 0} onSwiped={handleSwiped} />
              </motion.div>
            ))}
          </div>
        )}
      </div>

      <span className="text-center text-xs text-slate-400 dark:text-slate-500">{stack.length} left</span>

      <p aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

