export function IconStepper({
  steps,
  initial = 0,
}: {
  steps: { label: string; icon: React.ReactNode }[];
  initial?: number;
}) {
  const [current, setCurrent] = useState(initial);
  const shouldReduceMotion = useReducedMotion();

  return (
    <ol className="flex w-full items-center">
      {steps.map((step, i) => {
        const isComplete = i < current;
        const isActive = i === current;
        return (
          <li key={step.label} className="flex flex-1 items-center last:flex-none">
            <button
              type="button"
              onClick={() => setCurrent(i)}
              aria-current={isActive ? "step" : undefined}
              className="flex flex-col items-center gap-2 rounded-full focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-amber-500"
            >
              <motion.span
                animate={isActive && !shouldReduceMotion ? { scale: [1, 1.15, 1] } : { scale: 1 }}
                transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
                className={`relative flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2 transition-colors duration-300 ${
                  isComplete
                    ? "border-amber-600 bg-amber-600 text-white"
                    : isActive
                      ? "border-amber-600 text-amber-600 dark:text-amber-400"
                      : "border-slate-300 text-slate-400 dark:border-slate-600 dark:text-slate-500"
                }`}
              >
                <AnimatePresence initial={false} mode="wait">
                  {isComplete ? (
                    <motion.svg
                      key="check"
                      viewBox="0 0 16 16"
                      width="14"
                      height="14"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      aria-hidden
                      initial={{ opacity: 0, scale: 0.5 }}
                      animate={{ opacity: 1, scale: 1 }}
                      exit={{ opacity: 0, scale: 0.5 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
                    >
                      <path d="M3 8.5l3 3 7-7.5" />
                    </motion.svg>
                  ) : (
                    <motion.span
                      key="icon"
                      initial={{ opacity: 0, scale: 0.5, rotate: -20 }}
                      animate={{ opacity: 1, scale: 1, rotate: 0 }}
                      exit={{ opacity: 0, scale: 0.5, rotate: 20 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
                      className="flex items-center justify-center"
                    >
                      {step.icon}
                    </motion.span>
                  )}
                </AnimatePresence>
              </motion.span>
              <span
                className={`text-xs font-medium ${
                  isActive ? "text-slate-900 dark:text-white" : "text-slate-400 dark:text-slate-500"
                }`}
              >
                {step.label}
              </span>
            </button>
            {i < steps.length - 1 && (
              <div className="mx-2 mb-5 h-0.5 flex-1 overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
                <motion.div
                  className="h-full bg-amber-600"
                  initial={false}
                  animate={{ scaleX: isComplete ? 1 : 0 }}
                  style={{ transformOrigin: "left" }}
                  transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                />
              </div>
            )}
          </li>
        );
      })}
    </ol>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export function CometStepper({ steps, initial = 0 }: { steps: string[]; initial?: number }) {
  const [current, setCurrent] = useState(initial);
  const [prevCurrent, setPrevCurrent] = useState(current);
  const shouldReduceMotion = useReducedMotion();

  if (current !== prevCurrent) {
    setPrevCurrent(current);
  }
  const jumpOrigin = prevCurrent;

  return (
    <div style={{ perspective: 600 }}>
      <ol className="flex items-center">
        {steps.map((step, i) => {
          const isComplete = i < current;
          const isActive = i === current;
          const segmentDelay = shouldReduceMotion ? 0 : Math.min(Math.abs(i - jumpOrigin), 4) * 0.12;
          const arrivalDelay = shouldReduceMotion
            ? 0
            : Math.min(Math.abs(current - jumpOrigin), 4) * 0.12 + 0.1;

          return (
            <li key={step} className="flex flex-1 items-center last:flex-none">
              <button
                type="button"
                onClick={() => setCurrent(i)}
                aria-current={isActive ? "step" : undefined}
                className="flex flex-col items-center gap-2 rounded-full focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-600"
              >
                <span
                  className={`relative flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2 text-xs font-semibold transition-colors duration-300 ${
                    isComplete
                      ? "border-emerald-700 bg-emerald-700 text-white"
                      : isActive
                        ? "border-emerald-700 text-emerald-700 dark:text-emerald-400"
                        : "border-slate-300 text-slate-400 dark:border-slate-600 dark:text-slate-500"
                  }`}
                  style={{ transformStyle: "preserve-3d" }}
                >
                  <AnimatePresence initial={false}>
                    {isActive && !shouldReduceMotion && (
                      <motion.span
                        key="arrive-ring"
                        aria-hidden
                        className="absolute inset-0 rounded-full border-2 border-emerald-400/70"
                        initial={{ scale: 0.7, opacity: 0.9 }}
                        animate={{ scale: 2, opacity: 0 }}
                        exit={{ opacity: 0 }}
                        transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1], delay: arrivalDelay }}
                      />
                    )}
                  </AnimatePresence>
                  <AnimatePresence initial={false} mode="wait">
                    {isComplete ? (
                      <motion.svg
                        key="check"
                        viewBox="0 0 16 16"
                        width="14"
                        height="14"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        aria-hidden
                        initial={shouldReduceMotion ? { opacity: 0 } : { rotateY: -100, opacity: 0 }}
                        animate={{ rotateY: 0, opacity: 1 }}
                        exit={shouldReduceMotion ? { opacity: 0 } : { rotateY: 100, opacity: 0 }}
                        transition={
                          shouldReduceMotion
                            ? { duration: 0 }
                            : { duration: 0.35, ease: [0.16, 1, 0.3, 1], delay: segmentDelay }
                        }
                      >
                        <path d="M3 8.5l3 3 7-7.5" />
                      </motion.svg>
                    ) : (
                      <motion.span
                        key="num"
                        initial={shouldReduceMotion ? { opacity: 0 } : { rotateY: -100, opacity: 0 }}
                        animate={{ rotateY: 0, opacity: 1 }}
                        exit={shouldReduceMotion ? { opacity: 0 } : { rotateY: 100, opacity: 0 }}
                        transition={
                          shouldReduceMotion
                            ? { duration: 0 }
                            : { duration: 0.35, ease: [0.16, 1, 0.3, 1], delay: segmentDelay }
                        }
                      >
                        {i + 1}
                      </motion.span>
                    )}
                  </AnimatePresence>
                </span>
                <span
                  className={`text-xs font-medium ${
                    isActive ? "text-slate-900 dark:text-white" : "text-slate-400 dark:text-slate-500"
                  }`}
                >
                  {step}
                </span>
              </button>
              {i < steps.length - 1 && (
                <div className="relative mx-2 mb-5 h-0.5 flex-1 overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
                  <motion.div
                    className="h-full bg-emerald-700"
                    initial={false}
                    animate={{ scaleX: isComplete ? 1 : 0 }}
                    style={{ transformOrigin: "left" }}
                    transition={
                      shouldReduceMotion ? { duration: 0 } : { duration: 0.4, ease: [0.22, 1, 0.36, 1], delay: segmentDelay }
                    }
                  />
                  <AnimatePresence initial={false}>
                    {isComplete && !shouldReduceMotion && (
                      <motion.div
                        key="comet"
                        aria-hidden
                        className="absolute inset-y-0 left-0 w-full"
                        initial={{ x: "0%", opacity: 1 }}
                        animate={{ x: "100%", opacity: [1, 1, 0] }}
                        exit={{ opacity: 0 }}
                        transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1], delay: segmentDelay }}
                      >
                        <span
                          className="absolute top-1/2 h-2 w-2 rounded-full bg-amber-300 shadow-[0_0_8px_3px_rgba(245,158,11,0.7)]"
                          style={{ marginTop: -4, marginLeft: -4 }}
                        />
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              )}
            </li>
          );
        })}
      </ol>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export function DropdownMenu({ label, items }: { label: string; items: string[] }) {
  const [open, setOpen] = useState(false);
  const [highlighted, setHighlighted] = useState(0);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      if (!open) return setOpen(true);
      setHighlighted((h) => Math.min(h + 1, items.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlighted((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      setOpen((v) => !v);
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  };

  return (
    <div ref={rootRef} className="relative inline-block">
      <button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        onKeyDown={handleKeyDown}
        className="inline-flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-3.5 py-2 text-sm font-medium text-slate-700 transition-colors hover:border-slate-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-600 dark:bg-neutral-950 dark:text-slate-200"
      >
        {label}
        <motion.svg
          animate={{ rotate: open ? 180 : 0 }}
          transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 30 }}
          viewBox="0 0 24 24"
          width="14"
          height="14"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
        >
          <path d="m6 9 6 6 6-6" />
        </motion.svg>
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            role="menu"
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { height: { duration: 0.2, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.15 } }
            }
            className="mt-1.5 w-44 overflow-hidden rounded-lg border border-slate-200 bg-white shadow-lg dark:border-slate-700 dark:bg-neutral-950"
          >
            <div className="scrollbar-thin max-h-32 overflow-y-auto p-1">
              {items.map((item, i) => (
                <div
                  key={item}
                  role="menuitem"
                  tabIndex={-1}
                  onMouseEnter={() => setHighlighted(i)}
                  onClick={() => setOpen(false)}
                  className="relative cursor-pointer rounded-md px-3 py-2 text-sm text-slate-700 dark:text-slate-300"
                >
                  {highlighted === i && (
                    <motion.span
                      layoutId="dropdown-menu-highlight"
                      className="absolute inset-0 rounded-md bg-emerald-50 dark:bg-emerald-500/10"
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 600, damping: 40 }}
                    />
                  )}
                  <span className="relative">{item}</span>
                </div>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  AnimatePresence,
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  type MotionValue,
} from "framer-motion";

const MIN_SIZE = 40;
const MAX_SIZE = 60;
const MAGNET_RADIUS = 140;

export interface DockNavItem {
  id: string;
  label: string;
  icon: (props: { className?: string }) => ReactNode;
}

function DockItem({
  item,
  mouseX,
  isActive,
  reduceMotion,
  onSelect,
}: {
  item: DockNavItem;
  mouseX: MotionValue<number>;
  isActive: boolean;
  reduceMotion: boolean;
  onSelect: () => void;
}) {
  const ref = useRef<HTMLButtonElement>(null);
  const [hovered, setHovered] = useState(false);

  // Distance from the pointer to this icon's own center, recomputed every
  // frame the shared mouseX value changes: this is what lets each icon
  // magnify independently based on real proximity, like the macOS dock.
  const distance = useTransform(mouseX, (val) => {
    const bounds = ref.current?.getBoundingClientRect();
    if (!bounds) return MAGNET_RADIUS;
    return val - bounds.x - bounds.width / 2;
  });
  const sizeTarget = useTransform(distance, [-MAGNET_RADIUS, 0, MAGNET_RADIUS], [MIN_SIZE, MAX_SIZE, MIN_SIZE]);
  const size = useSpring(sizeTarget, reduceMotion ? { stiffness: 1000, damping: 100 } : { mass: 0.15, stiffness: 210, damping: 14 });
  const lift = useTransform(size, [MIN_SIZE, MAX_SIZE], [0, -10]);

  const Icon = item.icon;

  return (
    <div className="relative flex flex-col items-center">
      <AnimatePresence>
        {hovered && (
          <motion.span
            aria-hidden
            initial={{ opacity: 0, y: 4, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 4, scale: 0.9 }}
            transition={{ duration: 0.12 }}
            className="pointer-events-none absolute -top-9 whitespace-nowrap rounded-md bg-slate-900 px-2 py-1 text-[11px] font-medium text-white shadow-md dark:bg-white dark:text-slate-900"
          >
            {item.label}
          </motion.span>
        )}
      </AnimatePresence>

      <motion.button
        ref={ref}
        type="button"
        aria-label={item.label}
        aria-current={isActive ? "page" : undefined}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onFocus={() => setHovered(true)}
        onBlur={() => setHovered(false)}
        onClick={onSelect}
        style={{ width: size, height: size, y: lift }}
        whileTap={{ scale: 0.92 }}
        className="flex items-center justify-center rounded-2xl bg-slate-100 text-slate-500 transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 hover:text-slate-900 dark:bg-white/[0.06] dark:text-slate-400 dark:hover:text-white"
      >
        <Icon className="h-1/2 w-1/2" />
      </motion.button>

      <motion.span
        aria-hidden
        animate={{ opacity: isActive ? 1 : 0, scale: isActive ? 1 : 0.4 }}
        transition={{ duration: 0.15 }}
        className="absolute -bottom-2 h-1 w-1 rounded-full bg-indigo-500 dark:bg-indigo-400"
      />
    </div>
  );
}

/**
 * A floating, physics-magnified dock nav in the shape of macOS's own dock.
 * Renders fixed to the bottom of the viewport and tucks itself away when
 * the page scrolls down, reappearing on the way back up.
 */
export function DockNav({
  items,
  activeId,
  onSelect,
}: {
  items: DockNavItem[];
  activeId?: string;
  onSelect?: (id: string) => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const mouseX = useMotionValue(Infinity);
  const [hidden, setHidden] = useState(false);
  const lastScrollY = useRef(0);

  useEffect(() => {
    lastScrollY.current = window.scrollY;
    const onScroll = () => {
      const y = window.scrollY;
      const delta = y - lastScrollY.current;
      if (y > 80 && delta > 4) setHidden(true);
      else if (delta < -4 || y < 80) setHidden(false);
      lastScrollY.current = y;
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <motion.div
      animate={shouldReduceMotion ? { opacity: 1, y: 0 } : { y: hidden ? 90 : 0, opacity: hidden ? 0 : 1 }}
      transition={{ type: "spring", stiffness: 380, damping: 32 }}
      className="fixed inset-x-0 bottom-6 z-50 flex justify-center"
    >
      <nav
        aria-label="Primary"
        onMouseMove={(e) => !shouldReduceMotion && mouseX.set(e.clientX)}
        onMouseLeave={() => mouseX.set(Infinity)}
        className="flex items-end gap-1 rounded-full border border-slate-200/80 bg-white/90 px-3 py-2.5 shadow-[0_12px_30px_-10px_rgba(15,23,42,0.35)] backdrop-blur-md dark:border-white/10 dark:bg-neutral-900/90"
      >
        {items.map((item) => (
          <DockItem
            key={item.id}
            item={item}
            mouseX={mouseX}
            isActive={activeId === item.id}
            reduceMotion={!!shouldReduceMotion}
            onSelect={() => onSelect?.(item.id)}
          />
        ))}
      </nav>
    </motion.div>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  AnimatePresence,
  motion,
  useMotionTemplate,
  useMotionValue,
  useReducedMotion,
} from "framer-motion";
import { ListIcon as PhList, XIcon as PhX, CaretDownIcon as PhCaretDown } from "@phosphor-icons/react";

function MenuIcon({ className }: { className?: string }) {
  return <PhList aria-hidden className={className} />;
}

function CloseIcon({ className }: { className?: string }) {
  return <PhX aria-hidden className={className} />;
}

function ChevronIcon({ open }: { open: boolean }) {
  return (
    <motion.span
      animate={{ rotate: open ? 180 : 0 }}
      transition={{ type: "spring", stiffness: 500, damping: 32 }}
      className="flex text-slate-400"
    >
      <PhCaretDown size={13} weight="bold" aria-hidden />
    </motion.span>
  );
}

export interface RailNavPanelTile {
  title: string;
  description: string;
  icon: (props: { className?: string }) => ReactNode;
  href?: string;
}

export interface RailNavLink {
  id: string;
  label: string;
  href?: string;
  panel?: RailNavPanelTile[];
}

const COMPACT_BREAKPOINT = 560;

/**
 * A top nav bar whose collapse point is driven by its own rendered width via
 * ResizeObserver rather than a CSS breakpoint: drop it in a sidebar or a
 * split layout and it still switches to the mobile menu correctly. Hovering
 * a link with a `panel` drops a live preview strip beneath the bar, a
 * shared sliding pill tracks whichever link is hovered, and a soft glow
 * follows the pointer along the top edge.
 */
export function RailNav({
  links,
  activeId,
  brandLabel = "Nova",
  brandHref = "/",
  ctaLabel = "Sign in",
  ctaHref = "#",
}: {
  links: RailNavLink[];
  activeId?: string;
  brandLabel?: string;
  brandHref?: string;
  ctaLabel?: string;
  ctaHref?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const rootRef = useRef<HTMLElement>(null);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const [isCompact, setIsCompact] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [openPanel, setOpenPanel] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);

  const beamX = useMotionValue(0);
  const beamOpacity = useMotionValue(0);
  const beamBackground = useMotionTemplate`radial-gradient(220px circle at ${beamX}px 0%, rgba(20,184,166,0.18), transparent 75%)`;

  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new ResizeObserver((entries) => {
      setIsCompact((entries[0]?.contentRect.width ?? 0) < COMPACT_BREAKPOINT);
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!isCompact) setMobileOpen(false);
  }, [isCompact]);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const clearCloseTimer = () => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
  };
  const scheduleClose = () => {
    clearCloseTimer();
    closeTimer.current = setTimeout(() => setOpenPanel(null), 150);
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLElement>) => {
    if (shouldReduceMotion) return;
    const rect = rootRef.current?.getBoundingClientRect();
    if (!rect) return;
    beamX.set(e.clientX - rect.left);
  };

  return (
    <nav
      ref={rootRef}
      aria-label="Primary"
      onMouseMove={handleMouseMove}
      onMouseEnter={() => beamOpacity.set(1)}
      onMouseLeave={() => beamOpacity.set(0)}
      className={`sticky top-0 z-50 flex items-center justify-between gap-3 px-4 py-3.5 transition-colors duration-300 ${
        scrolled
          ? "border-b border-slate-200/80 bg-white/85 backdrop-blur-md dark:border-slate-800 dark:bg-neutral-950/85"
          : "border-b border-transparent bg-transparent"
      }`}
    >
      <motion.div aria-hidden className="pointer-events-none absolute inset-0" style={{ background: beamBackground, opacity: beamOpacity }} />

      <a href={brandHref} className="relative z-10 flex shrink-0 items-center gap-2 rounded-md focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500">
        <span aria-hidden className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-teal-500 to-slate-900 dark:from-teal-400 dark:to-slate-700">
          <span className="h-2 w-2 rounded-sm bg-white/90" />
        </span>
        <span className="text-sm font-semibold tracking-tight text-slate-900 dark:text-white">{brandLabel}</span>
      </a>

      {!isCompact && (
        <div
          className="relative z-10 flex items-center gap-0.5"
          onMouseLeave={() => {
            setHoveredId(null);
            scheduleClose();
          }}
        >
          {links.map((link) => (
            <div key={link.id} className="relative">
              {link.panel ? (
                <button
                  type="button"
                  aria-haspopup="true"
                  aria-expanded={openPanel === link.id}
                  onMouseEnter={() => {
                    setHoveredId(link.id);
                    clearCloseTimer();
                    setOpenPanel(link.id);
                  }}
                  onFocus={() => {
                    setHoveredId(link.id);
                    clearCloseTimer();
                    setOpenPanel(link.id);
                  }}
                  onBlur={scheduleClose}
                  className="relative flex items-center gap-1 rounded-full px-3 py-1.5 text-sm font-medium text-slate-600 transition-colors hover:text-slate-900 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 dark:text-slate-300 dark:hover:text-white"
                >
                  {hoveredId === link.id && (
                    <motion.span
                      layoutId="rail-hover-highlight"
                      className="absolute inset-0 -z-10 rounded-full bg-slate-100 dark:bg-white/[0.07]"
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 38 }}
                    />
                  )}
                  <span className="relative">{link.label}</span>
                  <ChevronIcon open={openPanel === link.id} />
                </button>
              ) : (
                <a
                  href={link.href ?? "#"}
                  aria-current={activeId === link.id ? "page" : undefined}
                  onMouseEnter={() => {
                    setHoveredId(link.id);
                    scheduleClose();
                  }}
                  onFocus={() => {
                    setHoveredId(link.id);
                    scheduleClose();
                  }}
                  className={`relative block rounded-full px-3 py-1.5 text-sm font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 ${
                    activeId === link.id
                      ? "font-semibold text-slate-900 dark:text-white"
                      : "text-slate-600 hover:text-slate-900 dark:text-slate-300 dark:hover:text-white"
                  }`}
                >
                  {hoveredId === link.id && (
                    <motion.span
                      layoutId="rail-hover-highlight"
                      className="absolute inset-0 -z-10 rounded-full bg-slate-100 dark:bg-white/[0.07]"
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 38 }}
                    />
                  )}
                  {link.label}
                  {activeId === link.id && (
                    <span aria-hidden className="absolute inset-x-3 -bottom-[3px] h-[2px] rounded-full bg-teal-500 dark:bg-teal-400" />
                  )}
                </a>
              )}
            </div>
          ))}
        </div>
      )}

      {!isCompact ? (
        <a
          href={ctaHref}
          className="relative z-10 shrink-0 rounded-full bg-slate-900 px-3.5 py-1.5 text-sm font-medium text-white transition-colors hover:bg-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
        >
          {ctaLabel}
        </a>
      ) : (
        <button
          type="button"
          aria-label={mobileOpen ? "Close menu" : "Open menu"}
          aria-expanded={mobileOpen}
          aria-controls="rail-nav-mobile-menu"
          onClick={() => setMobileOpen((v) => !v)}
          className="relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-slate-600 transition-colors hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 dark:text-slate-300 dark:hover:bg-white/10"
        >
          {mobileOpen ? <CloseIcon className="h-5 w-5" /> : <MenuIcon className="h-5 w-5" />}
        </button>
      )}

      <AnimatePresence>
        {!isCompact && openPanel && (
          <motion.div
            role="region"
            aria-label={`${links.find((l) => l.id === openPanel)?.label} preview`}
            initial={{ opacity: 0, y: -4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -4 }}
            transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
            onMouseEnter={clearCloseTimer}
            onMouseLeave={scheduleClose}
            className="absolute inset-x-0 top-full z-10 border-b border-slate-200/80 bg-white shadow-lg dark:border-slate-800 dark:bg-neutral-950"
          >
            <div className="grid grid-cols-3 gap-1 p-3">
              {links
                .find((l) => l.id === openPanel)
                ?.panel?.map((tile) => {
                  const Icon = tile.icon;
                  return (
                    <a
                      key={tile.title}
                      href={tile.href ?? "#"}
                      className="rounded-xl p-3 transition-colors hover:bg-slate-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 dark:hover:bg-white/5"
                    >
                      <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-teal-50 text-teal-600 dark:bg-teal-500/10 dark:text-teal-400">
                        <Icon className="h-4 w-4" />
                      </span>
                      <p className="mt-2 text-sm font-medium text-slate-700 dark:text-slate-200">{tile.title}</p>
                      <p className="mt-0.5 text-xs leading-relaxed text-slate-400 dark:text-slate-500">{tile.description}</p>
                    </a>
                  );
                })}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isCompact && mobileOpen && (
          <motion.div
            id="rail-nav-mobile-menu"
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={shouldReduceMotion ? { duration: 0 } : { height: { duration: 0.22, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.15 } }}
            className="absolute inset-x-0 top-full z-10 overflow-hidden border-b border-slate-200/80 bg-white shadow-lg dark:border-slate-800 dark:bg-neutral-950"
          >
            <ul className="flex flex-col gap-0.5 p-2">
              {links.map((link) => (
                <li key={link.id}>
                  <a
                    href={link.href ?? "#"}
                    aria-current={activeId === link.id ? "page" : undefined}
                    onClick={() => setMobileOpen(false)}
                    className={`block rounded-lg px-3 py-2.5 text-sm transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 ${
                      activeId === link.id
                        ? "bg-teal-50 font-semibold text-teal-700 dark:bg-teal-500/10 dark:text-teal-400"
                        : "font-medium text-slate-600 hover:bg-slate-50 dark:text-slate-300 dark:hover:bg-white/5"
                    }`}
                  >
                    {link.label}
                  </a>
                </li>
              ))}
              <li className="mt-1 border-t border-slate-100 pt-2 dark:border-slate-800">
                <a href={ctaHref} onClick={() => setMobileOpen(false)} className="block rounded-lg bg-slate-900 px-3 py-2.5 text-center text-sm font-medium text-white dark:bg-white dark:text-slate-900">
                  {ctaLabel}
                </a>
              </li>
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  ListIcon as PhList,
  XIcon as PhX,
  MagnifyingGlassIcon as PhMagnifyingGlass,
  GearIcon as PhGear,
  UserIcon as PhUser,
  CaretDownIcon as PhCaretDown,
  CheckIcon as PhCheck,
} from "@phosphor-icons/react";

const COLLAPSED_WIDTH = 64;
const DEFAULT_WIDTH = 232;
const MIN_WIDTH = 200;
const MAX_WIDTH = 320;
const COLLAPSE_THRESHOLD = 140;
const MOBILE_QUERY = "(max-width: 768px)";

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function MenuIcon({ className }: { className?: string }) {
  return <PhList aria-hidden className={className} />;
}

function CloseIcon({ className }: { className?: string }) {
  return <PhX aria-hidden className={className} />;
}

function SearchIcon({ className }: { className?: string }) {
  return <PhMagnifyingGlass aria-hidden className={className} />;
}

function GearIcon({ className }: { className?: string }) {
  return <PhGear aria-hidden className={className} />;
}

function UserIcon({ className }: { className?: string }) {
  return <PhUser aria-hidden className={className} />;
}

function ChevronIcon({ open }: { open: boolean }) {
  return (
    <motion.span
      animate={{ rotate: open ? 180 : 0 }}
      transition={{ type: "spring", stiffness: 500, damping: 32 }}
      className="flex shrink-0 text-slate-400"
    >
      <PhCaretDown size={13} weight="bold" aria-hidden />
    </motion.span>
  );
}

function CheckIcon({ className }: { className?: string }) {
  return <PhCheck weight="bold" aria-hidden className={className} />;
}

export interface SidebarNavItem {
  id: string;
  label: string;
  icon: (props: { className?: string }) => ReactNode;
  badge?: number;
}

export interface SidebarNavGroup {
  label: string;
  items: SidebarNavItem[];
}

type PresenceId = "online" | "away" | "dnd" | "offline";

interface PresenceOption {
  id: PresenceId;
  label: string;
  dotClass: string;
  textClass: string;
}

const PRESENCE_OPTIONS: PresenceOption[] = [
  { id: "online", label: "Online", dotClass: "bg-emerald-500", textClass: "text-emerald-600 dark:text-emerald-400" },
  { id: "away", label: "Away", dotClass: "bg-amber-500", textClass: "text-amber-600 dark:text-amber-400" },
  { id: "dnd", label: "Do not disturb", dotClass: "bg-rose-500", textClass: "text-rose-600 dark:text-rose-400" },
  { id: "offline", label: "Offline", dotClass: "bg-slate-400 dark:bg-slate-600", textClass: "text-slate-400 dark:text-slate-500" },
];

function WorkspaceSwitcher({ workspaces }: { workspaces: string[] }) {
  const [open, setOpen] = useState(false);
  const [workspace, setWorkspace] = useState(workspaces[0]);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  return (
    <div ref={rootRef} className="relative min-w-0">
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        onKeyDown={(e) => {
          if (e.key === "Escape") setOpen(false);
        }}
        className="flex w-full min-w-0 items-center gap-2 rounded-lg py-1.5 pr-1.5 text-left transition-colors hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/5"
      >
        <span aria-hidden className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md bg-gradient-to-br from-emerald-500 to-slate-900 text-[11px] font-semibold text-white dark:from-emerald-400 dark:to-slate-700">
          {workspace[0]}
        </span>
        <span className="min-w-0 flex-1 truncate text-sm font-semibold text-slate-900 dark:text-white">{workspace}</span>
        {workspaces.length > 1 && <ChevronIcon open={open} />}
      </button>

      <AnimatePresence>
        {open && workspaces.length > 1 && (
          <motion.div
            role="listbox"
            aria-label="Workspaces"
            initial={{ opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.98 }}
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 34 }}
            className="absolute left-0 top-full z-30 mt-1 w-48 overflow-hidden rounded-lg border border-slate-200 bg-white p-1 shadow-lg dark:border-slate-700 dark:bg-neutral-900"
          >
            {workspaces.map((name) => (
              <button
                key={name}
                type="button"
                role="option"
                aria-selected={workspace === name}
                onClick={() => {
                  setWorkspace(name);
                  setOpen(false);
                }}
                className="flex w-full items-center justify-between gap-2 rounded-md px-2.5 py-1.5 text-left text-sm text-slate-700 transition-colors hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-white/5"
              >
                {name}
                {workspace === name && <CheckIcon className="h-3.5 w-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />}
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function PresenceSwitcher({ collapsed, userName }: { collapsed: boolean; userName: string }) {
  const [open, setOpen] = useState(false);
  const [status, setStatus] = useState<PresenceId>("online");
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const current = PRESENCE_OPTIONS.find((option) => option.id === status)!;

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  return (
    <div ref={rootRef} className="relative">
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={collapsed ? `Status: ${current.label}` : undefined}
        onClick={() => setOpen((v) => !v)}
        onKeyDown={(e) => {
          if (e.key === "Escape") setOpen(false);
        }}
        className="flex w-full min-w-0 items-center gap-2.5 rounded-lg py-1.5 pr-1.5 text-left transition-colors hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/5"
      >
        <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-emerald-500 to-slate-900 text-white dark:from-emerald-400 dark:to-slate-700">
          <UserIcon className="h-[18px] w-[18px]" />
          <motion.span
            aria-hidden
            animate={{ scale: 1 }}
            initial={false}
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 28 }}
            className={`absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full ring-2 ring-white dark:ring-neutral-950 ${current.dotClass}`}
          />
        </span>
        <motion.span
          animate={{ width: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
          className="flex min-w-0 flex-1 items-center justify-between gap-2 overflow-hidden whitespace-nowrap"
        >
          <span className="min-w-0">
            <span className="block truncate text-xs font-medium text-slate-700 dark:text-slate-200">{userName}</span>
            <span className={`block truncate text-[11px] font-medium ${current.textClass}`}>{current.label}</span>
          </span>
          <ChevronIcon open={open} />
        </motion.span>
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            role="listbox"
            aria-label="Set status"
            initial={{ opacity: 0, y: 4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 4, scale: 0.98 }}
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 34 }}
            className="absolute bottom-full left-0 z-30 mb-1 w-44 overflow-hidden rounded-lg border border-slate-200 bg-white p-1 shadow-lg dark:border-slate-700 dark:bg-neutral-900"
          >
            {PRESENCE_OPTIONS.map((option) => (
              <button
                key={option.id}
                type="button"
                role="option"
                aria-selected={status === option.id}
                onClick={() => {
                  setStatus(option.id);
                  setOpen(false);
                }}
                className="flex w-full items-center gap-2 rounded-md px-2.5 py-1.5 text-left text-sm text-slate-700 transition-colors hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-white/5"
              >
                <span aria-hidden className={`h-2 w-2 shrink-0 rounded-full ${option.dotClass}`} />
                <span className="min-w-0 flex-1 truncate">{option.label}</span>
                {status === option.id && <CheckIcon className="h-3.5 w-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />}
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function NavRow({
  item,
  active,
  collapsed,
  onSelect,
}: {
  item: SidebarNavItem;
  active: boolean;
  collapsed: boolean;
  onSelect: () => void;
}) {
  const [hovered, setHovered] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const Icon = item.icon;
  const accessibleLabel = collapsed ? (item.badge !== undefined ? `${item.label}, ${item.badge} unread` : item.label) : undefined;

  return (
    <div className="relative">
      <button
        type="button"
        aria-current={active ? "page" : undefined}
        aria-label={accessibleLabel}
        onClick={onSelect}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onFocus={() => setHovered(true)}
        onBlur={() => setHovered(false)}
        className={`relative flex w-full items-center rounded-lg py-2 pr-2.5 text-sm transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
          active ? "text-slate-900 dark:text-white" : "text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200"
        }`}
      >
        {active && (
          <motion.span
            layoutId="sidebar-nav-active-highlight"
            className="absolute inset-0 -z-10 rounded-lg bg-emerald-50 dark:bg-emerald-500/10"
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 38 }}
          />
        )}
        <span className="relative flex h-9 w-9 shrink-0 items-center justify-center">
          <Icon className="h-[18px] w-[18px]" />
          {item.badge !== undefined && collapsed && (
            <span aria-hidden className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-emerald-500" />
          )}
        </span>
        <motion.span
          animate={{ width: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
          className="relative flex flex-1 items-center justify-between gap-2 overflow-hidden whitespace-nowrap"
        >
          <span>{item.label}</span>
          {item.badge !== undefined && (
            <span className="shrink-0 rounded-full bg-emerald-100 px-1.5 py-0.5 text-[11px] font-medium text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300">
              {item.badge}
            </span>
          )}
        </motion.span>
      </button>

      <span className="pointer-events-none absolute left-full top-1/2 z-30 ml-2 -translate-y-1/2">
        <AnimatePresence>
          {collapsed && hovered && (
            <motion.span
              aria-hidden
              initial={{ opacity: 0, x: -4 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -4 }}
              transition={{ duration: 0.12 }}
              className="block whitespace-nowrap rounded-md bg-slate-900 px-2 py-1 text-[11px] font-medium text-white shadow-md dark:bg-white dark:text-slate-900"
            >
              {item.label}
            </motion.span>
          )}
        </AnimatePresence>
      </span>
    </div>
  );
}

function SidebarContent({
  groups,
  workspaces,
  userName,
  collapsed,
  activeId,
  onSelect,
  onToggleCollapsed,
  onClose,
}: {
  groups: SidebarNavGroup[];
  workspaces: string[];
  userName: string;
  collapsed: boolean;
  activeId?: string;
  onSelect: (id: string) => void;
  onToggleCollapsed?: () => void;
  onClose?: () => void;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="flex h-full min-w-0 flex-col">
      <div className="flex items-center gap-1 border-b border-slate-100 py-3 pl-2.5 pr-2 dark:border-slate-800">
        <button
          type="button"
          aria-pressed={onClose ? undefined : collapsed}
          aria-label={onClose ? "Close menu" : collapsed ? "Expand sidebar" : "Collapse sidebar"}
          onClick={onClose ?? onToggleCollapsed}
          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-500 transition-colors hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-white/5"
        >
          {onClose ? <CloseIcon className="h-[18px] w-[18px]" /> : <MenuIcon className="h-[18px] w-[18px]" />}
        </button>
        <motion.div
          animate={{ width: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
          className="min-w-0 flex-1 overflow-hidden"
        >
          <WorkspaceSwitcher workspaces={workspaces} />
        </motion.div>
      </div>

      <motion.div
        animate={{ height: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
        transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
        className="overflow-hidden px-3"
      >
        <div className="relative pt-3">
          <SearchIcon className="pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            placeholder="Search"
            aria-label="Search"
            className="w-full rounded-lg border border-slate-200 bg-white py-1.5 pl-8 pr-2 text-xs text-slate-700 outline-none transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:bg-neutral-900 dark:text-slate-200 dark:placeholder:text-slate-500"
          />
        </div>
      </motion.div>

      <nav aria-label="Primary" className={`min-h-0 flex-1 px-2 py-3 ${collapsed ? "overflow-visible" : "overflow-y-auto"}`}>
        {groups.map((group) => (
          <div key={group.label} className="mb-4 last:mb-0">
            <motion.p
              animate={{ height: collapsed ? 0 : "auto", opacity: collapsed ? 0 : 1 }}
              transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              className="overflow-hidden px-2.5 text-[10px] font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500"
            >
              <span className="block pb-1.5">{group.label}</span>
            </motion.p>
            <div className="space-y-0.5">
              {group.items.map((item) => (
                <NavRow key={item.id} item={item} active={activeId === item.id} collapsed={collapsed} onSelect={() => onSelect(item.id)} />
              ))}
            </div>
          </div>
        ))}
      </nav>

      <div className="border-t border-slate-100 px-2 py-3 dark:border-slate-800">
        <NavRow
          item={{ id: "settings", label: "Settings", icon: GearIcon }}
          active={activeId === "settings"}
          collapsed={collapsed}
          onSelect={() => onSelect("settings")}
        />
        <div className="mt-1">
          <PresenceSwitcher collapsed={collapsed} userName={userName} />
        </div>
      </div>
    </div>
  );
}

/**
 * A left app-shell sidebar in the mold of Linear/Notion/Vercel: persistently
 * collapsible to an icon rail on desktop (drop it inside a `flex h-screen`
 * shell), resizable by dragging its right edge (drag past the collapse
 * point and it snaps into the rail), and a hamburger-triggered slide-in
 * drawer on narrow viewports. Renders nothing inline on mobile besides a
 * small fixed trigger: the drawer itself is a fixed overlay, so it works
 * regardless of where it's mounted in the tree.
 */
export function SidebarNav({
  groups,
  activeId,
  onSelect,
  workspaces = ["Workspace"],
  userName = "You",
}: {
  groups: SidebarNavGroup[];
  activeId?: string;
  onSelect?: (id: string) => void;
  workspaces?: string[];
  userName?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [isMobile, setIsMobile] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [width, setWidth] = useState(DEFAULT_WIDTH);
  const [isDragging, setIsDragging] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const asideRef = useRef<HTMLElement>(null);
  const dragRawRef = useRef(width);

  useEffect(() => {
    const mq = window.matchMedia(MOBILE_QUERY);
    const update = () => setIsMobile(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  useEffect(() => {
    if (!isMobile) setDrawerOpen(false);
  }, [isMobile]);

  useEffect(() => {
    if (!drawerOpen) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setDrawerOpen(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [drawerOpen]);

  const handleSelect = (id: string) => onSelect?.(id);

  const handleResizePointerDown = (e: React.PointerEvent) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    const asideEl = asideRef.current;
    if (!asideEl) return;
    const left = asideEl.getBoundingClientRect().left;
    dragRawRef.current = width;
    setIsDragging(true);
    document.body.style.userSelect = "none";

    const onMove = (ev: PointerEvent) => {
      const raw = ev.clientX - left;
      dragRawRef.current = raw;
      setWidth(clamp(raw, MIN_WIDTH, MAX_WIDTH));
    };
    const onUp = () => {
      document.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerup", onUp);
      document.body.style.userSelect = "";
      setIsDragging(false);
      if (dragRawRef.current < COLLAPSE_THRESHOLD) {
        setCollapsed(true);
        setWidth(DEFAULT_WIDTH);
      }
    };
    document.addEventListener("pointermove", onMove);
    document.addEventListener("pointerup", onUp);
  };

  const handleResizeKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      setWidth((w) => clamp(w - 16, MIN_WIDTH, MAX_WIDTH));
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      setWidth((w) => clamp(w + 16, MIN_WIDTH, MAX_WIDTH));
    } else if (e.key === "Home") {
      e.preventDefault();
      setCollapsed(true);
    } else if (e.key === "End") {
      e.preventDefault();
      setWidth(MAX_WIDTH);
    }
  };

  if (isMobile) {
    return (
      <>
        <button
          type="button"
          aria-label="Open menu"
          aria-expanded={drawerOpen}
          aria-controls="sidebar-nav-drawer"
          onClick={() => setDrawerOpen(true)}
          className="fixed left-3 top-3 z-40 flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-600 shadow-sm transition-colors hover:bg-slate-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:bg-neutral-950 dark:text-slate-300 dark:hover:bg-neutral-900"
        >
          <MenuIcon className="h-[18px] w-[18px]" />
        </button>
        <AnimatePresence>
          {drawerOpen && (
            <>
              <motion.div
                key="backdrop"
                aria-hidden
                onClick={() => setDrawerOpen(false)}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: shouldReduceMotion ? 0.1 : 0.2 }}
                className="fixed inset-0 z-40 bg-slate-950/40 backdrop-blur-sm"
              />
              <motion.aside
                id="sidebar-nav-drawer"
                key="drawer"
                initial={shouldReduceMotion ? { opacity: 0 } : { x: "-100%" }}
                animate={shouldReduceMotion ? { opacity: 1 } : { x: 0 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { x: "-100%" }}
                transition={{ type: "spring", stiffness: 380, damping: 36 }}
                style={{ width: DEFAULT_WIDTH }}
                className="fixed inset-y-0 left-0 z-50 border-r border-slate-200 bg-white shadow-2xl dark:border-slate-800 dark:bg-neutral-950"
              >
                <SidebarContent
                  groups={groups}
                  workspaces={workspaces}
                  userName={userName}
                  collapsed={false}
                  activeId={activeId}
                  onSelect={(id) => {
                    handleSelect(id);
                    setDrawerOpen(false);
                  }}
                  onClose={() => setDrawerOpen(false)}
                />
              </motion.aside>
            </>
          )}
        </AnimatePresence>
      </>
    );
  }

  return (
    <motion.aside
      ref={asideRef}
      animate={{ width: collapsed ? COLLAPSED_WIDTH : width }}
      transition={isDragging || shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 360, damping: 34 }}
      className="relative h-full shrink-0 border-r border-slate-100 bg-slate-50/60 dark:border-slate-800 dark:bg-neutral-900/40"
    >
      <SidebarContent
        groups={groups}
        workspaces={workspaces}
        userName={userName}
        collapsed={collapsed}
        activeId={activeId}
        onSelect={handleSelect}
        onToggleCollapsed={() => setCollapsed((v) => !v)}
      />

      {!collapsed && (
        <div
          role="separator"
          aria-orientation="vertical"
          aria-label="Resize sidebar"
          aria-valuenow={Math.round(width)}
          aria-valuemin={MIN_WIDTH}
          aria-valuemax={MAX_WIDTH}
          tabIndex={0}
          onPointerDown={handleResizePointerDown}
          onKeyDown={handleResizeKeyDown}
          className="group absolute right-0 top-0 z-20 h-full w-2 translate-x-1/2 cursor-col-resize touch-none focus-visible:outline focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-emerald-600"
        >
          <span
            aria-hidden
            className={`mx-auto block h-full w-px transition-colors ${
              isDragging ? "bg-emerald-500" : "bg-transparent group-hover:bg-emerald-400/70"
            }`}
          />
        </div>
      )}
    </motion.aside>
  );
}

