import { useCallback, useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { CheckIcon as PhCheck } from "@phosphor-icons/react";

const DURATION = 4000;

export function useToast() {
  const [visible, setVisible] = useState(false);
  const [key, setKey] = useState(0);
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const dismiss = useCallback(() => {
    setVisible(false);
    clearTimeout(timerRef.current);
  }, []);

  const show = useCallback(() => {
    setKey((k) => k + 1);
    setVisible(true);
    clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setVisible(false), DURATION);
  }, []);

  useEffect(() => () => clearTimeout(timerRef.current), []);

  return { visible, key, show, dismiss };
}

export function Toast({
  visible,
  onDismiss,
  title,
  description,
}: {
  visible: boolean;
  onDismiss: () => void;
  title: string;
  description: string;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="pointer-events-none fixed right-4 top-4 z-50">
      <AnimatePresence>
        {visible && (
          <motion.div
            role="status"
            drag="x"
            dragConstraints={{ left: 0, right: 0 }}
            dragElastic={{ left: 0, right: 0.5 }}
            onDragEnd={(_, info) => {
              if (info.offset.x > 60) onDismiss();
            }}
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, x: 40, scale: 0.95 }}
            animate={{ opacity: 1, x: 0, scale: 1 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, x: 60, scale: 0.95 }}
            transition={{ type: "spring", stiffness: 420, damping: 32 }}
            className="pointer-events-auto relative w-64 cursor-grab overflow-hidden rounded-xl border border-slate-200 bg-white p-3.5 shadow-lg active:cursor-grabbing dark:border-slate-700 dark:bg-neutral-950"
          >
            <div className="flex items-start gap-2.5">
              <span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400">
                <PhCheck size={14} weight="bold" aria-hidden />
              </span>
              <div className="flex-1">
                <p className="text-sm font-medium text-slate-900 dark:text-white">{title}</p>
                <p className="text-xs text-slate-500 dark:text-slate-400">{description}</p>
              </div>
            </div>
            <div className="absolute inset-x-0 bottom-0 h-0.5 bg-slate-100 dark:bg-neutral-900">
              <motion.div
                className="h-full bg-emerald-500"
                initial={{ scaleX: 1 }}
                animate={{ scaleX: 0 }}
                style={{ transformOrigin: "left" }}
                transition={shouldReduceMotion ? { duration: 0 } : { duration: DURATION / 1000, ease: "linear" }}
              />
            </div>
          </motion.div>
        )}
      </AnimatePresence>
