  additions: number;
  deletions: number;
  url?: string;
}

function pseudoHash(input: string) {
  let h = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0").slice(0, 7);
}

function AgentIcon() {
  return <PhSparkle size={13} weight="fill" aria-hidden />;
}

function BranchIcon() {
