      <span className="h-full bg-emerald-500" style={{ width: `${addPct}%` }} />
    </span>
  );
}

export function Commit({
  subject,
  body,
  files,
  branch = "main",
  autoPlay = true,
  repoUrl,
}: {
  subject: string;
  body?: string;
  files: ChangedFile[];
  branch?: string;
  autoPlay?: boolean;
  /** Base repo URL (e.g. "https://github.com/org/repo") used to derive a file's GitHub link when it has no explicit url. */
  repoUrl?: string;
}) {
  const [playId, setPlayId] = useState(0);
  return (
    <CommitRun
      key={playId}
      subject={subject}
      body={body}
      files={files}
      branch={branch}
      autoPlay={autoPlay}
      repoUrl={repoUrl}
      onReplay={() => setPlayId((id) => id + 1)}
    />
  );
}

function CommitRun({
  subject,
  body,
  files,
  branch,
  autoPlay,
  repoUrl,
  onReplay,
}: {
  subject: string;
  body?: string;
  files: ChangedFile[];
  branch: string;
  autoPlay: boolean;
  repoUrl?: string;
  onReplay: () => void;
}) {
  const fullText = useMemo(() => (body ? `${subject}\n\n${body}` : subject), [subject, body]);
  const words = useMemo(() => fullText.split(" "), [fullText]);
  const [revealed, setRevealed] = useState(autoPlay ? 0 : words.length);
  const [committed, setCommitted] = useState(!autoPlay);
  const [filesOpen, setFilesOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const filesId = "commit-files-panel";

  const delays = useMemo(() => words.map((w, i) => 30 + ((w.length * 7 + i * 3) % 40)), [words]);
  const hash = useMemo(() => pseudoHash(fullText), [fullText]);
  const totals = useMemo(
    () => files.reduce((acc, f) => ({ additions: acc.additions + f.additions, deletions: acc.deletions + f.deletions }), { additions: 0, deletions: 0 }),
    [files]
  );

  useEffect(() => {
    if (!autoPlay) return;
    let cancelled = false;

    if (shouldReduceMotion) {
      const t = setTimeout(() => {
        if (cancelled) return;
        setRevealed(words.length);
        setCommitted(true);
      }, 0);
      return () => {
        cancelled = true;
        clearTimeout(t);
      };
    }

    let i = 0;
    const step = () => {
      if (cancelled) return;
      i += 1;
      setRevealed(i);
      if (i >= words.length) {
        setTimeout(() => !cancelled && setCommitted(true), 400);
        return;
      }
      timeout = setTimeout(step, delays[i] ?? 40);
    };
    let timeout = setTimeout(step, delays[0] ?? 40);
    return () => {
      cancelled = true;
      clearTimeout(timeout);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPlay, words.length, delays, shouldReduceMotion]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(hash);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {
      // Clipboard API unavailable ; no-op
    }
  };

  const visibleText = words.slice(0, revealed).join(" ");
  const [visibleSubject, ...visibleBodyParts] = visibleText.split("\n\n");
  const visibleBody = visibleBodyParts.join("\n\n");

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-4 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="mb-3 flex items-center gap-2">
        <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-500 dark:text-emerald-400">
          <AgentIcon />
        </span>
        <span className="text-sm font-medium text-slate-700 dark:text-slate-200">Assistant</span>
        {repoUrl ? (
          <a
            href={`${repoUrl}/tree/${branch}`}
            target="_blank"
            rel="noopener noreferrer"
            title={`View ${branch} branch on GitHub`}
            className="inline-flex items-center gap-1 rounded-full border border-slate-200 px-2 py-0.5 text-[11px] font-medium text-slate-500 transition-colors hover:border-slate-300 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:text-slate-400 dark:hover:border-white/20 dark:hover:text-slate-200"
          >
            <BranchIcon />
            {branch}
          </a>
        ) : (
          <span className="inline-flex items-center gap-1 rounded-full border border-slate-200 px-2 py-0.5 text-[11px] font-medium text-slate-500 dark:border-white/10 dark:text-slate-400">
            <BranchIcon />
            {branch}
          </span>
        )}
        <span className="ml-auto text-xs text-slate-400 dark:text-slate-500">Just now</span>
      </div>

      <div className="min-h-[4.5rem]">
        <p className="text-sm font-semibold text-slate-800 dark:text-slate-100">
          {visibleSubject}
          {!committed && <span className="text-slate-300 dark:text-slate-600">|</span>}
        </p>
        {visibleBody && <p className="mt-1 text-xs leading-relaxed text-slate-500 dark:text-slate-400">{visibleBody}</p>}
      </div>

      <AnimatePresence>
        {committed && (
          <motion.div
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
          >
            <div className="mt-3 flex items-center gap-2 border-t border-slate-100 pt-3 dark:border-white/5">
              {repoUrl ? (
                <span className="inline-flex items-center gap-1 rounded-md bg-black/[0.04] py-1 pl-2 pr-1 dark:bg-white/[0.06]">
                  <a
                    href={`${repoUrl}/commit/${hash}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    title={`View commit ${hash} on GitHub`}
                    className="font-mono text-xs text-slate-600 underline-offset-2 transition-colors hover:text-slate-800 hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-300 dark:hover:text-slate-100"
                  >
                    {hash}
                  </a>
                  <button
                    type="button"
                    onClick={handleCopy}
                    aria-label={copied ? "Commit hash copied" : "Copy commit hash"}
                    title={copied ? "Commit hash copied" : "Copy commit hash"}
                    className="inline-flex h-5 w-5 items-center justify-center rounded text-slate-500 transition-colors hover:bg-black/[0.06] hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-200"
                  >
                    {copied ? <CheckIcon /> : <CopyIcon />}
                  </button>
                </span>
              ) : (
                <button
                  type="button"
                  onClick={handleCopy}
                  aria-label={copied ? "Commit hash copied" : "Copy commit hash"}
                  title={copied ? "Commit hash copied" : "Copy commit hash"}
                  className="inline-flex items-center gap-1.5 rounded-md bg-black/[0.04] px-2 py-1 font-mono text-xs text-slate-600 transition-colors hover:bg-black/[0.07] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:bg-white/[0.06] dark:text-slate-300 dark:hover:bg-white/10"
                >
                  {copied ? <CheckIcon /> : <CopyIcon />}
                  {hash}
                </button>
              )}
              <span className="text-xs text-slate-400 dark:text-slate-500">
                <span className="font-medium text-emerald-600 dark:text-emerald-400">+{totals.additions}</span>{" "}
                <span className="font-medium">−{totals.deletions}</span>
              </span>
              <StatsBar additions={totals.additions} deletions={totals.deletions} />
              {autoPlay && (
                <button
                  type="button"
                  onClick={onReplay}
                  aria-label="Replay commit"
                  className="ml-auto inline-flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
                >
                  <ReplayIcon />
                </button>
              )}
            </div>

            <button
              type="button"
              onClick={() => setFilesOpen((v) => !v)}
              aria-expanded={filesOpen}
              aria-controls={filesId}
              className="mt-2 flex w-full items-center gap-1.5 rounded-md px-1 py-1 text-left text-xs font-medium text-slate-500 transition-colors hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:text-slate-200"
            >
              <motion.span animate={{ rotate: filesOpen ? 90 : 0 }} transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}>
                <ChevronIcon />
              </motion.span>
              {files.length} files changed
            </button>

            <AnimatePresence initial={false}>
              {filesOpen && (
                <motion.div
                  id={filesId}
                  initial={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
                  animate={shouldReduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
                  transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.4, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.28, ease: [0.22, 1, 0.36, 1] } }}
                  className="overflow-hidden"
                >
                  <motion.ul
                    initial={shouldReduceMotion ? undefined : { y: -8 }}
                    animate={{ y: 0 }}
                    transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.35, ease: [0.22, 1, 0.36, 1], delay: 0.06 }}
                    className="mt-1 flex flex-col gap-1 pl-1"
                    role="list"
                  >
                    {files.map((f, i) => {
                      const url = f.url ?? (repoUrl ? `${repoUrl}/blob/${hash}/${f.path}` : undefined);
                      return (
                        <motion.li
                          key={f.path}
                          initial={shouldReduceMotion ? undefined : { opacity: 0, y: -6 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.28, delay: 0.1 + i * 0.05, ease: [0.22, 1, 0.36, 1] }}
                          className="flex items-center gap-2 text-xs"
                        >
                          {url ? (
                            <a
                              href={url}
                              target="_blank"
                              rel="noopener noreferrer"
                              title={`Open ${f.path} on GitHub`}
                              className="group/file inline-flex min-w-0 items-center gap-1 truncate rounded font-mono text-slate-500 underline-offset-2 hover:text-slate-700 hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:text-slate-200"
                            >
                              <span className="truncate">{f.path}</span>
                              <ExternalLinkIcon />
                            </a>
                          ) : (
                            <span className="truncate font-mono text-slate-500 dark:text-slate-400">{f.path}</span>
                          )}
                          <span className="ml-auto shrink-0 text-slate-400 dark:text-slate-500">
                            <span className="text-emerald-600 dark:text-emerald-400">+{f.additions}</span> −{f.deletions}
                          </span>
                          <StatsBar additions={f.additions} deletions={f.deletions} />
                        </motion.li>
                      );
                    })}
                  </motion.ul>
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { CaretRightIcon as PhCaretRight, FolderIcon as PhFolder, FolderOpenIcon as PhFolderOpen, FileIcon as PhFile } from "@phosphor-icons/react";

type FileStatus = "new" | "modified" | "deleted";

interface TreeNode {
  name: string;
  type: "folder" | "file";
  status?: FileStatus;
  children?: TreeNode[];
}

function ChevronIcon() {
  return <PhCaretRight size={12} weight="bold" aria-hidden />;
}

function FolderIcon({ open }: { open: boolean }) {
  return open ? <PhFolderOpen size={15} aria-hidden /> : <PhFolder size={15} aria-hidden />;
}

function FileIcon() {
  return <PhFile size={14} aria-hidden />;
}

interface FileTypeMeta {
  label: string;
  className: string;
}

const FILE_TYPE_MAP: Record<string, FileTypeMeta> = {
  ts: { label: "TS", className: "bg-blue-500 text-white" },
  tsx: { label: "TSX", className: "bg-sky-500 text-white" },
  js: { label: "JS", className: "bg-yellow-400 text-neutral-900" },
  jsx: { label: "JSX", className: "bg-amber-400 text-neutral-900" },
  json: { label: "{}", className: "bg-amber-600 text-white" },
  css: { label: "#", className: "bg-blue-400 text-white" },
  scss: { label: "#", className: "bg-pink-400 text-white" },
  html: { label: "<>", className: "bg-orange-500 text-white" },
  md: { label: "M↓", className: "bg-slate-400 text-white" },
  yml: { label: "YML", className: "bg-violet-400 text-white" },
  yaml: { label: "YML", className: "bg-violet-400 text-white" },
  env: { label: "ENV", className: "bg-lime-600 text-white" },
  py: { label: "PY", className: "bg-indigo-500 text-white" },
  svg: { label: "SVG", className: "bg-purple-400 text-white" },
  png: { label: "IMG", className: "bg-purple-400 text-white" },
  jpg: { label: "IMG", className: "bg-purple-400 text-white" },
  jpeg: { label: "IMG", className: "bg-purple-400 text-white" },
  gif: { label: "IMG", className: "bg-purple-400 text-white" },
  webp: { label: "IMG", className: "bg-purple-400 text-white" },
};

function getFileTypeMeta(name: string): FileTypeMeta | null {
  const lower = name.toLowerCase();
  if (lower === "package.json") return { label: "PKG", className: "bg-red-500 text-white" };
  if (/\.(test|spec)\.[jt]sx?$/.test(lower)) return { label: "✓", className: "bg-emerald-500 text-white" };
  const dotIndex = lower.lastIndexOf(".");
  if (dotIndex === -1) return null;
  return FILE_TYPE_MAP[lower.slice(dotIndex + 1)] ?? null;
}

function badgeFontSize(label: string) {
  if (label.length <= 1) return "text-[8px]";
  if (label.length === 2) return "text-[7px]";
  if (label.length === 3) return "text-[6px]";
  return "text-[5px]";
}

function FileTypeIcon({ name }: { name: string }) {
  const meta = getFileTypeMeta(name);
  if (!meta) {
    return (
      <span className="text-slate-400 dark:text-slate-500">
        <FileIcon />
      </span>
    );
  }
  return (
    <span
      aria-hidden
      className={`flex h-3.5 w-3.5 shrink-0 items-center justify-center rounded-[3px] font-bold leading-none tracking-tighter ${badgeFontSize(meta.label)} ${meta.className}`}
    >
      {meta.label}
    </span>
  );
}

const STATUS_TONE: Record<FileStatus, string> = {
  new: "text-emerald-600 dark:text-emerald-400",
  modified: "text-amber-600 dark:text-amber-400",
  deleted: "text-slate-400 dark:text-slate-500",
};

const STATUS_LABEL: Record<FileStatus, string> = {
  new: "new",
  modified: "modified",
  deleted: "deleted",
};

interface FlatRow {
  node: TreeNode;
  depth: number;
  path: string;
}

function flatten(nodes: TreeNode[], depth: number, parentPath: string, collapsed: Set<string>, out: FlatRow[]) {
  for (const node of nodes) {
    const path = parentPath ? `${parentPath}/${node.name}` : node.name;
    out.push({ node, depth, path });
    if (node.type === "folder" && node.children && !collapsed.has(path)) {
      flatten(node.children, depth + 1, path, collapsed, out);
    }
  }
}

export function FileTree({ tree, rootLabel }: { tree: TreeNode[]; rootLabel?: string }) {
  const [collapsed, setCollapsed] = useState<Set<string>>(new Set());
  const [selected, setSelected] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const rows = useMemo(() => {
    const out: FlatRow[] = [];
    flatten(tree, 0, "", collapsed, out);
    return out;
  }, [tree, collapsed]);

  const toggleFolder = (path: string) => {
    setCollapsed((prev) => {
      const next = new Set(prev);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  };

  return (
    <div className="w-full max-w-sm rounded-2xl border border-slate-200/70 bg-white/95 p-2 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      {rootLabel && <p className="px-2 pb-1.5 pt-1 font-mono text-xs font-semibold text-slate-400 dark:text-slate-500">{rootLabel}</p>}
      <ul role="tree" aria-label="File tree" className="flex flex-col">
        {rows.map((row, i) => {
          const { node, depth, path } = row;
          const isFolder = node.type === "folder";
          const isOpen = isFolder && !collapsed.has(path);
          const isSelected = selected === path;
          return (
            <motion.li
              key={path}
              role="treeitem"
              aria-selected={!isFolder && isSelected}
              aria-expanded={isFolder ? isOpen : undefined}
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, x: -8 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.22, delay: Math.min(i, 12) * 0.045, ease: [0.16, 1, 0.3, 1] }}
            >
              <button
                type="button"
                onClick={() => (isFolder ? toggleFolder(path) : setSelected(path))}
                style={{ paddingLeft: `${depth * 16 + 8}px` }}
                className={`group flex w-full items-center gap-1.5 rounded-md py-1.5 pr-2 text-left transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-emerald-600 ${
                  isSelected ? "bg-emerald-500/10" : "hover:bg-black/[0.03] dark:hover:bg-white/5"
                }`}
              >
                {isFolder ? (
                  <motion.span
                    animate={{ rotate: isOpen ? 90 : 0 }}
                    transition={{ duration: 0.15 }}
                    className="shrink-0 text-slate-400"
                  >
                    <ChevronIcon />
                  </motion.span>
                ) : (
                  <span className="w-3 shrink-0" />
                )}
                <span
                  className={`shrink-0 ${
                    isFolder ? "text-slate-400 dark:text-slate-500" : node.status === "deleted" ? "opacity-60" : ""
                  }`}
                >
                  {isFolder ? <FolderIcon open={isOpen} /> : <FileTypeIcon name={node.name} />}
                </span>
                <span
                  className={`truncate text-sm ${
                    node.status === "deleted" ? "text-slate-400 line-through dark:text-slate-500" : "text-slate-700 dark:text-slate-200"
                  } ${isFolder ? "font-medium" : ""}`}
                >
                  {node.name}
                </span>
                {!isFolder && node.status && (
                  <span className={`ml-auto shrink-0 text-[10px] font-medium uppercase tracking-wide ${STATUS_TONE[node.status]}`}>
                    {STATUS_LABEL[node.status]}
                  </span>
                )}
              </button>
            </motion.li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  PackageIcon as PhPackage,
  CheckIcon as PhCheck,
  CopyIcon as PhCopy,
  ArrowSquareOutIcon as PhArrowSquareOut,
  ArrowClockwiseIcon as PhArrowClockwise,
} from "@phosphor-icons/react";

interface BootStep {
  label: string;
  detail?: string;
  /** Duration this step stays active, in ms. Defaults to 900. */
  duration?: number;
}

interface Resources {
  cpuPct: number;
  memoryUsedMB: number;
  memoryTotalMB: number;
}

function BoxIcon() {
  return <PhPackage size={13} aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={11} weight="bold" aria-hidden />;
}

function CopyIcon() {
  return <PhCopy size={12} aria-hidden />;
}

function ExternalLinkIcon() {
  return <PhArrowSquareOut size={12} aria-hidden />;
}

function ReplayIcon() {
  return <PhArrowClockwise size={14} aria-hidden />;
}

function StepIndicator({ status, shouldReduceMotion }: { status: "pending" | "active" | "done"; shouldReduceMotion: boolean | null }) {
  if (status === "done") {
    return (
      <span className="relative flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white">
        <CheckIcon />
      </span>
    );
  }
  if (status === "active") {
    return (
      <span className="relative flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-emerald-500/15">
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full border-2 border-emerald-400/25 border-t-emerald-500"
          animate={shouldReduceMotion ? undefined : { rotate: 360 }}
          transition={{ duration: 0.8, repeat: Infinity, ease: "linear" }}
        />
      </span>
    );
  }
  return <span className="h-5 w-5 shrink-0 rounded-full border-2 border-slate-300 dark:border-white/15" />;
}

function GaugeBar({ label, pct, note, shouldReduceMotion }: { label: string; pct: number; note: string; shouldReduceMotion: boolean | null }) {
  return (
    <div>
      <div className="mb-1 flex items-center justify-between text-[11px] text-slate-500 dark:text-slate-400">
        <span>{label}</span>
        <span>{note}</span>
      </div>
      <div className="h-1.5 overflow-hidden rounded-full bg-slate-200 dark:bg-white/10">
        <motion.div
          className="h-full rounded-full bg-emerald-600 dark:bg-emerald-500"
          initial={{ width: 0 }}
          animate={shouldReduceMotion ? { width: `${pct}%` } : { width: [`${pct - 3}%`, `${pct + 3}%`, `${pct - 3}%`] }}
          transition={shouldReduceMotion ? { duration: 0.4 } : { duration: 3.2, repeat: Infinity, ease: "easeInOut" }}
        />
      </div>
    </div>
  );
}

export function Sandbox({
  steps,
  previewUrl,
  resources,
  autoPlay = true,
}: {
  steps: BootStep[];
  previewUrl: string;
  resources: Resources;
  autoPlay?: boolean;
}) {
  const [playId, setPlayId] = useState(0);
  return (
    <SandboxRun
      key={playId}
      steps={steps}
      previewUrl={previewUrl}
      resources={resources}
      autoPlay={autoPlay}
      onReplay={() => setPlayId((id) => id + 1)}
    />
  );
}

function SandboxRun({
  steps,
  previewUrl,
  resources,
  autoPlay,
  onReplay,
}: {
  steps: BootStep[];
  previewUrl: string;
  resources: Resources;
  autoPlay: boolean;
  onReplay: () => void;
}) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [ready, setReady] = useState(!autoPlay);
  const [copied, setCopied] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!autoPlay) return;
    let cumulative = 0;
    let cancelled = false;
    const timeouts: ReturnType<typeof setTimeout>[] = [];
    steps.forEach((step, i) => {
      const d = shouldReduceMotion ? 40 : (step.duration ?? 900);
      cumulative += d;
      timeouts.push(
        setTimeout(() => {
          if (cancelled) return;
          if (i === steps.length - 1) {
            setTimeout(() => !cancelled && setReady(true), 250);
          } else {
            setCurrentIndex(i + 1);
          }
        }, cumulative)
      );
    });
    return () => {
      cancelled = true;
      timeouts.forEach(clearTimeout);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPlay, shouldReduceMotion]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(`https://${previewUrl}`);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {
      // Clipboard API unavailable ; no-op
    }
  };

  const statusOf = (i: number): "pending" | "active" | "done" => (i < currentIndex || ready ? "done" : i === currentIndex ? "active" : "pending");

  return (
    <div className="w-full max-w-sm overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_25px_60px_-25px_rgba(0,0,0,0.15)] dark:border-white/10 dark:bg-neutral-950 dark:shadow-[0_25px_60px_-25px_rgba(0,0,0,0.6)]">
      <div className="flex items-center gap-2 border-b border-slate-200 bg-slate-50 px-4 py-2.5 dark:border-white/10 dark:bg-white/[0.02]">
        <span className="flex h-5 w-5 items-center justify-center rounded bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400">
          <BoxIcon />
        </span>
        <span className="text-xs font-medium text-slate-600 dark:text-slate-300">Sandbox</span>
        <AnimatePresence mode="wait">
          <motion.span
            key={ready ? "ready" : "booting"}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.2 }}
            className="ml-auto flex items-center gap-1.5 text-[11px] font-medium"
          >
            <span className="relative flex h-1.5 w-1.5">
              {ready && !shouldReduceMotion && (
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400 opacity-75" />
              )}
              <span className={`relative inline-flex h-1.5 w-1.5 rounded-full ${ready ? "bg-emerald-500 dark:bg-emerald-400" : "bg-amber-500 dark:bg-amber-400"}`} />
            </span>
            <span className={ready ? "text-emerald-600 dark:text-emerald-400" : "text-amber-600 dark:text-amber-400"}>{ready ? "Ready" : "Booting"}</span>
          </motion.span>
        </AnimatePresence>
        {ready && autoPlay && (
          <button
            type="button"
            onClick={onReplay}
            aria-label="Restart sandbox"
            className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-slate-200 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-200 dark:focus-visible:outline-emerald-500"
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <div className="px-4 py-4">
        <div className="flex flex-col gap-2.5">
          {steps.map((step, i) => {
            const status = statusOf(i);
            return (
              <div key={step.label} className="flex items-center gap-2.5">
                <StepIndicator status={status} shouldReduceMotion={shouldReduceMotion} />
                <div className="min-w-0 flex-1">
                  <p className={`truncate font-mono text-xs ${status === "pending" ? "text-slate-400 dark:text-slate-600" : "text-slate-800 dark:text-slate-200"}`}>{step.label}</p>
                  {step.detail && status !== "pending" && <p className="truncate font-mono text-[11px] text-slate-500 dark:text-slate-500">{step.detail}</p>}
                </div>
              </div>
            );
          })}
        </div>

        <AnimatePresence>
          {ready && (
            <motion.div
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              transition={shouldReduceMotion ? { duration: 0.2 } : { height: { duration: 0.3, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.25 } }}
              className="overflow-hidden"
            >
              <div className="mt-4 flex items-center gap-1.5 rounded-lg border border-slate-200 bg-slate-50 px-2.5 py-1.5 dark:border-white/10 dark:bg-white/[0.03]">
                <span className="truncate font-mono text-xs text-slate-700 dark:text-slate-300">{previewUrl}</span>
                <button
                  type="button"
                  onClick={handleCopy}
                  aria-label={copied ? "Preview URL copied" : "Copy preview URL"}
                  title={copied ? "Preview URL copied" : "Copy preview URL"}
                  className="ml-auto inline-flex h-6 w-6 shrink-0 items-center justify-center rounded text-slate-400 transition-colors hover:bg-slate-200 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-200 dark:focus-visible:outline-emerald-500"
                >
                  {copied ? <CheckIcon /> : <CopyIcon />}
                </button>
                <span className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded text-slate-400">
                  <ExternalLinkIcon />
                </span>
              </div>

              <div className="mt-4 flex flex-col gap-3">
                <GaugeBar label="CPU" pct={resources.cpuPct} note={`${resources.cpuPct}%`} shouldReduceMotion={shouldReduceMotion} />
                <GaugeBar
                  label="Memory"
                  pct={(resources.memoryUsedMB / resources.memoryTotalMB) * 100}
                  note={`${resources.memoryUsedMB} / ${resources.memoryTotalMB} MB`}
                  shouldReduceMotion={shouldReduceMotion}
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { CaretRightIcon as PhCaretRight, CheckIcon as PhCheck, XIcon as PhX, ArrowClockwiseIcon as PhArrowClockwise } from "@phosphor-icons/react";

type TestStatus = "pending" | "running" | "pass" | "fail";

interface TestCase {
  name: string;
  outcome: "pass" | "fail";
  message?: string;
  duration: number;
}

function ChevronIcon() {
  return <PhCaretRight size={12} weight="bold" aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={11} weight="bold" aria-hidden />;
}

function XIcon() {
  return <PhX size={11} weight="bold" aria-hidden />;
}

function ReplayIcon() {
  return <PhArrowClockwise size={14} aria-hidden />;
}

function formatElapsed(ms: number) {
  return `${(ms / 1000).toFixed(1)}s`;
}

function StatusIcon({ status, shouldReduceMotion }: { status: TestStatus; shouldReduceMotion: boolean | null }) {
  if (status === "pass") {
    return (
      <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white">
        <CheckIcon />
      </span>
    );
  }
  if (status === "fail") {
    return (
      <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-rose-600 text-white">
        <XIcon />
      </span>
    );
  }
  if (status === "running") {
    return (
      <motion.span
        aria-hidden
        className="h-4 w-4 shrink-0 rounded-full border-2 border-emerald-400/25 border-t-emerald-500"
        animate={shouldReduceMotion ? undefined : { rotate: 360 }}
        transition={{ duration: 0.7, repeat: Infinity, ease: "linear" }}
      />
    );
  }
  return <span className="h-4 w-4 shrink-0 rounded-full border-2 border-slate-200 dark:border-slate-700" />;
}

export function TestResults({
  suite,
  tests,
  autoPlay = true,
}: {
  suite: string;
  tests: TestCase[];
  autoPlay?: boolean;
}) {
  const [playId, setPlayId] = useState(0);
  return <TestResultsRun key={playId} suite={suite} tests={tests} autoPlay={autoPlay} onReplay={() => setPlayId((id) => id + 1)} />;
}

function TestResultsRun({
  suite,
  tests,
  autoPlay,
  onReplay,
}: {
  suite: string;
  tests: TestCase[];
  autoPlay: boolean;
  onReplay: () => void;
}) {
  const [statuses, setStatuses] = useState<TestStatus[]>(() => (autoPlay ? tests.map(() => "pending") : tests.map((t) => t.outcome)));
  const [finished, setFinished] = useState(!autoPlay);
  const [expanded, setExpanded] = useState<number | null>(null);
  const [elapsedMs, setElapsedMs] = useState(0);
  const startRef = useRef(0);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!autoPlay) return;
    startRef.current = performance.now();
    let cumulative = 0;
    let cancelled = false;
    const timeouts: ReturnType<typeof setTimeout>[] = [];

    tests.forEach((test, i) => {
      const d = shouldReduceMotion ? 30 : test.duration;
      const startAt = cumulative;
      const endAt = cumulative + d;
      timeouts.push(
        setTimeout(() => {
          if (cancelled) return;
          setStatuses((s) => s.map((v, idx) => (idx === i ? "running" : v)));
        }, startAt)
      );
      timeouts.push(
        setTimeout(() => {
          if (cancelled) return;
          setStatuses((s) => s.map((v, idx) => (idx === i ? test.outcome : v)));
        }, endAt)
      );
      cumulative = endAt;
    });
    timeouts.push(
      setTimeout(() => {
        if (!cancelled) setFinished(true);
      }, cumulative + 150)
    );

    return () => {
      cancelled = true;
      timeouts.forEach(clearTimeout);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPlay, shouldReduceMotion]);

  useEffect(() => {
    if (finished) return;
    let raf: number;
    const tick = () => {
      setElapsedMs(performance.now() - startRef.current);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [finished]);

  const passed = statuses.filter((s) => s === "pass").length;
  const failed = statuses.filter((s) => s === "fail").length;
  const total = tests.length;
  const passedPct = (passed / total) * 100;
  const failedPct = (failed / total) * 100;

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-4 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="mb-1 flex items-center gap-2">
        <p className="truncate font-mono text-xs font-medium text-slate-500 dark:text-slate-400">{suite}</p>
        <span className="ml-auto shrink-0 text-xs tabular-nums text-slate-400 dark:text-slate-500">
          {finished ? `Ran in ${formatElapsed(elapsedMs)}` : formatElapsed(elapsedMs)}
        </span>
        {finished && autoPlay && (
          <button
            type="button"
            onClick={onReplay}
            aria-label="Re-run tests"
            className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <div className="mb-3 flex items-center gap-2">
        <div className="flex h-1.5 flex-1 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10">
          <motion.span className="h-full bg-emerald-500" animate={{ width: `${passedPct}%` }} transition={{ duration: 0.25 }} />
          <motion.span className="h-full bg-rose-500" animate={{ width: `${failedPct}%` }} transition={{ duration: 0.25 }} />
        </div>
        <p className="shrink-0 text-xs text-slate-400 dark:text-slate-500">
          <span className="font-medium text-emerald-600 dark:text-emerald-400">{passed} passed</span>
          {failed > 0 && (
            <>
              {" · "}
              <span className="font-medium text-rose-600 dark:text-rose-400">{failed} failed</span>
            </>
          )}
        </p>
      </div>

      <ul className="flex flex-col" role="list">
        {tests.map((test, i) => {
          const status = statuses[i];
          const resolved = status === "pass" || status === "fail";
          const canExpand = status === "fail";
          const isExpanded = expanded === i;
          return (
            <li key={test.name} className="border-t border-slate-100 first:border-t-0 dark:border-white/5">
              <button
                type="button"
                disabled={!canExpand}
                onClick={() => setExpanded((e) => (e === i ? null : i))}
                className="flex w-full items-center gap-2.5 py-2 text-left disabled:cursor-default"
              >
                <StatusIcon status={status} shouldReduceMotion={shouldReduceMotion} />
                <span className={`min-w-0 flex-1 truncate text-sm ${resolved ? "text-slate-700 dark:text-slate-200" : "text-slate-400 dark:text-slate-600"}`}>
                  {test.name}
                </span>
                {canExpand && (
                  <motion.span
                    animate={{ rotate: isExpanded ? 90 : 0 }}
                    transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
                    className="shrink-0 text-slate-400"
                  >
                    <ChevronIcon />
                  </motion.span>
                )}
              </button>
              <AnimatePresence initial={false}>
                {canExpand && isExpanded && (
                  <motion.div
                    initial={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
                    animate={shouldReduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
                    exit={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
                    transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.4, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.28, ease: [0.22, 1, 0.36, 1] } }}
                    className="overflow-hidden"
                  >
                    <motion.p
                      initial={shouldReduceMotion ? undefined : { y: -8 }}
                      animate={{ y: 0 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.32, ease: [0.22, 1, 0.36, 1], delay: 0.06 }}
                      className="mb-2 ml-6 rounded-lg border border-rose-500/20 bg-rose-500/5 px-3 py-2 font-mono text-xs leading-relaxed text-rose-700 dark:text-rose-400"
                    >
                      {test.message}
                    </motion.p>
                  </motion.div>
                )}
              </AnimatePresence>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { motion, steps, useReducedMotion } from "framer-motion";
import { TerminalIcon as PhTerminal, ArrowClockwiseIcon as PhArrowClockwise } from "@phosphor-icons/react";

interface OutputLine {
  text: string;
  tone?: "success";
}

interface Command {
  cmd: string;
  output: OutputLine[];
}

const CHAR_MS = 18;
const LINE_MS = 260;
const POST_TYPE_PAUSE = 220;
const POST_OUTPUT_PAUSE = 180;

interface Snapshot {
  cmdIndex: number;
  typedLen: number;
  outputRevealed: number;
  phase: "typing" | "output";
}

interface ScheduleStep {
  delay: number;
  snapshot: Snapshot;
}

function buildSchedule(commands: Command[]): ScheduleStep[] {
  const steps: ScheduleStep[] = [];
  let t = 0;
  commands.forEach((c, ci) => {
    for (let i = 1; i <= c.cmd.length; i++) {
      t += CHAR_MS;
      steps.push({ delay: t, snapshot: { cmdIndex: ci, typedLen: i, outputRevealed: 0, phase: "typing" } });
    }
    t += POST_TYPE_PAUSE;
    c.output.forEach((_, oi) => {
      t += LINE_MS;
      steps.push({ delay: t, snapshot: { cmdIndex: ci, typedLen: c.cmd.length, outputRevealed: oi + 1, phase: "output" } });
    });
    t += POST_OUTPUT_PAUSE;
  });
  return steps;
}

function TerminalIcon() {
  return <PhTerminal size={13} aria-hidden />;
}

function ReplayIcon() {
  return <PhArrowClockwise size={14} aria-hidden />;
}

function Cursor({ shouldReduceMotion }: { shouldReduceMotion: boolean | null }) {
  return (
    <motion.span
      aria-hidden
      className="ml-0.5 inline-block h-3.5 w-[7px] translate-y-0.5 bg-emerald-600 dark:bg-emerald-500"
      animate={shouldReduceMotion ? undefined : { opacity: [1, 0, 1] }}
      transition={{ duration: 1, repeat: Infinity, ease: steps(2) }}
    />
  );
}

export function Terminal({ commands, autoPlay = true }: { commands: Command[]; autoPlay?: boolean }) {
  const [playId, setPlayId] = useState(0);
  return <TerminalRun key={playId} commands={commands} autoPlay={autoPlay} onReplay={() => setPlayId((id) => id + 1)} />;
}

function TerminalRun({
  commands,
  autoPlay,
  onReplay,
}: {
  commands: Command[];
  autoPlay: boolean;
  onReplay: () => void;
}) {
  const schedule = useMemo(() => buildSchedule(commands), [commands]);
  const [stepIndex, setStepIndex] = useState(autoPlay ? -1 : schedule.length - 1);
  const [finished, setFinished] = useState(!autoPlay);
  const scrollRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!autoPlay) return;
    let cancelled = false;

    if (shouldReduceMotion) {
      const t = setTimeout(() => {
        if (cancelled) return;
        setStepIndex(schedule.length - 1);
        setFinished(true);
      }, 0);
      return () => {
        cancelled = true;
        clearTimeout(t);
      };
    }

    const timeouts = schedule.map((s, i) =>
      setTimeout(() => {
        if (!cancelled) setStepIndex(i);
      }, s.delay)
    );
    const finishDelay = (schedule[schedule.length - 1]?.delay ?? 0) + 200;
    timeouts.push(
      setTimeout(() => {
        if (!cancelled) setFinished(true);
      }, finishDelay)
    );

    return () => {
      cancelled = true;
      timeouts.forEach(clearTimeout);
    };
  }, [schedule, autoPlay, shouldReduceMotion]);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    el.scrollTop = el.scrollHeight;
  }, [stepIndex]);

  const snapshot = stepIndex >= 0 ? schedule[stepIndex]?.snapshot ?? null : null;

  return (
    <div className="w-full max-w-lg overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_25px_60px_-25px_rgba(0,0,0,0.15)] dark:border-white/10 dark:bg-neutral-950 dark:shadow-[0_25px_60px_-25px_rgba(0,0,0,0.6)]">
      <div className="flex items-center gap-2 border-b border-slate-200 bg-slate-50 px-4 py-2.5 dark:border-white/10 dark:bg-white/[0.02]">
        <span className="flex h-5 w-5 items-center justify-center rounded bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400">
          <TerminalIcon />
        </span>
        <span className="text-xs font-medium text-slate-600 dark:text-slate-300">Terminal</span>
        {finished && autoPlay && (
          <button
            type="button"
            onClick={onReplay}
            aria-label="Replay commands"
            className="ml-auto inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-slate-200 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-200 dark:focus-visible:outline-emerald-500"
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <div ref={scrollRef} className="max-h-64 overflow-y-auto px-4 py-3 font-mono text-[13px] leading-relaxed scrollbar-hide">
        {commands.map((c, ci) => {
          if (!snapshot || ci > snapshot.cmdIndex) return null;
          const isCurrent = ci === snapshot.cmdIndex;
          const typedLen = isCurrent ? snapshot.typedLen : c.cmd.length;
          const showingOutput = !isCurrent || snapshot.phase === "output";
          const outputCount = isCurrent ? snapshot.outputRevealed : c.output.length;
          const stillTyping = isCurrent && snapshot.phase === "typing";
          return (
            <div key={ci} className="mb-2 last:mb-0">
              <p className="text-slate-800 dark:text-slate-200">
                <span className="text-emerald-600 dark:text-emerald-500">$</span> {c.cmd.slice(0, typedLen)}
                {stillTyping && <Cursor shouldReduceMotion={shouldReduceMotion} />}
              </p>
              {showingOutput &&
                c.output.slice(0, outputCount).map((line, li) => (
                  <p key={li} className={`pl-3 ${line.tone === "success" ? "text-emerald-600 dark:text-emerald-400" : "text-slate-500 dark:text-slate-400"}`}>
                    {line.text}
                  </p>
                ))}
            </div>
          );
        })}
        {finished && (
          <p className="text-slate-800 dark:text-slate-200">
            <span className="text-emerald-600 dark:text-emerald-500">$</span> <Cursor shouldReduceMotion={shouldReduceMotion} />
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

import {
  useEffect,
  useRef,
  useState,
  type ChangeEvent,
  type PointerEvent as ReactPointerEvent,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  PlayIcon as PhPlay,
  PauseIcon as PhPause,
  SparkleIcon as PhSparkle,
  SpeakerHighIcon as PhSpeakerHigh,
  SpeakerXIcon as PhSpeakerX,
  UploadSimpleIcon as PhUploadSimple,
  TrashIcon as PhTrash,
} from "@phosphor-icons/react";

const BAR_COUNT = 48;
const SPEEDS = [1, 1.5, 2, 0.5];

function PlayIcon() {
  return <PhPlay size={16} weight="fill" aria-hidden />;
}

function PauseIcon() {
  return <PhPause size={16} weight="fill" aria-hidden />;
}

function SpeakerIcon() {
  return <PhSparkle size={12} weight="fill" aria-hidden />;
}

function VolumeIcon({ muted }: { muted: boolean }) {
  return muted ? <PhSpeakerX size={14} aria-hidden /> : <PhSpeakerHigh size={14} aria-hidden />;
}

function UploadIcon() {
  return <PhUploadSimple size={13} aria-hidden />;
}

function TrashIcon() {
  return <PhTrash size={13} aria-hidden />;
}

function formatTime(s: number) {
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, "0")}`;
}

function BarRow({ heights, color, playing, reduceMotion }: { heights: number[]; color: string; playing: boolean; reduceMotion: boolean | null }) {
  return (
    // w-full is load-bearing: this div is itself a flex item inside the seek
    // track's flex row, so without an explicit width it shrink-wraps to its
    // bars' min-width instead of stretching to fill the track.
    <div className="flex h-full w-full items-center gap-0.5">
      {heights.map((h, i) => (
        <motion.span
          key={i}
          className={`min-w-[2px] flex-1 rounded-full ${color}`}
          style={{ height: `${(h * 100).toFixed(2)}%` }}
          animate={playing && !reduceMotion ? { scaleY: [1, 1.1 + h * 0.2, 1] } : { scaleY: 1 }}
          transition={
            playing && !reduceMotion
              ? { duration: 0.7 + (i % 6) * 0.08, repeat: Infinity, ease: "easeInOut", delay: (i % 12) * 0.05 }
              : { duration: 0.2 }
          }
        />
      ))}
    </div>
  );
}

function VolumeControl({ volume, muted, toggleMute, onVolumeChange }: { volume: number; muted: boolean; toggleMute: () => void; onVolumeChange: (v: number) => void }) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [dragging, setDragging] = useState(false);
  const effective = muted ? 0 : volume;

  const setFromClientX = (clientX: number) => {
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const frac = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    onVolumeChange(Math.round(frac * 100) / 100);
  };

  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    setDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
    setFromClientX(e.clientX);
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    setFromClientX(e.clientX);
  };
  const onPointerUp = () => setDragging(false);

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      onVolumeChange(Math.max(0, Math.round((effective - 0.1) * 100) / 100));
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      onVolumeChange(Math.min(1, Math.round((effective + 0.1) * 100) / 100));
    }
  };

  return (
    <div className="ml-auto flex items-center gap-1.5">
      <button
        type="button"
        onClick={toggleMute}
        aria-label={muted || volume === 0 ? "Unmute" : "Mute"}
        aria-pressed={muted}
        className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-500 dark:hover:text-slate-300"
      >
        <VolumeIcon muted={muted || volume === 0} />
      </button>
      <div
        ref={trackRef}
        role="slider"
        tabIndex={0}
        aria-label="Volume"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(effective * 100)}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onKeyDown={onKeyDown}
        className="group relative flex h-4 w-12 cursor-pointer items-center focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
      >
        <div className="relative h-1 w-full overflow-hidden rounded-full bg-slate-200 dark:bg-white/10">
          <div className="h-full rounded-full bg-emerald-500" style={{ width: `${effective * 100}%` }} />
        </div>
        <div
          aria-hidden
          className={`absolute top-1/2 h-2.5 w-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-emerald-600 ring-2 ring-white transition-opacity duration-150 dark:ring-neutral-950 ${
            dragging ? "opacity-100" : "opacity-0 group-hover:opacity-100"
          }`}
          style={{ left: `${effective * 100}%` }}
        />
      </div>
    </div>
  );
}

function EmptyState({ onUpload }: { onUpload: () => void }) {
  return (
    <button
      type="button"
      onClick={onUpload}
      className="flex w-full flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-slate-300 py-7 text-slate-400 transition-colors hover:border-emerald-400 hover:text-emerald-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/15 dark:text-slate-500 dark:hover:border-emerald-500/50 dark:hover:text-emerald-400"
    >
      <UploadIcon />
      <span className="text-xs font-medium">Upload an audio file</span>
    </button>
  );
}

// title/src: pass your own audio file as the initial track. durationSeconds is
// only the pre-load estimate shown before the file's real metadata arrives.
// The player also lets the visitor swap in their own file or clear it entirely
// (the upload/trash icons next to the volume control); src only seeds the
// initial state, it isn't a controlled prop after that.
export function AudioPlayer({ title, src, durationSeconds = 0 }: { title: string; src: string; durationSeconds?: number }) {
  const [currentSrc, setCurrentSrc] = useState<string | null>(src);
  const [playing, setPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(durationSeconds);
  const [speed, setSpeed] = useState(1);
  const [dragging, setDragging] = useState(false);
  const [volume, setVolume] = useState(0.8);
  const [muted, setMuted] = useState(false);
  const audioRef = useRef<HTMLAudioElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const fillRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  // Only the object URL created from a user-uploaded file needs revoking,
  // never the initial `src` prop, so it's tracked separately from currentSrc.
  const uploadedUrlRef = useRef<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const barHeights = useRef(
    Array.from({ length: BAR_COUNT }, (_, i) => {
      const base = Math.sin(i * 0.5) * 0.5 + 0.5;
      const detail = Math.sin(i * 1.7) * 0.3;
      const h = Math.max(0.18, Math.min(1, base * 0.7 + detail + 0.3));
      return Math.round(h * 10000) / 10000;
    })
  ).current;

  const applyProgress = (time: number, dur: number) => {
    const frac = dur > 0 ? Math.min(1, Math.max(0, time / dur)) : 0;
    if (fillRef.current) fillRef.current.style.clipPath = `inset(0 ${(1 - frac) * 100}% 0 0)`;
    if (trackRef.current) {
      trackRef.current.setAttribute("aria-valuenow", String(Math.round(time)));
      trackRef.current.setAttribute("aria-valuetext", `${formatTime(time)} of ${formatTime(dur)}`);
    }
  };

  useEffect(() => {
    const audio = audioRef.current;
    if (audio) audio.playbackRate = speed;
  }, [speed]);

  useEffect(() => {
    const audio = audioRef.current;
    if (audio) {
      audio.volume = volume;
      audio.muted = muted;
    }
  }, [volume, muted]);

  useEffect(() => {
    if (!playing || !currentSrc) return;
    let raf: number;
    let lastWhole = Math.floor(audioRef.current?.currentTime ?? 0);
    const tick = () => {
      const audio = audioRef.current;
      if (!audio) return;
      const dur = Number.isFinite(audio.duration) && audio.duration > 0 ? audio.duration : duration;
      applyProgress(audio.currentTime, dur);
      const whole = Math.floor(audio.currentTime);
      if (whole !== lastWhole) {
        lastWhole = whole;
        setCurrentTime(audio.currentTime);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [playing, duration, currentSrc]);

  const handleLoadedMetadata = () => {
    const audio = audioRef.current;
    if (audio && Number.isFinite(audio.duration) && audio.duration > 0) setDuration(audio.duration);
  };

  const handleEnded = () => {
    const audio = audioRef.current;
    const time = audio?.duration ?? duration;
    setPlaying(false);
    setCurrentTime(time);
    applyProgress(time, duration);
  };

  const handleSeek = (time: number) => {
    const clamped = Math.min(duration, Math.max(0, time));
    const audio = audioRef.current;
    if (audio) audio.currentTime = clamped;
    applyProgress(clamped, duration);
    setCurrentTime(clamped);
  };

  const seekFromClientX = (clientX: number) => {
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const frac = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    handleSeek(frac * duration);
  };

  const togglePlay = () => {
    const audio = audioRef.current;
    if (!audio) return;
    if (playing) {
      audio.pause();
      setPlaying(false);
      setCurrentTime(audio.currentTime);
      return;
    }
    if (audio.currentTime >= duration - 0.05) audio.currentTime = 0;
    audio.play().catch(() => {});
    setPlaying(true);
  };

  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    setDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
    seekFromClientX(e.clientX);
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    seekFromClientX(e.clientX);
  };
  const onPointerUp = () => setDragging(false);

  const toggleMute = () => setMuted((m) => !m);
  const handleVolumeChange = (v: number) => {
    setVolume(v);
    if (v > 0 && muted) setMuted(false);
  };

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    const at = audioRef.current?.currentTime ?? currentTime;
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      handleSeek(at - 5);
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      handleSeek(at + 5);
    } else if (e.key === "Home") {
      e.preventDefault();
      handleSeek(0);
    } else if (e.key === "End") {
      e.preventDefault();
      handleSeek(duration);
    } else if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      togglePlay();
    }
  };

  const resetPlayback = () => {
    setPlaying(false);
    setCurrentTime(0);
    setDuration(durationSeconds);
  };

  const openFilePicker = () => fileInputRef.current?.click();

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    if (uploadedUrlRef.current) URL.revokeObjectURL(uploadedUrlRef.current);
    // Local-only preview: this creates a blob URL that only exists in this
    // browser tab. A real app would typically upload `file` to its backend
    // here and use the returned hosted URL instead (or alongside this one),
    // and would still need to revoke the local object URL to avoid leaking it.
    const url = URL.createObjectURL(file);
    uploadedUrlRef.current = url;
    resetPlayback();
    setCurrentSrc(url);
  };

  const deleteAudio = () => {
    audioRef.current?.pause();
    if (uploadedUrlRef.current) {
      URL.revokeObjectURL(uploadedUrlRef.current);
      uploadedUrlRef.current = null;
    }
    resetPlayback();
    setCurrentSrc(null);
  };

  useEffect(() => {
    return () => {
      if (uploadedUrlRef.current) URL.revokeObjectURL(uploadedUrlRef.current);
    };
  }, []);

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-4 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <input ref={fileInputRef} type="file" accept="audio/*" onChange={handleFileChange} className="hidden" />
      {currentSrc && (
        <audio ref={audioRef} src={currentSrc} preload="metadata" onLoadedMetadata={handleLoadedMetadata} onEnded={handleEnded} className="hidden" />
      )}
      <div className="mb-3 flex items-center gap-2">
        <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-500 dark:text-emerald-400">
          <SpeakerIcon />
        </span>
        <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{title}</span>
        {currentSrc ? (
          <>
            <VolumeControl volume={volume} muted={muted} toggleMute={toggleMute} onVolumeChange={handleVolumeChange} />
            <button
              type="button"
              onClick={() => setSpeed((s) => SPEEDS[(SPEEDS.indexOf(s) + 1) % SPEEDS.length])}
              className="rounded-full border border-slate-200 px-2 py-0.5 text-[11px] font-medium text-slate-500 transition-colors hover:border-slate-300 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:text-slate-400 dark:hover:border-white/20 dark:hover:text-slate-200"
            >
              {speed}x
            </button>
            <button
              type="button"
              onClick={openFilePicker}
              aria-label="Change audio file"
              className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-500 dark:hover:text-slate-300"
            >
              <UploadIcon />
            </button>
            <button
              type="button"
              onClick={deleteAudio}
              aria-label="Delete audio file"
              className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:text-rose-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-500 dark:hover:text-rose-400"
            >
              <TrashIcon />
            </button>
          </>
        ) : (
          <button
            type="button"
            onClick={openFilePicker}
            className="ml-auto rounded-full border border-slate-200 px-2.5 py-1 text-[11px] font-medium text-slate-500 transition-colors hover:border-slate-300 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:text-slate-400 dark:hover:border-white/20 dark:hover:text-slate-200"
          >
            Upload
          </button>
        )}
      </div>

      {!currentSrc ? (
        <EmptyState onUpload={openFilePicker} />
      ) : (
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={togglePlay}
            aria-label={playing ? "Pause" : "Play"}
            className="relative inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white shadow-[0_4px_14px_-4px_rgba(5,150,105,0.6)] transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
          >
            <AnimatePresence mode="wait" initial={false}>
              <motion.span
                key={playing ? "pause" : "play"}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                transition={{ duration: 0.15 }}
                className="flex items-center justify-center"
              >
                {playing ? <PauseIcon /> : <PlayIcon />}
              </motion.span>
            </AnimatePresence>
          </button>

          <div className="min-w-0 flex-1">
            <div
              ref={trackRef}
              role="slider"
              tabIndex={0}
              aria-label="Seek"
              aria-valuemin={0}
              aria-valuemax={Math.round(duration)}
              aria-valuenow={Math.round(currentTime)}
              aria-valuetext={`${formatTime(currentTime)} of ${formatTime(duration)}`}
              onPointerDown={onPointerDown}
              onPointerMove={onPointerMove}
              onPointerUp={onPointerUp}
              onPointerCancel={onPointerUp}
              onKeyDown={onKeyDown}
              className="relative flex h-9 cursor-pointer items-center rounded-md focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
            >
              <BarRow heights={barHeights} color="bg-slate-200 dark:bg-slate-700" playing={playing} reduceMotion={shouldReduceMotion} />
              <div ref={fillRef} className="pointer-events-none absolute inset-0" style={{ clipPath: `inset(0 ${(1 - currentTime / duration) * 100}% 0 0)` }}>
                <BarRow heights={barHeights} color="bg-emerald-500" playing={playing} reduceMotion={shouldReduceMotion} />
              </div>
            </div>
            <div className="mt-1 flex items-center justify-between text-[11px] tabular-nums text-slate-400 dark:text-slate-500">
              <span>{formatTime(currentTime)}</span>
              <span>{formatTime(duration)}</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

