}

// title/src: pass your own audio file as the initial track. durationSeconds is
// only the pre-load estimate shown before the file's real metadata arrives.
// The scrubber also lets the visitor swap in their own file or clear it
// entirely (the upload/trash icons next to the volume control); src only
// seeds the initial state, it isn't a controlled prop after that.
export function AudioScrubber({ title, src, durationSeconds = 0 }: { title: string; src: string; durationSeconds?: number }) {
  const [currentSrc, setCurrentSrc] = useState<string | null>(src);
  const [playing, setPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(durationSeconds);
  const [speed, setSpeed] = useState(1);
  const [dragging, setDragging] = useState(false);
  const [volume, setVolume] = useState(0.8);
  const [muted, setMuted] = useState(false);
  const audioRef = useRef<HTMLAudioElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const fillRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  // Only the object URL created from a user-uploaded file needs revoking,
  // never the initial `src` prop, so it's tracked separately from currentSrc.
  const uploadedUrlRef = useRef<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const applyProgress = (time: number, dur: number) => {
    const pct = `${dur > 0 ? Math.min(1, Math.max(0, time / dur)) * 100 : 0}%`;
    if (fillRef.current) fillRef.current.style.width = pct;
    if (thumbRef.current) thumbRef.current.style.left = pct;
    if (trackRef.current) {
      trackRef.current.setAttribute("aria-valuenow", String(Math.round(time)));
      trackRef.current.setAttribute("aria-valuetext", `${formatTime(time)} of ${formatTime(dur)}`);
    }
  };

  useEffect(() => {
    const audio = audioRef.current;
    if (audio) audio.playbackRate = speed;
  }, [speed]);

  useEffect(() => {
    const audio = audioRef.current;
    if (audio) {
      audio.volume = volume;
      audio.muted = muted;
    }
  }, [volume, muted]);

  useEffect(() => {
    if (!playing || !currentSrc) return;
    let raf: number;
    let lastWhole = Math.floor(audioRef.current?.currentTime ?? 0);
    const tick = () => {
      const audio = audioRef.current;
      if (!audio) return;
      const dur = Number.isFinite(audio.duration) && audio.duration > 0 ? audio.duration : duration;
      applyProgress(audio.currentTime, dur);
      const whole = Math.floor(audio.currentTime);
      if (whole !== lastWhole) {
        lastWhole = whole;
        setCurrentTime(audio.currentTime);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [playing, duration, currentSrc]);

  const handleLoadedMetadata = () => {
    const audio = audioRef.current;
    if (audio && Number.isFinite(audio.duration) && audio.duration > 0) setDuration(audio.duration);
  };

  const handleEnded = () => {
    const audio = audioRef.current;
    const time = audio?.duration ?? duration;
    setPlaying(false);
    setCurrentTime(time);
    applyProgress(time, duration);
  };

  const handleSeek = (time: number) => {
    const clamped = Math.min(duration, Math.max(0, time));
    const audio = audioRef.current;
    if (audio) audio.currentTime = clamped;
    applyProgress(clamped, duration);
    setCurrentTime(clamped);
  };

  const seekFromClientX = (clientX: number) => {
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const frac = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    handleSeek(frac * duration);
  };

  const togglePlay = () => {
    const audio = audioRef.current;
    if (!audio) return;
    if (playing) {
      audio.pause();
      setPlaying(false);
      setCurrentTime(audio.currentTime);
      return;
    }
    if (audio.currentTime >= duration - 0.05) audio.currentTime = 0;
    audio.play().catch(() => {});
    setPlaying(true);
  };

  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    setDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
    seekFromClientX(e.clientX);
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    seekFromClientX(e.clientX);
  };
  const onPointerUp = () => setDragging(false);

  const toggleMute = () => setMuted((m) => !m);
  const handleVolumeChange = (v: number) => {
    setVolume(v);
    if (v > 0 && muted) setMuted(false);
  };

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    const at = audioRef.current?.currentTime ?? currentTime;
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      handleSeek(at - 5);
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      handleSeek(at + 5);
    } else if (e.key === "Home") {
      e.preventDefault();
      handleSeek(0);
    } else if (e.key === "End") {
      e.preventDefault();
      handleSeek(duration);
    } else if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      togglePlay();
    }
  };

  const resetPlayback = () => {
    setPlaying(false);
    setCurrentTime(0);
    setDuration(durationSeconds);
  };

  const openFilePicker = () => fileInputRef.current?.click();

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    if (uploadedUrlRef.current) URL.revokeObjectURL(uploadedUrlRef.current);
    // Local-only preview: this creates a blob URL that only exists in this
    // browser tab. A real app would typically upload `file` to its backend
    // here and use the returned hosted URL instead (or alongside this one),
    // and would still need to revoke the local object URL to avoid leaking it.
    const url = URL.createObjectURL(file);
    uploadedUrlRef.current = url;
    resetPlayback();
    setCurrentSrc(url);
  };

  const deleteAudio = () => {
    audioRef.current?.pause();
    if (uploadedUrlRef.current) {
      URL.revokeObjectURL(uploadedUrlRef.current);
      uploadedUrlRef.current = null;
    }
    resetPlayback();
    setCurrentSrc(null);
  };

  useEffect(() => {
    return () => {
      if (uploadedUrlRef.current) URL.revokeObjectURL(uploadedUrlRef.current);
    };
  }, []);

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-4 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <input ref={fileInputRef} type="file" accept="audio/*" onChange={handleFileChange} className="hidden" />
      {currentSrc && (
        <audio ref={audioRef} src={currentSrc} preload="metadata" onLoadedMetadata={handleLoadedMetadata} onEnded={handleEnded} className="hidden" />
      )}
      <div className="mb-3 flex items-center gap-2">
        <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-500 dark:text-emerald-400">
          <SpeakerIcon />
        </span>
        <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{title}</span>
        {currentSrc ? (
          <>
            <VolumeControl volume={volume} muted={muted} toggleMute={toggleMute} onVolumeChange={handleVolumeChange} />
            <button
              type="button"
              onClick={() => setSpeed((s) => SPEEDS[(SPEEDS.indexOf(s) + 1) % SPEEDS.length])}
              className="rounded-full border border-slate-200 px-2 py-0.5 text-[11px] font-medium text-slate-500 transition-colors hover:border-slate-300 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:text-slate-400 dark:hover:border-white/20 dark:hover:text-slate-200"
            >
              {speed}x
            </button>
            <button
              type="button"
              onClick={openFilePicker}
              aria-label="Change audio file"
              className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-500 dark:hover:text-slate-300"
            >
              <UploadIcon />
            </button>
            <button
              type="button"
              onClick={deleteAudio}
              aria-label="Delete audio file"
              className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:text-rose-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-500 dark:hover:text-rose-400"
            >
              <TrashIcon />
            </button>
          </>
        ) : (
          <button
            type="button"
            onClick={openFilePicker}
            className="ml-auto rounded-full border border-slate-200 px-2.5 py-1 text-[11px] font-medium text-slate-500 transition-colors hover:border-slate-300 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:text-slate-400 dark:hover:border-white/20 dark:hover:text-slate-200"
          >
            Upload
          </button>
        )}
      </div>

      {!currentSrc ? (
        <EmptyState onUpload={openFilePicker} />
      ) : (
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={togglePlay}
            aria-label={playing ? "Pause" : "Play"}
            className="relative inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white shadow-[0_4px_14px_-4px_rgba(5,150,105,0.6)] transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
          >
            <AnimatePresence mode="wait" initial={false}>
              <motion.span
                key={playing ? "pause" : "play"}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                transition={{ duration: 0.15 }}
                className="flex items-center justify-center"
              >
                {playing ? <PauseIcon /> : <PlayIcon />}
              </motion.span>
            </AnimatePresence>
          </button>

          <div className="min-w-0 flex-1">
            <div
              ref={trackRef}
              role="slider"
              tabIndex={0}
              aria-label="Seek"
              aria-valuemin={0}
              aria-valuemax={Math.round(duration)}
              aria-valuenow={Math.round(currentTime)}
              aria-valuetext={`${formatTime(currentTime)} of ${formatTime(duration)}`}
              onPointerDown={onPointerDown}
              onPointerMove={onPointerMove}
              onPointerUp={onPointerUp}
              onPointerCancel={onPointerUp}
              onKeyDown={onKeyDown}
              className="group relative flex h-5 w-full cursor-pointer items-center focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
            >
              <div
                className={`relative w-full overflow-hidden rounded-full bg-slate-200 transition-[height] duration-150 dark:bg-white/10 ${
                  dragging ? "h-1.5" : "h-1 group-hover:h-1.5"
                }`}
              >
                <div ref={fillRef} className="absolute inset-y-0 left-0 rounded-full bg-emerald-500" style={{ width: `${(currentTime / duration) * 100}%` }} />
              </div>
              <div
                ref={thumbRef}
                aria-hidden
                className={`absolute top-1/2 h-3 w-3 -translate-x-1/2 -translate-y-1/2 rounded-full bg-emerald-600 shadow-[0_1px_4px_rgba(0,0,0,0.35)] ring-2 ring-white transition-opacity duration-150 dark:ring-neutral-950 ${
                  dragging ? "opacity-100" : "opacity-0 group-hover:opacity-100"
                }`}
                style={{ left: `${(currentTime / duration) * 100}%` }}
              />
            </div>
            <div className="mt-1 flex items-center justify-between text-[11px] tabular-nums text-slate-400 dark:text-slate-500">
              <span>{formatTime(currentTime)}</span>
              <span>{formatTime(duration)}</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
