export function Persona({ personas, initialId }: { personas: PersonaDef[]; initialId?: string }) {
  const [activeId, setActiveId] = useState(initialId ?? personas[0].id);
  const [thinking, setThinking] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const active = personas.find((p) => p.id === activeId) ?? personas[0];

  useEffect(() => {
    if (!thinking) return;
    const t = setTimeout(() => setThinking(false), shouldReduceMotion ? 30 : 550);
    return () => clearTimeout(t);
  }, [thinking, shouldReduceMotion]);

  const switchPersona = (id: string) => {
    if (id === activeId) return;
    setActiveId(id);
    setThinking(true);
  };

  return (
    <div className="w-full max-w-sm rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <AnimatePresence mode="wait">
        <motion.div
          key={activeId}
          initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
          animate={{ opacity: 1, y: 0 }}
          exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
          transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
        >
          <div className="flex items-start gap-3">
            <AvatarOrb persona={active} size={44} thinking={thinking} shouldReduceMotion={shouldReduceMotion} />
            <div className="min-w-0 flex-1 pt-0.5">
              <div className="flex flex-wrap items-center gap-2">
                <h3 className="text-sm font-semibold text-slate-900 dark:text-white">{active.name}</h3>
                <StatusBadge thinking={thinking} />
              </div>
              <p className="text-xs text-slate-500 dark:text-slate-400">{active.role}</p>
            </div>
          </div>

          <p className="mt-3 text-sm leading-relaxed text-slate-600 dark:text-slate-300">{active.description}</p>

          <div className="mt-3 flex flex-wrap gap-1.5">
            {active.traits.map((t, i) => (
              <motion.span
                key={t}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.25, delay: 0.1 + i * 0.05, ease: [0.22, 1, 0.36, 1] }}
                className="rounded-full bg-black/[0.04] px-2.5 py-1 text-[11px] font-medium text-slate-600 dark:bg-white/[0.06] dark:text-slate-300"
              >
                {t}
              </motion.span>
            ))}
          </div>
        </motion.div>
      </AnimatePresence>

      {personas.length > 1 && (
        <div className="mt-4 flex items-center gap-2 border-t border-slate-100 pt-3 dark:border-white/5">
          <span className="text-[11px] font-medium text-slate-400 dark:text-slate-500">Switch persona</span>
          <div role="tablist" aria-label="Persona" className="ml-auto flex gap-1.5">
            {personas.map((p) => (
              <button
                key={p.id}
                type="button"
                role="tab"
                aria-selected={p.id === activeId}
                aria-label={p.name}
                title={p.name}
                onClick={() => switchPersona(p.id)}
                className={`rounded-full transition-all focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                  p.id === activeId ? "ring-2 ring-emerald-500/60 ring-offset-2 ring-offset-white dark:ring-offset-neutral-950" : "opacity-70 hover:opacity-100"
                }`}
              >
                <span className="block h-6 w-6 rounded-full" style={{ background: p.orb }} />
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  MicrophoneIcon as PhMicrophone,
  CheckIcon as PhCheck,
  StopIcon as PhStop,
  ArrowClockwiseIcon as PhArrowClockwise,
  CaretDownIcon as PhCaretDown,
} from "@phosphor-icons/react";

const WORD_MS = 70;
const FINALIZE_PAUSE = 350;
const CHUNK_GAP = 200;

interface ScheduleStep {
  delay: number;
  chunkIndex: number;
  wordCount: number;
  finalized: boolean;
}

function buildSchedule(chunks: string[]): ScheduleStep[] {
  const steps: ScheduleStep[] = [];
  let t = 0;
  chunks.forEach((chunk, ci) => {
    const words = chunk.split(" ");
    words.forEach((_, wi) => {
      t += WORD_MS;
      steps.push({ delay: t, chunkIndex: ci, wordCount: wi + 1, finalized: false });
    });
    t += FINALIZE_PAUSE;
    steps.push({ delay: t, chunkIndex: ci, wordCount: words.length, finalized: true });
    t += CHUNK_GAP;
  });
  return steps;
}

// The Web Speech API has no official TS lib entry, so this is the minimal
// shape this component actually reads/writes from SpeechRecognition.
interface SpeechRecognitionAlternativeLike {
  transcript: string;
}
interface SpeechRecognitionResultLike {
  readonly length: number;
  isFinal: boolean;
  [index: number]: SpeechRecognitionAlternativeLike;
}
interface SpeechRecognitionResultListLike {
  readonly length: number;
  [index: number]: SpeechRecognitionResultLike;
}
interface SpeechRecognitionEventLike extends Event {
  resultIndex: number;
  results: SpeechRecognitionResultListLike;
}
interface SpeechRecognitionErrorEventLike extends Event {
  error: string;
}
interface SpeechRecognitionLike extends EventTarget {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  start: () => void;
  stop: () => void;
  onresult: ((event: SpeechRecognitionEventLike) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEventLike) => void) | null;
  onend: (() => void) | null;
}
interface SpeechRecognitionConstructor {
  new (): SpeechRecognitionLike;
}

function getSpeechRecognitionCtor(): SpeechRecognitionConstructor | null {
  if (typeof window === "undefined") return null;
  const w = window as unknown as {
    SpeechRecognition?: SpeechRecognitionConstructor;
    webkitSpeechRecognition?: SpeechRecognitionConstructor;
  };
  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
}

function MicIcon() {
  return <PhMicrophone size={13} aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={13} weight="bold" aria-hidden />;
}

function StopIcon() {
  return <PhStop size={11} weight="fill" aria-hidden />;
}

function ReplayIcon() {
  return <PhArrowClockwise size={14} aria-hidden />;
}

function ChevronDownIcon() {
  return <PhCaretDown size={12} weight="bold" aria-hidden />;
}

const WAVEFORM_BARS = [
  { peak: 10, duration: 0.8, delay: 0 },
  { peak: 15, duration: 0.7, delay: 0.08 },
  { peak: 18, duration: 0.85, delay: 0.16 },
  { peak: 13, duration: 0.75, delay: 0.24 },
];

function formatElapsed(ms: number) {
  return `${(ms / 1000).toFixed(1)}s`;
}

type Phase = "demo" | "listening" | "done";

interface Language {
  id: string;
  label: string;
}

export function Transcription({
  chunks,
  languages,
  autoPlay = true,
}: {
  chunks: string[];
  languages: Language[];
  autoPlay?: boolean;
}) {
  const schedule = useMemo(() => buildSchedule(chunks), [chunks]);
  const [phase, setPhase] = useState<Phase>(autoPlay ? "demo" : "done");
  const [source, setSource] = useState<"script" | "live">("script");
  const [stepIndex, setStepIndex] = useState(autoPlay ? -1 : schedule.length - 1);
  const [finalText, setFinalText] = useState("");
  const [interimText, setInterimText] = useState("");
  const [elapsedMs, setElapsedMs] = useState(0);
  const [micError, setMicError] = useState<string | null>(null);
  const [languageId, setLanguageId] = useState(languages[0]?.id ?? "");
  const [languageOpen, setLanguageOpen] = useState(false);

  const startRef = useRef(0);
  const timeoutsRef = useRef<ReturnType<typeof setTimeout>[]>([]);
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const micErrorTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const languageRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const language = languages.find((l) => l.id === languageId) ?? languages[0];

  const clearTimeouts = () => {
    timeoutsRef.current.forEach(clearTimeout);
    timeoutsRef.current = [];
  };

  const playDemo = () => {
    clearTimeouts();
    setStepIndex(-1);
    startRef.current = performance.now();
    setElapsedMs(0);
    setSource("script");
    setPhase("demo");

    if (shouldReduceMotion) {
      timeoutsRef.current.push(
        setTimeout(() => {
          setStepIndex(schedule.length - 1);
          setPhase("done");
        }, 0)
      );
      return;
    }

    schedule.forEach((s, i) => {
      timeoutsRef.current.push(setTimeout(() => setStepIndex(i), s.delay));
    });
    const finishDelay = (schedule[schedule.length - 1]?.delay ?? 0) + 250;
    timeoutsRef.current.push(setTimeout(() => setPhase("done"), finishDelay));
  };

  useEffect(() => {
    if (!autoPlay) return;
    playDemo();
    return () => clearTimeouts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (phase === "done") return;
    let raf: number;
    const tick = () => {
      setElapsedMs(performance.now() - startRef.current);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [phase]);

  useEffect(() => {
    return () => {
      clearTimeouts();
      if (micErrorTimeoutRef.current) clearTimeout(micErrorTimeoutRef.current);
      const recognition = recognitionRef.current;
      if (recognition) {
        recognition.onresult = null;
        recognition.onerror = null;
        recognition.onend = null;
        recognition.stop();
        recognitionRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (!languageOpen) return;
    const onClick = (e: MouseEvent) => {
      if (languageRef.current && !languageRef.current.contains(e.target as Node)) setLanguageOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setLanguageOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onClick);
      document.removeEventListener("keydown", onKey);
    };
  }, [languageOpen]);

  const showMicError = (message: string) => {
    setMicError(message);
    if (micErrorTimeoutRef.current) clearTimeout(micErrorTimeoutRef.current);
    micErrorTimeoutRef.current = setTimeout(() => setMicError(null), 3200);
  };

  const startRecording = () => {
    const Ctor = getSpeechRecognitionCtor();
    if (!Ctor) {
      showMicError("This browser doesn't support live transcription. Try Chrome, Edge, or Safari.");
      return;
    }

    setMicError(null);
    setLanguageOpen(false);
    clearTimeouts();

    const recognition = new Ctor();
    recognition.lang = language?.id ?? "en-US";
    recognition.continuous = true;
    recognition.interimResults = true;

    // Accumulated outside React state so results aren't lost to stale
    // closures across the many onresult events a single session fires.
    let finalSoFar = "";

    recognition.onresult = (event) => {
      let interim = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const result = event.results[i];
        const transcript = result[0]?.transcript ?? "";
        if (result.isFinal) {
          finalSoFar += `${transcript} `;
        } else {
          interim += transcript;
        }
      }
      setFinalText(finalSoFar);
      setInterimText(interim);
    };

    recognition.onerror = (event) => {
      if (event.error === "not-allowed" || event.error === "service-not-allowed") {
        showMicError("Microphone access was denied.");
      } else if (event.error === "audio-capture") {
        showMicError("Couldn't access the microphone.");
      } else if (event.error !== "no-speech" && event.error !== "aborted") {
        showMicError("Transcription stopped unexpectedly.");
      }
    };

    recognition.onend = () => {
      recognitionRef.current = null;
      setSource("live");
      setPhase("done");
    };

    recognitionRef.current = recognition;
    setFinalText("");
    setInterimText("");
    startRef.current = performance.now();
    setElapsedMs(0);
    setPhase("listening");

    try {
      recognition.start();
    } catch {
      recognitionRef.current = null;
      showMicError("Couldn't start the microphone.");
      setPhase("done");
    }
  };

  const stopRecording = () => {
    recognitionRef.current?.stop();
  };

  const toggleRecording = () => {
    if (phase === "listening") {
      stopRecording();
      return;
    }
    startRecording();
  };

  const listening = phase === "listening";
  const finished = phase === "done";
  const snapshot = stepIndex >= 0 ? schedule[stepIndex] : null;
  const statusLabel = finished ? "Transcribed" : "Listening";
  const liveTranscript = `${finalText}${interimText}`.trim();

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-4 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="mb-3 flex items-center justify-between gap-2">
        <button
          type="button"
          onClick={toggleRecording}
          aria-pressed={listening}
          aria-label={listening ? "Stop recording" : "Record audio to transcribe"}
          className={`relative inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-xs font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
            listening
              ? "border-amber-700/30 bg-amber-700 text-white"
              : "border-slate-900/10 bg-black/[0.02] text-slate-600 hover:border-slate-900/20 hover:bg-black/5 hover:text-slate-800 dark:border-white/10 dark:bg-white/5 dark:text-slate-300 dark:hover:border-white/20 dark:hover:bg-white/10 dark:hover:text-white"
          }`}
        >
          {listening && (
            <motion.span
              aria-hidden
              className="absolute inset-[-3px] rounded-full border border-amber-400/60"
              animate={shouldReduceMotion ? undefined : { scale: [1, 1.3], opacity: [0.6, 0] }}
              transition={{ duration: 1.1, repeat: Infinity, ease: "easeOut" }}
            />
          )}
          {listening ? <StopIcon /> : <MicIcon />}
          {listening ? "Stop" : "Record"}
        </button>

        <div ref={languageRef} className="relative">
          <button
            type="button"
            onClick={() => setLanguageOpen((v) => !v)}
            disabled={listening}
            aria-haspopup="listbox"
            aria-expanded={languageOpen}
            className="inline-flex items-center gap-1.5 rounded-full border border-slate-900/10 bg-black/[0.02] px-2.5 py-1 text-xs font-medium text-slate-600 transition-colors hover:border-slate-900/20 hover:bg-black/5 hover:text-slate-800 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 disabled:pointer-events-none disabled:opacity-50 dark:border-white/10 dark:bg-white/5 dark:text-slate-300 dark:hover:border-white/20 dark:hover:bg-white/10 dark:hover:text-white"
          >
            {language?.label}
            <motion.span animate={{ rotate: languageOpen ? 180 : 0 }} transition={{ duration: 0.15 }} className="text-slate-400">
              <ChevronDownIcon />
            </motion.span>
          </button>
          <AnimatePresence>
            {languageOpen && (
              <motion.div
                role="listbox"
                aria-label="Transcription language"
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.95, y: -4 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96, y: -4 }}
                transition={{ duration: 0.15, ease: [0.16, 1, 0.3, 1] }}
                style={{ transformOrigin: "top right" }}
                className="scrollbar-thin absolute right-0 top-full z-20 mt-2 max-h-32 w-40 overflow-y-auto rounded-xl border border-slate-200/70 bg-white/95 p-1 shadow-lg backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/90"
              >
                {languages.map((l) => (
                  <button
                    key={l.id}
                    type="button"
                    role="option"
                    aria-selected={l.id === languageId}
                    onClick={() => {
                      setLanguageId(l.id);
                      setLanguageOpen(false);
                    }}
                    className="flex w-full items-center justify-between gap-2 rounded-lg px-2.5 py-1.5 text-left text-sm text-slate-700 transition-colors hover:bg-slate-50 dark:text-slate-200 dark:hover:bg-slate-800/60"
                  >
                    {l.label}
                    {l.id === languageId && (
                      <span className="text-emerald-500 dark:text-emerald-400">
                        <CheckIcon />
                      </span>
                    )}
                  </button>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      <AnimatePresence>
        {micError && (
          <motion.p
            role="alert"
            initial={{ opacity: 0, y: -4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -4 }}
            transition={{ duration: 0.15 }}
            className="mb-2 text-xs font-medium text-rose-600 dark:text-rose-400"
          >
            {micError}
          </motion.p>
        )}
      </AnimatePresence>

      <div className="mb-3 flex items-center gap-2">
        <span className="relative flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-500 dark:text-emerald-400">
          {!finished && !shouldReduceMotion && (
            <motion.span
              aria-hidden
              className="absolute inset-0 rounded-full border border-emerald-400/40"
              animate={{ scale: [1, 1.5], opacity: [0.6, 0] }}
              transition={{ duration: 1.4, repeat: Infinity, ease: "easeOut" }}
            />
          )}
          {finished ? <CheckIcon /> : <MicIcon />}
        </span>
        <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{statusLabel}</span>
        {listening && (
          <span className="flex h-3 items-end gap-0.5">
            {WAVEFORM_BARS.map((bar, i) => (
              <motion.span
                key={i}
                className="w-0.5 rounded-full bg-amber-500 dark:bg-amber-400"
                style={{ height: 3 }}
                animate={shouldReduceMotion ? undefined : { height: [3, bar.peak, 3] }}
                transition={{ duration: bar.duration, repeat: Infinity, ease: "easeInOut", delay: bar.delay }}
              />
            ))}
          </span>
        )}
        <span className="ml-auto shrink-0 text-xs tabular-nums text-slate-400 dark:text-slate-500">{formatElapsed(elapsedMs)}</span>
        {finished && source === "script" && autoPlay && (
          <button
            type="button"
            onClick={playDemo}
            aria-label="Replay transcription"
            className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <p className="min-h-[1.25rem] text-sm leading-relaxed">
        {phase === "listening" ? (
          <>
            <span className="text-slate-800 dark:text-slate-100">{finalText}</span>
            <span className="italic text-slate-500 dark:text-slate-400">{interimText}</span>
            {!finalText && !interimText && (
              <span className="italic text-slate-400 dark:text-slate-500">Listening for speech…</span>
            )}
          </>
        ) : source === "live" ? (
          liveTranscript ? (
            <span className="text-slate-800 dark:text-slate-100">{liveTranscript}</span>
          ) : (
            !micError && (
              <span className="italic text-slate-400 dark:text-slate-500">No speech detected. Press Record and try again.</span>
            )
          )
        ) : (
          chunks.map((chunk, ci) => {
            if (!snapshot || ci > snapshot.chunkIndex) return null;
            const isCurrent = ci === snapshot.chunkIndex;
            const isFinal = !isCurrent || snapshot.finalized;
            const words = chunk.split(" ");
            const visible = isCurrent ? words.slice(0, snapshot.wordCount).join(" ") : chunk;
            return (
              <motion.span
                key={ci}
                animate={{ opacity: isFinal ? 1 : 0.55 }}
                transition={{ duration: 0.25 }}
                className={`${isFinal ? "text-slate-800 dark:text-slate-100" : "italic text-slate-500 dark:text-slate-400"} `}
              >
                {visible + " "}
              </motion.span>
            );
          })
        )}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { CheckIcon as PhCheck, PlayIcon as PhPlay, StopIcon as PhStop } from "@phosphor-icons/react";

interface Voice {
  id: string;
  name: string;
  accent: string;
}

const PREVIEW_MS = 1800;

function CheckIcon() {
  return <PhCheck size={11} weight="bold" aria-hidden />;
}

function PlayIcon() {
  return <PhPlay size={12} weight="fill" aria-hidden />;
}

function StopIcon() {
  return <PhStop size={10} weight="fill" aria-hidden />;
}

function PreviewButton({
  playing,
  onClick,
  label,
  shouldReduceMotion,
}: {
  playing: boolean;
  onClick: () => void;
  label: string;
  shouldReduceMotion: boolean | null;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={playing ? `Stop preview of ${label}` : `Preview ${label}`}
      title={playing ? "Stop preview" : "Preview voice"}
      className={`relative inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
        playing
          ? "bg-emerald-600 text-white"
          : "bg-black/5 text-slate-500 hover:bg-black/10 hover:text-slate-700 dark:bg-white/10 dark:text-slate-400 dark:hover:bg-white/15 dark:hover:text-slate-200"
      }`}
    >
      {playing && (
        <motion.span
          aria-hidden
          className="absolute inset-[-3px] rounded-full border border-emerald-400/50"
          animate={shouldReduceMotion ? undefined : { scale: [1, 1.3], opacity: [0.6, 0] }}
          transition={{ duration: 1, repeat: Infinity, ease: "easeOut" }}
        />
      )}
      {playing ? <StopIcon /> : <PlayIcon />}
    </button>
  );
}

export function VoiceSelector({
  voices,
  defaultSelectedId,
  onSelect,
}: {
  voices: Voice[];
  defaultSelectedId?: string;
  onSelect?: (id: string) => void;
}) {
  const [selectedId, setSelectedId] = useState(defaultSelectedId ?? voices[0].id);
  const [previewingId, setPreviewingId] = useState<string | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const togglePreview = (id: string) => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (previewingId === id) {
      setPreviewingId(null);
      return;
    }
    setPreviewingId(id);
    timeoutRef.current = setTimeout(() => setPreviewingId(null), PREVIEW_MS);
  };

  const select = (id: string) => {
    setSelectedId(id);
    onSelect?.(id);
  };

  const selected = voices.find((v) => v.id === selectedId) ?? voices[0];

  return (
    <div className="w-full max-w-sm rounded-2xl border border-slate-200/70 bg-white/95 p-2 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="flex items-center justify-between px-2 pb-1.5 pt-1">
        <p className="text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Voice</p>
        <p className="text-xs font-medium text-emerald-600 dark:text-emerald-400">{selected.name}</p>
      </div>
      <ul role="radiogroup" aria-label="Select a voice" className="flex flex-col gap-0.5">
        {voices.map((v) => {
          const isSelected = v.id === selectedId;
          const isPlaying = previewingId === v.id;
          return (
            <li key={v.id}>
              <div
                className={`flex items-center gap-2 rounded-lg px-2 py-1.5 transition-colors ${
                  isSelected ? "bg-emerald-500/8 dark:bg-emerald-400/10" : "hover:bg-black/[0.03] dark:hover:bg-white/5"
                }`}
              >
                <button
                  type="button"
                  role="radio"
                  aria-checked={isSelected}
                  onClick={() => select(v.id)}
                  className="flex flex-1 items-center gap-2.5 rounded-md py-0.5 text-left focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                >
                  <span
                    className={`flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2 transition-colors ${
                      isSelected ? "border-emerald-600 bg-emerald-600 text-white" : "border-slate-300 dark:border-slate-600"
                    }`}
                  >
                    {isSelected && <CheckIcon />}
                  </span>
                  <span className="min-w-0">
                    <span className="block text-sm font-medium text-slate-800 dark:text-slate-100">{v.name}</span>
                    <span className="block text-xs text-slate-400 dark:text-slate-500">{v.accent}</span>
                  </span>
                </button>
                <PreviewButton playing={isPlaying} onClick={() => togglePreview(v.id)} label={v.name} shouldReduceMotion={shouldReduceMotion} />
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  ImageIcon as PhImage,
  FileIcon as PhFile,
  CheckIcon as PhCheck,
  XIcon as PhX,
  ArrowClockwiseIcon as PhArrowClockwise,
  PlusIcon as PhPlus,
} from "@phosphor-icons/react";

type Status = "uploading" | "done" | "error";

interface Attachment {
  id: string;
  name: string;
  size: number;
  status: Status;
  progress: number;
  speed: number;
  failAt?: number;
}

let nextId = 1;

const RADIUS = 9;
const CIRC = 2 * Math.PI * RADIUS;

function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb.toFixed(kb < 10 ? 1 : 0)} KB`;
  const mb = kb / 1024;
  return `${mb.toFixed(mb < 10 ? 1 : 0)} MB`;
}

function isImage(name: string) {
  return /\.(png|jpe?g|gif|webp|svg)$/i.test(name);
}

function ImageIcon() {
  return <PhImage size={14} aria-hidden />;
}

function DocumentIcon() {
  return <PhFile size={14} aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={10} weight="bold" aria-hidden />;
}

function XIcon() {
  return <PhX size={13} aria-hidden />;
}

// A bare exclamation mark, deliberately with no outer triangle/circle of its own
// since it's always shown inside this file's own colored circular status badge.
function AlertIcon() {
  return (
    <svg viewBox="0 0 24 24" width="9" height="9" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M12 8v4" />
      <path d="M12 16h.01" />
    </svg>
  );
}

function RetryIcon() {
  return <PhArrowClockwise size={13} aria-hidden />;
}

function PlusIcon() {
  return <PhPlus size={14} aria-hidden />;
}

function FileTone({ name }: { name: string }) {
  const image = isImage(name);
  return (
    <span
      className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${
        image ? "bg-emerald-500/12 text-emerald-600 dark:text-emerald-400" : "bg-amber-500/12 text-amber-600 dark:text-amber-400"
      }`}
    >
      {image ? <ImageIcon /> : <DocumentIcon />}
    </span>
  );
}

function ProgressRing({ progress, status }: { progress: number; status: Status }) {
  const offset = CIRC * (1 - progress / 100);
  const color = status === "error" ? "#e11d48" : "#059669";
  return (
    <svg viewBox="0 0 24 24" width="32" height="32" className="absolute inset-0 -rotate-90" aria-hidden>
      <circle cx="12" cy="12" r={RADIUS} fill="none" stroke="currentColor" strokeWidth="2" className="text-black/5 dark:text-white/10" />
      <motion.circle
        cx="12"
        cy="12"
        r={RADIUS}
        fill="none"
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
        strokeDasharray={CIRC}
        animate={{ strokeDashoffset: offset }}
        transition={{ duration: 0.15, ease: "linear" }}
      />
    </svg>
  );
}

export function Attachments({ initialFiles = [] }: { initialFiles?: { name: string; size: number }[] }) {
  const [attachments, setAttachments] = useState<Attachment[]>(() =>
    initialFiles.map((f) => ({ id: `i${nextId++}`, name: f.name, size: f.size, status: "uploading", progress: 0, speed: 3.5 }))
  );
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const id = setInterval(() => {
      setAttachments((prev) =>
        prev.map((a) => {
          if (a.status !== "uploading") return a;
          const next = a.progress + a.speed;
          if (a.failAt !== undefined && next >= a.failAt) {
            return { ...a, progress: a.failAt, status: "error" };
          }
          if (next >= 100) {
            return { ...a, progress: 100, status: "done" };
          }
          return { ...a, progress: next };
        })
      );
    }, 80);
    return () => clearInterval(id);
  }, []);

  const remove = (id: string) => setAttachments((prev) => prev.filter((a) => a.id !== id));

  const retry = (id: string) =>
    setAttachments((prev) => prev.map((a) => (a.id === id ? { ...a, status: "uploading", progress: 0, failAt: undefined } : a)));

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const added: Attachment[] = Array.from(files).map((f) => ({
      id: `f${nextId++}`,
      name: f.name,
      size: f.size,
      status: "uploading",
      progress: 0,
      speed: 3.5,
    }));
    setAttachments((prev) => [...prev, ...added]);
  };

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-3 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <p className="px-1 pb-2 text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">
        Attachments · {attachments.length}
      </p>
      <ul className="flex flex-col gap-1.5" role="list">
        <AnimatePresence initial={false}>
          {attachments.map((a) => (
            <motion.li
              key={a.id}
              layout
              initial={{ opacity: 0, scale: 0.96 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.94 }}
              transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              className="flex items-center gap-3 rounded-xl border border-transparent bg-black/[0.02] px-2.5 py-2 dark:bg-white/[0.03]"
            >
              <div className="relative h-8 w-8 shrink-0">
                <FileTone name={a.name} />
                {a.status === "uploading" && <ProgressRing progress={a.progress} status={a.status} />}
                {a.status === "done" && (
                  <span className="absolute -bottom-0.5 -right-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-emerald-600 text-white ring-2 ring-white dark:ring-neutral-950">
                    <CheckIcon />
                  </span>
                )}
                {a.status === "error" && (
                  <span className="absolute -bottom-0.5 -right-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-rose-600 text-white ring-2 ring-white dark:ring-neutral-950">
                    <AlertIcon />
                  </span>
                )}
              </div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-slate-800 dark:text-slate-100">{a.name}</p>
                <p className={`text-xs ${a.status === "error" ? "text-rose-600 dark:text-rose-400" : "text-slate-400 dark:text-slate-500"}`}>
                  {a.status === "uploading" ? `${Math.round(a.progress)}% · ${formatBytes(a.size)}` : a.status === "error" ? "Upload failed" : formatBytes(a.size)}
                </p>
              </div>
              <div className="flex shrink-0 items-center gap-1">
                {a.status === "error" && (
                  <button
                    type="button"
                    onClick={() => retry(a.id)}
                    aria-label={`Retry uploading ${a.name}`}
                    className="inline-flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
                  >
                    <RetryIcon />
                  </button>
                )}
                <button
                  type="button"
                  onClick={() => remove(a.id)}
                  aria-label={`Remove ${a.name}`}
                  className="inline-flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
                >
                  <XIcon />
                </button>
              </div>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>

      <input
        ref={inputRef}
        type="file"
        multiple
        className="sr-only"
        onChange={(e) => {
          handleFiles(e.target.files);
          e.target.value = "";
        }}
      />
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        className="mt-1.5 flex w-full items-center justify-center gap-1.5 rounded-xl border border-dashed border-slate-300 py-2 text-xs font-medium text-slate-500 transition-colors hover:border-emerald-400 hover:text-emerald-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:text-slate-400 dark:hover:border-emerald-500/60 dark:hover:text-emerald-400"
      >
        <PlusIcon />
        Add file
      </button>
    </div>
  );
}

