function FieldSelect({
  label,
  options,
  value,
  onChange,
}: {
  label: string;
  options: SelectOption[];
  value: string;
  onChange: (value: string) => void;
}) {
  const styles = useAccent();
  const [open, setOpen] = useState(false);
  const selectedIndex = Math.max(0, options.findIndex((o) => o.value === value));
  const [highlighted, setHighlighted] = useState(selectedIndex);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const reactId = useId();
  const listboxId = `settings-select-${reactId}`;
  const selected = options.find((o) => o.value === value) ?? options[0];

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      e.stopPropagation();
      if (!open) return setOpen(true);
      setHighlighted((h) => Math.min(h + 1, options.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      e.stopPropagation();
      setHighlighted((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      e.stopPropagation();
      if (open) {
        onChange(options[highlighted].value);
        setOpen(false);
      } else {
        setOpen(true);
      }
    } else if (e.key === "Escape") {
      e.stopPropagation();
      setOpen(false);
    }
  };

  return (
    <div ref={rootRef} className="relative">
      <button
        type="button"
        role="combobox"
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-controls={listboxId}
        aria-label={label}
        onClick={() => {
          setOpen((v) => !v);
          setHighlighted(selectedIndex);
        }}
        onKeyDown={handleKeyDown}
        className={`flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-sm text-slate-700 outline-none transition-colors hover:border-slate-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 dark:border-slate-700 dark:bg-neutral-900 dark:text-slate-200 dark:hover:border-slate-600 ${styles.ring}`}
      >
        {selected.dot && <span className={`h-2 w-2 shrink-0 rounded-full ${selected.dot}`} aria-hidden />}
        {selected.label}
        <ChevronDownIcon open={open} />
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { height: { duration: 0.2, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.15 } }
            }
            className="absolute right-0 z-20 mt-1.5 w-40 overflow-hidden rounded-lg border border-slate-200 bg-white shadow-lg dark:border-slate-700 dark:bg-neutral-900"
          >
            <ul id={listboxId} role="listbox" aria-label={label} data-lenis-prevent className="scrollbar-hide max-h-44 overflow-y-auto p-1">
              {options.map((option, i) => (
                <li
                  key={option.value}
                  role="option"
                  aria-selected={value === option.value}
                  onMouseEnter={() => setHighlighted(i)}
                  onClick={() => {
                    onChange(option.value);
                    setOpen(false);
                  }}
                  className="relative flex cursor-pointer items-center gap-2 rounded-md px-2.5 py-1.5 text-sm text-slate-700 dark:text-slate-300"
                >
                  {highlighted === i && (
                    <motion.span
                      layoutId={`${listboxId}-highlight`}
                      className={`absolute inset-0 rounded-md ${styles.optionHighlightBg}`}
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 600, damping: 40 }}
                    />
                  )}
                  <span className={`relative flex flex-1 items-center gap-2 ${highlighted === i ? styles.optionHighlightText : ""}`}>
                    {option.dot && <span className={`h-2 w-2 shrink-0 rounded-full ${option.dot}`} aria-hidden />}
                    {option.label}
                  </span>
                  {value === option.value && (
                    <span className={`relative shrink-0 ${styles.check}`}>
                      <CheckIcon />
                    </span>
                  )}
                </li>
              ))}
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function MiniToggle({ checked, onChange, label }: { checked: boolean; onChange: (v: boolean) => void; label: string }) {
  const styles = useAccent();
  const shouldReduceMotion = useReducedMotion();
  return (
    <motion.button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
      whileTap={{ scale: 0.93 }}
      className={`relative h-6 w-11 shrink-0 rounded-full transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ${styles.ring} ${
        checked ? styles.switchOn : "bg-slate-300 dark:bg-slate-600"
      }`}
    >
      <motion.span
        animate={{ x: checked ? 22 : 2 }}
        transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 700, damping: 32 }}
        className="absolute top-0.5 block h-5 w-5 rounded-full bg-white shadow-md"
      />
    </motion.button>
  );
}

function SaveIndicator({ state }: { state: "idle" | "saving" | "saved" }) {
  const styles = useAccent();
  const shouldReduceMotion = useReducedMotion();
  return (
    <AnimatePresence mode="wait">
      {state !== "idle" && (
        <motion.span
          key={state}
          initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: -2 }}
          animate={{ opacity: 1, y: 0 }}
          exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 2 }}
          transition={{ duration: 0.15 }}
          className="inline-flex shrink-0 items-center gap-1.5 text-xs font-medium text-slate-400 dark:text-slate-500"
        >
          {state === "saving" ? (
            <>
              <motion.span
                className="h-1.5 w-1.5 rounded-full bg-slate-400 dark:bg-slate-500"
                animate={shouldReduceMotion ? undefined : { opacity: [0.3, 1, 0.3] }}
                transition={{ repeat: Infinity, duration: 1 }}
              />
              Saving…
            </>
          ) : (
            <>
              <span className={styles.check}>
                <CheckIcon />
              </span>
              Saved
            </>
          )}
        </motion.span>
      )}
    </AnimatePresence>
  );
}

