interface SettingsPanelProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Renders scoped to the nearest positioned ancestor instead of the viewport, for demoing inside a bounded card. */
  contained?: boolean;
}

export function SettingsPanel({ open, onOpenChange, contained = false }: SettingsPanelProps) {
  const [active, setActive] = useState<SectionId>("general");
  const [settings, setSettings] = useState<SettingsState>(DEFAULT_SETTINGS);
  const [saveState, setSaveState] = useState<"idle" | "saving" | "saved">("idle");
  const [query, setQuery] = useState("");
  const shouldReduceMotion = useReducedMotion();
  const activeItem = NAV_GROUPS.flatMap((g) => g.items).find((item) => item.id === active);
  const styles = ACCENT_STYLES[settings.accent];
  const saveTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  // Every setting lives here, not in each pane, so switching tabs or closing
  // and reopening the dialog doesn't reset anything: this is what the
  // autosave indicator below would otherwise be lying about. The "saving"
  // flip happens inside this handler (a real user-driven event) rather than
  // an effect watching `settings`, since setState synchronously inside an
  // effect body triggers cascading renders.
  const update: UpdateSetting = (key, value) => {
    setSettings((prev) => ({ ...prev, [key]: value }));
    setSaveState("saving");
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => setSaveState("saved"), 500);
  };

  useEffect(() => {
    return () => {
      if (saveTimer.current) clearTimeout(saveTimer.current);
    };
  }, []);

  const filteredGroups = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return NAV_GROUPS;
    return NAV_GROUPS.map((group) => ({
      ...group,
      items: group.items.filter((item) => item.label.toLowerCase().includes(q)),
    })).filter((group) => group.items.length > 0);
  }, [query]);

  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onOpenChange(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open, onOpenChange]);

  return (
    <AccentContext.Provider value={settings.accent}>
      <AnimatePresence>
        {open && (
            <>
              <motion.div
                key="backdrop"
                aria-hidden
                className={`${contained ? "absolute" : "fixed"} inset-0 z-50 bg-slate-950/40 backdrop-blur-sm`}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: shouldReduceMotion ? 0.1 : 0.2 }}
                onClick={() => onOpenChange(false)}
              />
              <motion.div
                key="dialog"
                role="dialog"
                aria-modal="true"
                aria-label="Settings"
                className={`${contained ? "absolute" : "fixed"} left-1/2 top-1/2 z-50 w-[calc(100%-2rem)] max-w-2xl`}
                initial={shouldReduceMotion ? { opacity: 0, x: "-50%", y: "-50%" } : { opacity: 0, scale: 0.96, x: "-50%", y: "-50%" }}
                animate={{ opacity: 1, scale: 1, x: "-50%", y: "-50%" }}
                exit={shouldReduceMotion ? { opacity: 0, x: "-50%", y: "-50%" } : { opacity: 0, scale: 0.97, x: "-50%", y: "-50%" }}
                transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
              >
                <div className="flex h-[26rem] overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl dark:border-slate-700 dark:bg-neutral-950">
                  <nav aria-label="Settings sections" data-lenis-prevent className="scrollbar-hide flex w-48 shrink-0 flex-col gap-4 overflow-y-auto border-r border-slate-100 bg-slate-50/60 p-3 dark:border-slate-800 dark:bg-neutral-900/40">
                    <div className="relative">
                      <span className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500">
                        <SearchIcon />
                      </span>
                      <input
                        type="text"
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        placeholder="Search settings"
                        aria-label="Search settings"
                        className={`w-full rounded-lg border border-slate-200 bg-white py-1.5 pl-8 pr-2 text-xs text-slate-700 outline-none transition-colors placeholder:text-slate-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 dark:border-slate-700 dark:bg-neutral-900 dark:text-slate-200 dark:placeholder:text-slate-500 ${styles.ring}`}
                      />
                    </div>

                    {filteredGroups.length === 0 && (
                      <p className="px-2 text-xs text-slate-400 dark:text-slate-500">No settings match &ldquo;{query}&rdquo;.</p>
                    )}

                    {filteredGroups.map((group) => (
                      <div key={group.label}>
                        <p className="px-2 pb-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">
                          {group.label}
                        </p>
                        <div role="tablist" aria-orientation="vertical" className="space-y-0.5">
                          {group.items.map((item) => {
                            const isActive = active === item.id;
                            const Icon = item.icon;
                            return (
                              <button
                                key={item.id}
                                type="button"
                                role="tab"
                                id={`settings-tab-${item.id}`}
                                aria-selected={isActive}
                                aria-controls={`settings-panel-${item.id}`}
                                onClick={() => setActive(item.id)}
                                className={`relative flex w-full items-center gap-2.5 rounded-lg px-2.5 py-1.5 text-left text-sm transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ${styles.ring} ${
                                  isActive ? "text-slate-900 dark:text-white" : "text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                                }`}
                              >
                                {isActive && (
                                  <motion.span
                                    layoutId="settings-nav-highlight"
                                    className="absolute inset-0 -z-10 rounded-lg bg-white shadow-sm dark:bg-neutral-800"
                                    transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 38 }}
                                  />
                                )}
                                <Icon className={`h-4 w-4 shrink-0 ${isActive ? styles.activeIcon : ""}`} />
                                <span className="truncate">{item.label}</span>
                              </button>
                            );
                          })}
                        </div>
                      </div>
                    ))}
                  </nav>

                  <div className="relative flex min-h-0 min-w-0 flex-1 flex-col">
                    <button
                      type="button"
                      onClick={() => onOpenChange(false)}
                      aria-label="Close settings"
                      className="absolute right-4 top-4 z-10 rounded-md p-1 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600 dark:hover:bg-neutral-800 dark:hover:text-slate-300"
                    >
                      <CloseIcon />
                    </button>

                    <div data-lenis-prevent className="scrollbar-hide min-h-0 flex-1 overflow-y-auto px-6 pb-6 pt-5">
                      <div className="flex items-center justify-between gap-3 pr-7">
                        <h2 className="text-base font-semibold text-slate-900 dark:text-white">{activeItem?.label ?? "Settings"}</h2>
                        <SaveIndicator state={saveState} />
                      </div>
                      <motion.div
                        key={active}
                        id={`settings-panel-${active}`}
                        role="tabpanel"
                        aria-labelledby={`settings-tab-${active}`}
                        initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: 4 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.15 }}
                        className="mt-3"
                      >
                        {active === "general" && <GeneralPane settings={settings} update={update} />}
                        {active === "profile" && <ProfilePane settings={settings} update={update} />}
                        {active === "privacy" && <PrivacyPane settings={settings} update={update} />}
                        {active !== "general" && active !== "profile" && active !== "privacy" && activeItem && (
                          <EmptyPane label={activeItem.label} icon={activeItem.icon} />
                        )}
                      </motion.div>
                    </div>
                  </div>
                </div>
              </motion.div>
            </>
          )}
        </AnimatePresence>
    </AccentContext.Provider>
  );
}

"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Figma, Spotify, type Icon as GrommetIcon } from "grommet-icons";
import {
  PlayIcon as PhPlay,
  PauseIcon as PhPause,
  ArrowUpRightIcon as PhArrowUpRight,
  LinkIcon as PhLink,
  PlusIcon as PhPlus,
  CheckIcon as PhCheck,
  ThumbsUpIcon as PhThumbsUp,
  ThumbsDownIcon as PhThumbsDown,
  DevicesIcon as PhDevices,
  CircleNotchIcon as PhCircleNotch,
} from "@phosphor-icons/react";

const EASE = [0.22, 1, 0.36, 1] as const;
const CONNECTION_TTL_MS = 30 * 24 * 60 * 60 * 1000;

function connectionStorageKey(appName: string) {
  return `app-widget:connected:${appName}`;
}

function readPersistedConnection(appName: string): boolean {
  if (typeof window === "undefined") return false;
  try {
    const stored = window.localStorage.getItem(connectionStorageKey(appName));
    if (!stored) return false;
    const lastUsed = Number(stored);
    if (Number.isNaN(lastUsed) || Date.now() - lastUsed > CONNECTION_TTL_MS) {
      window.localStorage.removeItem(connectionStorageKey(appName));
      return false;
    }
    return true;
  } catch {
    return false;
  }
}

function touchPersistedConnection(appName: string) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(connectionStorageKey(appName), String(Date.now()));
  } catch {
    // Storage unavailable (e.g. private browsing): connection just won't persist across visits.
  }
}

