function AppWidgetHeaderBar({ appName, headerAction }: { appName: string; headerAction?: AppWidgetHeaderAction }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [selectedDevice, setSelectedDevice] = useState(() => (headerAction?.kind === "devices" ? headerAction.devices[0] : ""));
  const [copied, setCopied] = useState(false);
  const menuButtonRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const copyTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (copyTimeoutRef.current) window.clearTimeout(copyTimeoutRef.current);
    };
  }, []);

  useEffect(() => {
    if (!menuOpen) return;
    function onPointerDown(e: PointerEvent) {
      if (menuRef.current?.contains(e.target as Node) || menuButtonRef.current?.contains(e.target as Node)) {
        return;
      }
      setMenuOpen(false);
    }
    function onKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") {
        setMenuOpen(false);
        menuButtonRef.current?.focus();
      }
    }
    window.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [menuOpen]);

  return (
    <div className="flex items-center justify-between border-b border-slate-100 px-4 py-2.5 dark:border-slate-800">
      <span className="text-xs font-medium uppercase tracking-wide text-slate-400 dark:text-slate-500">From {appName}</span>
      {headerAction && (
        <div className="relative">
          {headerAction.kind === "devices" ? (
            <>
              <button
                ref={menuButtonRef}
                type="button"
                aria-haspopup="menu"
                aria-expanded={menuOpen}
                onClick={() => setMenuOpen((v) => !v)}
                className="flex items-center gap-1.5 rounded-full px-2 py-1 text-xs font-medium text-slate-500 transition-colors duration-150 hover:bg-slate-100 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-slate-200"
              >
                <DevicesIcon />
                Devices
              </button>
              <AnimatePresence>
                {menuOpen && (
                  <motion.div
                    ref={menuRef}
                    role="menu"
                    aria-label="Playback devices"
                    initial={{ opacity: 0, scale: 0.95, y: -4 }}
                    animate={{ opacity: 1, scale: 1, y: 0 }}
                    exit={{ opacity: 0, scale: 0.95, y: -4 }}
                    transition={{ duration: 0.15, ease: EASE }}
                    className="absolute right-0 top-full z-10 mt-1.5 min-w-40 rounded-xl border border-slate-200 bg-white p-1 shadow-lg dark:border-slate-700 dark:bg-neutral-900"
                  >
                    {headerAction.devices.map((device) => (
                      <button
                        key={device}
                        type="button"
                        role="menuitemradio"
                        aria-checked={device === selectedDevice}
                        onClick={() => {
                          setSelectedDevice(device);
                          setMenuOpen(false);
                          menuButtonRef.current?.focus();
                        }}
                        className="flex w-full items-center justify-between rounded-lg px-2.5 py-1.5 text-left text-xs text-slate-600 transition-colors duration-100 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800"
                      >
                        {device}
                        {device === selectedDevice && <CheckIcon />}
                      </button>
                    ))}
                  </motion.div>
                )}
              </AnimatePresence>
            </>
          ) : (
            <button
              type="button"
              aria-label={copied ? "Link copied" : (headerAction.label ?? "Copy link")}
              onClick={() => {
                setCopied(true);
                if (copyTimeoutRef.current) window.clearTimeout(copyTimeoutRef.current);
                copyTimeoutRef.current = window.setTimeout(() => setCopied(false), 1600);
              }}
              className="flex items-center gap-1.5 rounded-full px-2 py-1 text-xs font-medium text-slate-500 transition-colors duration-150 hover:bg-slate-100 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-slate-200"
            >
              {copied ? <CheckIcon /> : <LinkIcon />}
              {copied ? "Copied" : (headerAction.label ?? "Copy link")}
            </button>
          )}
        </div>
      )}
    </div>
  );
}

