function AppWidgetDemoBody({
  resolved,
  shouldReduceMotion,
  app,
  hero,
  items,
  resultKind = "audio",
  addLabel = "Add to library",
  addedLabel = "Added to library",
}: {
  resolved: boolean;
  shouldReduceMotion: boolean | null;
  app: AppWidgetApp;
  hero: AppWidgetHero;
  items: AppWidgetItem[];
  resultKind?: "audio" | "document";
  addLabel?: string;
  addedLabel?: string;
}) {
  const [added, setAdded] = useState(false);
  const [activeId, setActiveId] = useState<string | null>(null);

  const listVariants = {
    hidden: {},
    show: { transition: { staggerChildren: shouldReduceMotion ? 0 : 0.05, delayChildren: shouldReduceMotion ? 0 : 0.05 } },
  };
  const itemVariants = {
    hidden: shouldReduceMotion ? { opacity: 1, y: 0 } : { opacity: 0, y: 8 },
    show: { opacity: 1, y: 0, transition: { duration: 0.25, ease: EASE } },
  };

  const isHeroActive = activeId === "hero";
  const heroIdleLabel = resultKind === "audio" ? "Play" : "Open";
  const heroActiveLabel = resultKind === "audio" ? "Pause" : "Opened";

  return (
    <>
      <div className="p-4">
        <AnimatePresence mode="wait">
          {resolved ? (
            <motion.div
              key="hero-resolved"
              initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: 4 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, ease: EASE }}
              className="flex items-center gap-3"
            >
              <div className={`flex h-16 w-16 shrink-0 items-center justify-center rounded-lg bg-gradient-to-br text-2xl ${hero.gradient}`} aria-hidden>
                {hero.icon}
              </div>
              <div className="min-w-0 flex-1">
                <h3 className="truncate text-[15px] font-semibold text-slate-900 dark:text-white">{hero.title}</h3>
                <p className="mt-0.5 truncate text-sm text-slate-500 dark:text-slate-400">{hero.subtitle}</p>
              </div>
              <button
                type="button"
                aria-pressed={added}
                aria-label={added ? addedLabel : addLabel}
                onClick={() => setAdded((v) => !v)}
                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-slate-300 text-slate-500 transition-colors duration-150 hover:border-slate-400 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-600 dark:text-slate-400 dark:hover:border-slate-500 dark:hover:text-slate-200"
              >
                {added ? <CheckIcon /> : <PlusIcon />}
              </button>
              {resultKind === "audio" ? (
                <button
                  type="button"
                  aria-pressed={isHeroActive}
                  aria-label={`${isHeroActive ? heroActiveLabel : heroIdleLabel} ${hero.title}`}
                  onClick={() => setActiveId((prev) => (prev === "hero" ? null : "hero"))}
                  className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full transition-transform duration-150 hover:scale-105 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${app.accentButton}`}
                >
                  {isHeroActive ? <PauseIcon /> : <PlayIcon />}
                </button>
              ) : (
                <button
                  type="button"
                  aria-pressed={isHeroActive}
                  aria-label={`${isHeroActive ? heroActiveLabel : heroIdleLabel} ${hero.title}`}
                  onClick={() => setActiveId((prev) => (prev === "hero" ? null : "hero"))}
                  className={`flex h-9 shrink-0 items-center gap-1.5 rounded-full px-3.5 text-xs font-semibold transition-transform duration-150 hover:scale-105 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${app.accentButton}`}
                >
                  {isHeroActive ? <CheckIcon /> : <ArrowUpRightIcon />}
                  {isHeroActive ? heroActiveLabel : heroIdleLabel}
                </button>
              )}
            </motion.div>
          ) : (
            <motion.div key="hero-loading" exit={{ opacity: 0 }} transition={{ duration: 0.2 }} className="flex items-center gap-3">
              <ShimmerBlock className="h-16 w-16 shrink-0" />
              <div className="flex min-w-0 flex-1 flex-col gap-2">
                <ShimmerBlock className="h-3.5 w-2/3" />
                <ShimmerBlock className="h-3 w-1/3" />
              </div>
              <ShimmerBlock className="h-8 w-8 shrink-0 rounded-full" />
              <ShimmerBlock className={resultKind === "audio" ? "h-9 w-9 shrink-0 rounded-full" : "h-9 w-20 shrink-0 rounded-full"} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <div className="border-t border-slate-100 dark:border-slate-800">
        <AnimatePresence mode="wait">
          {resolved ? (
            <motion.ul key="items-resolved" variants={listVariants} initial="hidden" animate="show" className="divide-y divide-slate-100 dark:divide-slate-800">
              {items.map((item) => {
                const isActive = activeId === item.id;
                const itemIdleLabel = resultKind === "audio" ? "Preview" : "Open";
                const itemActiveLabel = resultKind === "audio" ? "Pause" : "Opened";
                return (
                  <motion.li key={item.id} variants={itemVariants} className={`flex items-center gap-3 px-4 py-2.5 transition-colors duration-150 ${isActive ? "bg-slate-50 dark:bg-slate-900" : ""}`}>
                    <div className={`relative flex h-9 w-9 shrink-0 items-center justify-center overflow-hidden rounded-md bg-gradient-to-br text-base ${item.swatch}`} aria-hidden>
                      {item.icon && !isActive && <span>{item.icon}</span>}
                      {isActive && (
                        <span className="absolute inset-0 flex items-center justify-center bg-black/45 text-white">
                          {resultKind === "audio" ? <EqualizerBars active={isActive} /> : <CheckIcon />}
                        </span>
                      )}
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className={`truncate text-sm font-medium ${isActive ? "text-emerald-700 dark:text-emerald-400" : "text-slate-800 dark:text-slate-100"}`}>{item.title}</p>
                      <p className="truncate text-xs text-slate-500 dark:text-slate-400">{item.subtitle}</p>
                    </div>
                    {item.meta && <span className="shrink-0 text-xs text-slate-400 dark:text-slate-500">{item.meta}</span>}
                    <button
                      type="button"
                      aria-pressed={isActive}
                      aria-label={`${isActive ? itemActiveLabel : itemIdleLabel} ${item.title}`}
                      onClick={() => setActiveId((prev) => (prev === item.id ? null : item.id))}
                      className={`flex shrink-0 items-center gap-1.5 rounded-full border px-2.5 py-1 text-xs font-medium transition-colors duration-150 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                        isActive
                          ? "border-emerald-600 bg-emerald-600 text-white"
                          : "border-slate-300 text-slate-600 hover:border-slate-400 dark:border-slate-600 dark:text-slate-300 dark:hover:border-slate-500"
                      }`}
                    >
                      {resultKind === "audio" ? (
                        isActive ? <PauseIcon /> : <PlayIcon />
                      ) : isActive ? (
                        <CheckIcon />
                      ) : (
                        <ArrowUpRightIcon />
                      )}
                      {isActive ? itemActiveLabel : itemIdleLabel}
                    </button>
                  </motion.li>
                );
              })}
            </motion.ul>
          ) : (
            <motion.div key="items-loading" exit={{ opacity: 0 }} transition={{ duration: 0.2 }} className="divide-y divide-slate-100 dark:divide-slate-800">
              {items.slice(0, 3).map((item) => (
                <div key={item.id} className="flex items-center gap-3 px-4 py-2.5">
                  <ShimmerBlock className="h-9 w-9 shrink-0" />
                  <div className="flex min-w-0 flex-1 flex-col gap-1.5">
                    <ShimmerBlock className="h-3 w-3/5" />
                    <ShimmerBlock className="h-2.5 w-2/5" />
                  </div>
                  <ShimmerBlock className="h-6 w-16 shrink-0 rounded-full" />
                </div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </>
  );
}

function AppWidgetAuthGate({ app, connecting, onConnect }: { app: AppWidgetApp; connecting: boolean; onConnect: () => void }) {
  const shouldReduceMotion = useReducedMotion();
  return (
    <div className="flex flex-col items-center gap-3 px-6 py-10 text-center">
      <AppIdentityMark app={app} className="h-11 w-11 text-base" />
      <div>
        <p className="text-sm font-semibold text-slate-900 dark:text-white">Sign in to {app.name}</p>
        <p className="mt-1 text-xs text-slate-500 dark:text-slate-400">Connect your account to see results here.</p>
      </div>
      <motion.button
        type="button"
        disabled={connecting}
        onClick={onConnect}
        aria-label={connecting ? "Connecting…" : app.loginUrl ? `Sign in to ${app.name} (opens in a new tab)` : `Sign in to ${app.name}`}
        whileHover={connecting || shouldReduceMotion ? undefined : { scale: 1.03 }}
        whileTap={connecting || shouldReduceMotion ? undefined : { scale: 0.97 }}
        className={`mt-1 flex items-center gap-2 rounded-full px-4 py-2 text-sm font-semibold transition-opacity duration-150 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 disabled:cursor-not-allowed disabled:opacity-70 ${app.accentButton}`}
      >
        {connecting && <SpinnerIcon />}
        {connecting ? "Connecting…" : `Sign in to ${app.name}`}
      </motion.button>
      {app.loginUrl && !connecting && <p className="text-[11px] text-slate-400 dark:text-slate-500">Opens {app.name}&rsquo;s real sign-in in a new tab.</p>}
    </div>
  );
}

function subscribeNever() {
  return () => {};
}

function getServerConnectionSnapshot() {
  return false;
}

export function AppWidget(props: AppWidgetProps) {
  const { app, headerAction } = props;
  const isLive = props.mode === "live";
  const shouldReduceMotion = useReducedMotion();
  // Reading localStorage safely across server/client (no hydration mismatch) is exactly
  // what useSyncExternalStore is for: the server snapshot always renders the sign-in gate.
  const persistedConnected = useSyncExternalStore(subscribeNever, () => readPersistedConnection(app.name), getServerConnectionSnapshot);
  const [connectedByUser, setConnectedByUser] = useState(false);
  const connected = connectedByUser || persistedConnected;
  const [connecting, setConnecting] = useState(false);
  const [timerResolved, setTimerResolved] = useState(false);
  const [iframeLoaded, setIframeLoaded] = useState(false);
  const resolved = shouldReduceMotion === true || (isLive ? iframeLoaded : timerResolved);
  const [liked, setLiked] = useState<"up" | "down" | null>(null);
  const connectTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    if (!connected || isLive || shouldReduceMotion) return;
    const timer = window.setTimeout(() => setTimerResolved(true), 1300);
    return () => window.clearTimeout(timer);
  }, [connected, isLive, shouldReduceMotion]);

  useEffect(() => {
    return () => {
      if (connectTimeoutRef.current) window.clearTimeout(connectTimeoutRef.current);
    };
  }, []);

  // A returning visit within the 30-day window refreshes the rolling expiry: only
  // 30 days of disuse (not 30 days since the original sign-in) triggers the gate again.
  useEffect(() => {
    if (persistedConnected) touchPersistedConnection(app.name);
  }, [persistedConnected, app.name]);

  function handleConnect() {
    // Open synchronously, inside the click handler itself: deferring this into the
    // setTimeout below would detach it from the user gesture and popup-blockers would
    // silently swallow it.
    if (app.loginUrl) {
      window.open(app.loginUrl, "_blank", "noopener,noreferrer");
    }
    setConnecting(true);
    connectTimeoutRef.current = window.setTimeout(() => {
      setConnecting(false);
      setConnectedByUser(true);
      touchPersistedConnection(app.name);
    }, 900);
  }

  const resolvedHeaderAction = headerAction ?? (isLive ? undefined : { kind: "devices" as const, devices: ["This device"] });
  const contentReady = connected && resolved;

  return (
    <div className="w-full max-w-md" aria-busy={!contentReady}>
      <span className="sr-only" role="status">
        {!connected ? `Sign in required to use ${app.name}` : resolved ? `${app.name} result loaded` : `Loading result from ${app.name}`}
      </span>

      <div className="mb-2 flex items-center gap-2 px-1">
        <AppIdentityMark app={app} className="h-6 w-6 text-[11px]" />
        <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{app.name}</span>
        <span className="ml-auto flex items-center gap-1">
          <motion.button
            type="button"
            aria-label="Like this result"
            aria-pressed={liked === "up"}
            whileTap={shouldReduceMotion ? undefined : { scale: 0.8 }}
            onClick={() => setLiked((prev) => (prev === "up" ? null : "up"))}
            className={`flex h-6 w-6 items-center justify-center rounded-full transition-colors duration-150 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
              liked === "up" ? "text-emerald-600 dark:text-emerald-400" : "text-slate-400 hover:text-slate-600 dark:text-slate-500 dark:hover:text-slate-300"
            }`}
          >
            <ThumbIcon direction="up" />
          </motion.button>
          <motion.button
            type="button"
            aria-label="Dislike this result"
            aria-pressed={liked === "down"}
            whileTap={shouldReduceMotion ? undefined : { scale: 0.8 }}
            onClick={() => setLiked((prev) => (prev === "down" ? null : "down"))}
            className={`flex h-6 w-6 items-center justify-center rounded-full transition-colors duration-150 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
              liked === "down" ? "text-rose-500 dark:text-rose-400" : "text-slate-400 hover:text-slate-600 dark:text-slate-500 dark:hover:text-slate-300"
            }`}
          >
            <ThumbIcon direction="down" />
          </motion.button>
        </span>
      </div>

      <motion.div
        whileHover={shouldReduceMotion ? undefined : { y: -2 }}
        transition={{ type: "spring", stiffness: 380, damping: 28 }}
        className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-neutral-950"
      >
        <AnimatePresence mode="wait">
          {!connected ? (
            <motion.div key="gate" exit={{ opacity: 0 }} transition={{ duration: 0.2 }}>
              <AppWidgetAuthGate app={app} connecting={connecting} onConnect={handleConnect} />
            </motion.div>
          ) : (
            <motion.div
              key="content"
              initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.25, ease: EASE }}
            >
              <AppWidgetHeaderBar appName={app.name} headerAction={resolvedHeaderAction} />
              {props.mode === "live" ? (
                <AppWidgetLiveBody
                  resolved={resolved}
                  embedUrl={props.embedUrl}
                  embedTitle={props.embedTitle}
                  embedHeight={props.embedHeight}
                  onLoad={() => setIframeLoaded(true)}
                />
              ) : (
                <AppWidgetDemoBody
                  resolved={resolved}
                  shouldReduceMotion={shouldReduceMotion}
                  app={app}
                  hero={props.hero}
                  items={props.items}
                  resultKind={props.resultKind}
                  addLabel={props.addLabel}
                  addedLabel={props.addedLabel}
                />
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </div>
  );
}

